:root{
  --fg-rgb:12,14,32;
  --bg:#f4f4f7;
  --panel:#ffffff;
  --bg-deep:#ffffff;
  --line:rgba(12,14,32,.1);
  --surface:rgba(12,14,32,.022);
  --card:#ffffff;
  --icon-bg:rgba(12,14,32,.035);
  --icon-line:rgba(12,14,32,.16);
  --chip:rgba(12,14,32,.06);
  --text:rgba(12,14,32,.92);
  --text-dim:rgba(12,14,32,.62);
  --muted:#6b6d7c;
  --accent:#f76b00;
  --accent-bg:rgba(247,107,0,.08);
  --accent-muted:rgba(214,90,0,.85);
  --accent-icon-bg:rgba(247,107,0,.06);
  --accent-icon-line:rgba(247,107,0,.32);
  --accent-fill:#fff4ec;
  --accent-hi:#ff8a33;
  --card-solid:#ffffff;
  --hatch-on:rgba(247,107,0,.2);
  --top-bg:rgba(244,244,247,.82);
  --success:#0f9a62;
  --danger:#d93a40;
  --shimmer-hi:#0c0e20;
  --desk:#ffffff;
  --code-k:#bf5600;--code-s:#12805a;--code-f:#2a2f73;--code-ty:#7448d0;--code-c:rgba(12,14,32,.42);
  --cursor-fill:#0c0e20;--cursor-stroke:#ffffff;
  color-scheme:light;
  --ease:cubic-bezier(.22,1,.36,1);
  --sans:"Inter",ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  --mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  box-sizing:border-box;
  padding-top:env(safe-area-inset-top,0px);
  padding-bottom:env(safe-area-inset-bottom,0px);
}
@media (prefers-color-scheme: dark){ :root:not([data-theme="light"]){
  --fg-rgb:255,255,255;
  --bg:#080918;
  --panel:#080918;
  --bg-deep:#070e1d;
  --line:rgba(255,255,255,.08);
  --surface:rgba(255,255,255,.02);
  --card:rgba(255,255,255,.01);
  --icon-bg:rgba(255,255,255,.04);
  --icon-line:rgba(255,255,255,.17);
  --chip:rgba(255,255,255,.07);
  --text:rgba(255,255,255,.95);
  --text-dim:rgba(255,255,255,.5);
  --muted:#9e9e9e;
  --accent:#ff850d;
  --accent-bg:rgba(255,133,13,.09);
  --accent-muted:rgba(255,133,13,.51);
  --accent-icon-bg:rgba(188,138,88,.04);
  --accent-icon-line:rgba(255,162,13,.17);
  --accent-fill:#1e1417;
  --accent-hi:#ff9633;
  --card-solid:#0a0b1a;
  --hatch-on:rgba(255,133,13,.16);
  --top-bg:rgba(8,9,24,.82);
  --success:#3ecf8e;
  --danger:#ff5a5f;
  --shimmer-hi:#ffffff;
  --desk:#0b0d1f;
  --code-k:#ff9c4a;--code-s:#9bdcb6;--code-f:#d7d9ff;--code-ty:#c4a7ff;--code-c:rgba(255,255,255,.35);
  --cursor-fill:#ffffff;--cursor-stroke:#080918;
  color-scheme:dark;
} }
:root[data-theme="dark"]{
  --fg-rgb:255,255,255;
  --bg:#080918;
  --panel:#080918;
  --bg-deep:#070e1d;
  --line:rgba(255,255,255,.08);
  --surface:rgba(255,255,255,.02);
  --card:rgba(255,255,255,.01);
  --icon-bg:rgba(255,255,255,.04);
  --icon-line:rgba(255,255,255,.17);
  --chip:rgba(255,255,255,.07);
  --text:rgba(255,255,255,.95);
  --text-dim:rgba(255,255,255,.5);
  --muted:#9e9e9e;
  --accent:#ff850d;
  --accent-bg:rgba(255,133,13,.09);
  --accent-muted:rgba(255,133,13,.51);
  --accent-icon-bg:rgba(188,138,88,.04);
  --accent-icon-line:rgba(255,162,13,.17);
  --accent-fill:#1e1417;
  --accent-hi:#ff9633;
  --card-solid:#0a0b1a;
  --hatch-on:rgba(255,133,13,.16);
  --top-bg:rgba(8,9,24,.82);
  --success:#3ecf8e;
  --danger:#ff5a5f;
  --shimmer-hi:#ffffff;
  --desk:#0b0d1f;
  --code-k:#ff9c4a;--code-s:#9bdcb6;--code-f:#d7d9ff;--code-ty:#c4a7ff;--code-c:rgba(255,255,255,.35);
  --cursor-fill:#ffffff;--cursor-stroke:#080918;
  color-scheme:dark;
}
html.theming,html.theming *,html.theming *::before,html.theming *::after{transition:background-color .45s ease,border-color .45s ease,color .45s ease,fill .45s ease,stroke .45s ease,box-shadow .45s ease!important}
*,*::before,*::after{box-sizing:border-box}
html{scroll-padding-top:calc(env(safe-area-inset-top,0px) + 84px);background:var(--bg);scroll-behavior:smooth}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);-webkit-font-smoothing:antialiased;line-height:1.5}
a{color:inherit}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer;padding:0}
button:focus-visible,textarea:focus-visible,a:focus-visible{outline:1px solid var(--accent);outline-offset:2px}
.ms{font-size:20px;line-height:1;display:inline-flex;align-items:center;justify-content:center;width:1em;height:1em;flex:none;color:inherit;user-select:none;overflow:hidden}
.ms svg{width:1em;height:1em;display:block;fill:none;stroke:currentColor;stroke-width:1.75;stroke-linecap:round;stroke-linejoin:round}
.ms.sm{font-size:16px}

/* motion primitives */
.unfold{display:grid;grid-template-rows:0fr;opacity:0;transition:grid-template-rows .55s var(--ease),opacity .4s ease}
.unfold>.uf{min-height:0;overflow:hidden}
.unfold>.uf>*{transform:translateY(-4px);transition:transform .55s var(--ease)}
.unfold.open{grid-template-rows:1fr;opacity:1}
.unfold.open>.uf>*{transform:none}
.fade-swap{transition:opacity .18s ease,transform .18s ease}
.fade-swap.out{opacity:0;transform:translateY(3px)}
.enter{animation:enter .45s var(--ease) both}
@keyframes enter{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}
.icon-in{animation:iconin .35s var(--ease) both}
@keyframes iconin{from{opacity:0;transform:scale(.6)}to{opacity:1;transform:none}}
.morph{transition:height .5s var(--ease);overflow:hidden}

/* page rails */
.rails{padding:0 64px;border-bottom:1px solid var(--line)}
.rails-inner{border-left:1px solid var(--line);border-right:1px solid var(--line);padding:0 48px}
.frame{border-left:1px solid var(--line);border-right:1px solid var(--line);background:var(--bg)}

.mono-tag{display:inline-flex;align-items:center;padding:2px 6px;background:rgba(0,0,0,.03);font-family:var(--mono);font-weight:700;font-size:10px;line-height:1.62;text-transform:uppercase;color:var(--muted);letter-spacing:.02em}
.mono-xs{font-family:var(--mono);font-weight:700;font-size:12px;line-height:1.5;text-transform:uppercase;color:var(--muted)}
.mono-xs.accent{color:var(--accent-muted)}

/* header */
.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:30;display:flex;align-items:center;justify-content:space-between;padding:18px 48px;border-bottom:1px solid var(--line);gap:12px;background:var(--top-bg);-webkit-backdrop-filter:blur(14px) saturate(140%);backdrop-filter:blur(14px) saturate(140%)}
.brand{display:flex;align-items:center;gap:12px;font-weight:600;font-size:16px;letter-spacing:-.32px}
.brand-mark{width:28px;height:28px;border:1px solid var(--accent-icon-line);background:var(--accent-icon-bg);display:grid;place-items:center;color:var(--accent)}
.top-actions{display:flex;gap:8px;align-items:center}
.btn{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;font-weight:600;font-size:14px;letter-spacing:-.14px;border:1px solid var(--line);background:var(--surface);text-decoration:none;transition:border-color .25s ease,background .25s ease,opacity .25s ease,color .25s ease}
.btn:hover{border-color:var(--icon-line)}
.btn.primary{background:var(--accent);border-color:var(--accent);color:#120a02}
.btn[disabled]{opacity:.4;cursor:default}
.sound-btn{display:inline-flex;align-items:center;gap:8px;padding:9px 12px;border:1px solid var(--line);font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted);transition:color .25s,border-color .25s}
.sound-btn:hover{color:var(--text);border-color:var(--icon-line)}
.sound-btn[aria-pressed="true"]{color:var(--accent);border-color:var(--accent-icon-line)}

/* hero */
.hero{display:grid;grid-template-columns:490px 1fr;border-bottom:1px solid var(--line)}
.hero-copy{padding:64px 48px;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:10px}
.h1{margin:0;font-weight:600;font-size:40px;line-height:1.2;letter-spacing:-.4px;background:linear-gradient(160deg,rgb(var(--fg-rgb)) 25%,rgba(var(--fg-rgb),.7) 86%);-webkit-background-clip:text;background-clip:text;color:transparent;max-width:14ch}
.lede{margin:14px 0 0;color:var(--text-dim);font-size:16px;line-height:1.55;max-width:38ch}
.hero-actions{display:flex;gap:10px;margin-top:22px;flex-wrap:wrap}
.hero-stage{position:relative;padding:10px;min-height:320px}
.dots{background-color:var(--bg);background-image:radial-gradient(rgba(var(--fg-rgb),.07) 1px,transparent 1.2px);background-size:6px 6px}
.hero-index{height:100%;display:grid;grid-template-columns:repeat(3,1fr);align-content:center;padding:28px}
.hero-index a{display:flex;gap:12px;align-items:center;padding:10px 14px;border:1px solid var(--line);margin:-1px 0 0 -1px;background:var(--panel);text-decoration:none;font-weight:600;font-size:14px;letter-spacing:-.14px;transition:border-color .3s ease,color .3s ease}
.hero-index a:hover{border-color:var(--accent);color:var(--accent);position:relative;z-index:1}
.hero-index .num{font-family:var(--mono);font-weight:700;font-size:10px;color:var(--muted)}

/* component grid */
.grid{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line)}
.comp{background:var(--bg);display:flex;flex-direction:column;min-width:0}
.comp.wide{grid-column:1/-1}
.comp-head{display:flex;gap:20px;align-items:center;padding:24px 32px;border-bottom:1px solid var(--line);background:var(--surface)}
.ibox{width:40px;height:40px;flex:none;border:1px solid var(--line);display:grid;place-items:center;color:var(--text-dim)}
.ibox.accent{border-color:var(--accent-icon-line);background:var(--accent-icon-bg);color:var(--accent)}
.comp-title{margin:0;font-weight:600;font-size:18px;line-height:1.4;letter-spacing:-.36px}
.comp-desc{margin:2px 0 0;color:var(--muted);font-size:14px;line-height:1.45}
.comp-num{margin-left:auto;align-self:flex-start}
.stage{position:relative;padding:10px;flex:1;min-height:420px;display:flex}
.stage-inner{flex:1;display:flex;align-items:center;justify-content:center;padding:40px 28px;overflow:hidden}
.comp-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px 12px 32px;border-top:1px solid var(--line);flex-wrap:wrap}

/* tabs with a gliding indicator */
.tabs{position:relative;display:flex;border:1px solid var(--line)}
.tabs .ind{position:absolute;top:0;bottom:0;left:0;width:0;background:var(--accent-bg);box-shadow:inset 0 -1px 0 var(--accent);transition:transform .45s var(--ease),width .45s var(--ease);pointer-events:none}
.tabs .ind.no-anim{transition:none}
.tab{position:relative;z-index:1;padding:6px 12px;font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted);border-right:1px solid var(--line);transition:color .3s ease}
.tab:last-of-type{border-right:0}
.tab[aria-selected="true"]{color:var(--accent)}
.tab:hover{color:var(--text)}
.tab[aria-selected="true"]:hover{color:var(--accent)}
.ghost{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted);border:1px solid var(--line);transition:color .25s,border-color .25s}
.ghost:hover{color:var(--text);border-color:var(--icon-line)}

/* hatched node frame */
.hatch{position:relative;padding:10px;background:repeating-linear-gradient(135deg,rgba(var(--fg-rgb),.045) 0 1px,transparent 1px 6px)}
.hatch::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(135deg,var(--hatch-on) 0 1px,transparent 1px 6px);opacity:0;transition:opacity .35s ease;pointer-events:none}
.hatch.on::before{opacity:1}
.hatch>*{position:relative}
.node{display:flex;gap:20px;align-items:center;text-align:left;padding:12px 16px;border:1px solid var(--line);background:var(--card-solid);transition:border-color .3s ease,background-color .3s ease}
.node.on{border-color:var(--accent);background-color:var(--accent-fill)}
.nbox{width:40px;height:40px;flex:none;display:grid;place-items:center;border:1px solid var(--icon-line);background:var(--icon-bg);box-shadow:0 0 0 7px var(--bg-deep);color:var(--text);transition:border-color .3s,color .3s,background-color .3s}
.node.on .nbox{border-color:var(--accent-icon-line);background-color:var(--accent-icon-bg);color:var(--accent)}
.n-title{font-weight:600;font-size:16px;line-height:1.5}
.node.on .n-title{color:var(--accent)}
.panel{width:100%;max-width:420px;background:var(--panel);border:1px solid var(--line)}

/* shimmer text */
.shimmer{background:linear-gradient(90deg,var(--muted) 0%,var(--muted) 40%,var(--shimmer-hi) 50%,var(--muted) 60%,var(--muted) 100%);background-size:250% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:shim 2s linear infinite}
@keyframes shim{from{background-position:100% 0}to{background-position:-50% 0}}

/* 01 loading */
.loader-row{display:flex;align-items:center;gap:16px}
.glyph{width:40px;height:40px;border:1px solid var(--accent-icon-line);background:var(--accent-icon-bg);box-shadow:0 0 0 7px var(--bg-deep);display:grid;place-items:center;flex:none}
.glyph>div{transition:opacity .2s ease,transform .3s var(--ease)}
.glyph>div.out{opacity:0;transform:scale(.7)}
.px-grid{display:grid;grid-template-columns:repeat(4,4px);gap:2px}
.px-grid i{width:4px;height:4px;background:rgba(var(--fg-rgb),.1);animation:px 1.6s ease-in-out infinite;animation-delay:calc(var(--d) * 100ms)}
@keyframes px{0%,100%{background:rgba(var(--fg-rgb),.1)}30%{background:var(--accent)}60%{background:rgba(255,133,13,.3)}}
.dot3{display:flex;gap:4px}
.dot3 i{width:5px;height:5px;background:var(--accent);animation:dot 1.2s ease-in-out infinite;animation-delay:calc(var(--d) * 180ms)}
@keyframes dot{0%,100%{opacity:.2}45%{opacity:1}}
.bars{display:flex;gap:3px;align-items:center;height:18px}
.bars i{width:3px;height:100%;background:var(--accent);transform-origin:center;animation:bar 1.1s ease-in-out infinite;animation-delay:calc(var(--d) * 130ms)}
@keyframes bar{0%,100%{transform:scaleY(.25)}50%{transform:scaleY(1)}}
.scan{position:relative;width:22px;height:22px;display:grid;grid-template-columns:repeat(4,1fr);gap:2px}
.scan i{background:rgba(var(--fg-rgb),.1)}
.scan::after{content:"";position:absolute;left:-3px;right:-3px;height:2px;background:var(--accent);box-shadow:0 0 8px var(--accent);animation:scan 1.8s ease-in-out infinite}
@keyframes scan{0%,100%{top:0}50%{top:20px}}
.loader-text{display:flex;flex-direction:column;gap:2px;min-width:170px}
.loader-label{font-weight:600;font-size:16px}
.elapsed{font-variant-numeric:tabular-nums}

/* 02 thinking */
.think-head{display:flex;align-items:center;gap:14px;width:100%;padding:14px 16px;text-align:left}
.think-head .t{font-weight:600;font-size:15px}
.think-head .chev{margin-left:auto;color:var(--muted);transition:transform .5s var(--ease)}
.think-head[aria-expanded="false"] .chev{transform:rotate(-90deg)}
.trace-box{border-top:1px solid var(--line);padding:6px 0;transition:border-color .4s ease}
.unfold:not(.open)>.uf>.trace-box{border-top-color:transparent}
.trace-item{display:flex;gap:12px;align-items:flex-start;padding:9px 16px;font-size:14px;color:var(--text-dim);transition:color .35s ease}
.trace-item .st{width:16px;height:16px;flex:none;margin-top:2px;display:grid;place-items:center}
.trace-item.done{color:var(--text)}
.trace-item.done .st{color:var(--success)}
.spin{width:10px;height:10px;border:1.5px solid var(--accent);border-top-color:transparent;border-radius:50%;animation:spin .9s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.trace-item .sub{display:block;font-family:var(--mono);font-size:11px;color:var(--muted);text-transform:uppercase;margin-top:2px}
.trace-item code{font-family:var(--mono);font-size:12px;color:var(--text)}
.reason{padding:4px 16px 4px;font-size:14px;line-height:1.6;color:var(--text-dim);border-left:2px solid var(--line);margin:8px 16px}

/* word reveal for streamed text */
.w{opacity:0;filter:blur(4px);transition:opacity .5s ease,filter .5s ease}
.w.in{opacity:1;filter:blur(0)}

/* 03 streaming */
.ask{display:flex;justify-content:flex-end;margin-bottom:14px}
.ask span{background:var(--chip);padding:8px 12px;font-size:14px;max-width:85%}
.answer{font-size:15px;line-height:1.65;color:var(--text)}
.cite{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 4px;margin:0 2px;font-family:var(--mono);font-weight:700;font-size:10px;color:var(--accent);background:var(--accent-bg);border:1px solid var(--accent-icon-line);vertical-align:2px}
.src-row{display:flex;align-items:center;justify-content:space-between;padding:10px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-top:16px}
.stack{display:flex;align-items:center;gap:10px}
.stack .sq{display:flex}
.stack .sq b{width:18px;height:18px;border:1px solid var(--bg);margin-left:-5px;display:grid;place-items:center;font-family:var(--mono);font-size:9px;color:#120a02}
.stack .sq b:first-child{margin-left:0}
.acts{display:flex;gap:2px}
.acts button{width:30px;height:30px;display:grid;place-items:center;color:var(--muted);border:1px solid transparent;transition:color .25s,border-color .25s}
.acts button:hover{color:var(--text);border-color:var(--line)}
.acts button.on{color:var(--accent)}
.fu-label{margin:14px 0 6px}
.fu{display:flex;align-items:center;gap:10px;width:100%;padding:9px 0;border-bottom:1px solid var(--line);font-size:14px;color:var(--text-dim);text-align:left;transition:color .25s ease}
.fu:hover{color:var(--accent)}
.fu .ms{font-size:16px;transition:transform .35s var(--ease)}
.fu:hover .ms{transform:translateX(3px)}

/* 04 approval */
.ap-q{padding:18px 16px 6px;font-weight:600;font-size:16px;line-height:1.4}
.ap-opts{padding:8px 16px 4px;display:flex;flex-direction:column}
.ap-opt{margin-top:-1px;padding:4px}
.ap-opt .node{width:100%;text-align:left;gap:14px;padding:10px 14px}
.ap-opt .key{width:24px;height:24px;flex:none;display:grid;place-items:center;font-family:var(--mono);font-size:11px;font-weight:700;border:1px solid var(--icon-line);color:var(--muted);transition:border-color .3s,color .3s}
.ap-opt .node.on .key{border-color:var(--accent);color:var(--accent)}
.ap-opt .lbl{font-weight:600;font-size:14px}
.ap-opt .hint{display:block;font-family:var(--mono);font-size:11px;font-weight:700;text-transform:uppercase;color:var(--muted);transition:color .3s}
.ap-opt .node.on .hint{color:var(--accent-muted)}
.ap-foot{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-top:1px solid var(--line);margin-top:12px}
.ap-btns{display:flex;gap:8px}
.ap-btns .btn{padding:8px 14px;font-size:13px}
.ap-done{padding:28px 16px;display:flex;flex-direction:column;align-items:flex-start;gap:12px}

/* 05 task rows */
.tk-view{transition:opacity .3s ease}
.tk-view.hide{display:none}
.task{border-bottom:1px solid var(--line)}
.task:last-child{border-bottom:0}
.task-h{display:flex;align-items:center;gap:12px;padding:12px 16px}
.task-n{width:22px;height:22px;flex:none;display:grid;place-items:center;font-family:var(--mono);font-weight:700;font-size:11px;border:1px solid var(--icon-line);color:var(--muted);transition:border-color .35s,color .35s}
.task-n.ok{color:var(--success);border-color:rgba(62,207,142,.4)}
.task-h .tt{font-weight:600;font-size:14px}
.task-h .meta{margin-left:auto}
.sub-row{display:flex;align-items:center;gap:12px;padding:7px 16px 7px 50px;font-size:13px;color:var(--text-dim)}
.sub-row .sl{transition:color .35s ease}
.sub-row.done .sl{color:var(--text)}
.si{display:inline-grid;place-items:center;width:16px;height:16px;flex:none}
.si .ms{font-size:16px}
.sub-row .r{margin-left:auto}
.s-done{color:var(--success)}
.s-fail{color:var(--danger)}
.s-run{color:var(--accent)}
.s-wait{color:var(--muted)}
.pbar{height:2px;background:var(--line);margin:2px 16px 10px 50px;position:relative;overflow:hidden}
.pbar i{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--accent);transition:width .2s linear}
.retry{font-family:var(--mono);font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text);border:1px solid var(--line);padding:2px 6px;transition:border-color .25s,color .25s}
.retry:hover{border-color:var(--accent);color:var(--accent)}
.caps{display:flex;flex-wrap:wrap;gap:8px;padding:16px}
.cap{display:inline-flex;align-items:center;gap:8px;padding:6px 10px;border:1px solid var(--line);background:var(--card);font-size:13px;font-weight:600;transition:border-color .35s,background-color .35s,color .35s}
.cap.run{border-color:var(--accent);background-color:var(--accent-bg);color:var(--accent)}
.cap .si .ms{font-size:15px}

/* 06 prompt bar */
.composer{width:100%;max-width:460px;border:1px solid var(--line);background:var(--panel);position:relative;transition:border-color .3s ease}
.composer.focus{border-color:var(--icon-line)}
.chips{display:flex;flex-wrap:wrap;gap:6px;padding:12px 14px 0}
.chips:empty{display:none}
.ctx{display:inline-flex;align-items:center;gap:6px;padding:3px 8px;background:var(--chip);font-size:12px;font-weight:600;animation:iconin .35s var(--ease) both;transition:opacity .2s ease,transform .2s ease}
.ctx.leaving{opacity:0;transform:scale(.85)}
.ctx .ms{font-size:14px;color:var(--accent)}
.ctx button{color:var(--muted);font-size:13px;line-height:1}
.ta{display:block;width:100%;min-height:72px;resize:none;border:0;outline:0;background:transparent;color:var(--text);font:inherit;font-size:15px;line-height:1.5;padding:14px}
.ta::placeholder{color:var(--muted)}
.ta:focus-visible{outline:0}
#c6 .stage-inner{align-items:flex-end;padding-bottom:64px}
.comp-bar{display:flex;align-items:center;gap:6px;padding:8px 10px;border-top:1px solid var(--line)}
.ib{width:32px;height:32px;display:grid;place-items:center;color:var(--muted);border:1px solid var(--line);transition:color .25s,border-color .25s,background-color .25s}
.ib:hover{color:var(--text);border-color:var(--icon-line)}
.ib.rec{color:var(--accent);border-color:var(--accent);background-color:var(--accent-bg)}
.ib.rec .ms{animation:dot 1.2s ease-in-out infinite}
.model{display:inline-flex;align-items:center;gap:4px;height:32px;padding:0 8px;border:1px solid var(--line);font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted);transition:color .25s}
.model:hover{color:var(--text)}
.send{margin-left:auto;width:32px;height:32px;display:grid;place-items:center;background:var(--accent);color:#120a02;transition:opacity .3s ease,transform .3s var(--ease)}
.send[disabled]{opacity:.35;cursor:default}
.send:not([disabled]):active{transform:translateY(-2px)}
.menu{position:absolute;left:10px;right:10px;bottom:calc(100% + 6px);background:var(--panel);border:1px solid var(--icon-line);z-index:5;opacity:0;visibility:hidden;transform:translateY(6px) scale(.985);transform-origin:bottom center;transition:opacity .22s ease,transform .35s var(--ease),visibility 0s linear .35s}
.menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .22s ease,transform .35s var(--ease),visibility 0s}
.menu-h{padding:8px 12px;border-bottom:1px solid var(--line)}
.menu-i{display:flex;align-items:center;gap:10px;width:100%;padding:9px 12px;font-size:13px;text-align:left;color:var(--text-dim);transition:background-color .2s ease,color .2s ease}
.menu-i .k{margin-left:auto}
.menu-i.act,.menu-i:hover{background-color:var(--accent-bg);color:var(--accent)}
.menu-i .ms{font-size:16px}
.composer.compact{display:flex;flex-wrap:wrap;align-items:flex-end}
.composer.compact .chips{width:100%}
.composer.compact .ta{flex:1;width:auto;min-height:44px;padding:11px 14px}
.composer.compact .comp-bar{border-top:0;padding:6px 8px}
.composer.compact .model,.composer.compact .at-btn{display:none}

/* ---------- batch two ---------- */
.panel.wide{max-width:none}
.cap-row{display:flex;align-items:center;gap:10px}
.mention{display:inline-flex;align-items:center;padding:0 6px;background:var(--accent-bg);color:var(--accent);font-weight:600;border:1px solid var(--accent-icon-line)}
.kbd{display:inline-flex;align-items:center;padding:1px 6px;border:1px solid var(--line);font-family:var(--mono);font-weight:700;font-size:10px;color:var(--muted);text-transform:uppercase}
.pill{display:inline-flex;align-items:center;gap:6px;padding:2px 8px;font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;border:1px solid var(--line);color:var(--muted);white-space:nowrap}
.pill i{width:6px;height:6px;background:currentColor}
.pill.todo{color:var(--muted)}
.pill.prog{color:var(--accent);border-color:var(--accent-icon-line);background:var(--accent-bg)}
.pill.done{color:var(--success);border-color:rgba(62,207,142,.3);background:rgba(62,207,142,.06)}
.tag{display:inline-flex;align-items:center;padding:1px 7px;background:var(--chip);font-size:12px;font-weight:500;color:var(--text);white-space:nowrap}
.tag.more{color:var(--muted)}
.in-tabs{position:relative;display:flex;gap:0;border-bottom:1px solid var(--line)}
.in-tabs .ul{position:absolute;bottom:-1px;left:0;height:1px;width:0;background:var(--accent);transition:transform .45s var(--ease),width .45s var(--ease)}
.in-tab{padding:12px 14px;font-size:13px;font-weight:600;color:var(--muted);transition:color .3s}
.in-tab[aria-selected="true"]{color:var(--text)}
.in-tab:hover{color:var(--text)}
.in-tab .ct{font-family:var(--mono);font-size:10px;font-weight:700;color:var(--muted);margin-left:6px}
.in-tab[aria-selected="true"] .ct{color:var(--accent)}

/* 07 tool chips */
.tc-sum{display:flex;align-items:center;gap:12px;width:100%;padding:14px 16px;text-align:left}
.tc-sum .t{font-weight:600;font-size:14px}
.tc-sum .chev{margin-left:auto;color:var(--muted);transition:transform .5s var(--ease)}
.tc-sum[aria-expanded="false"] .chev{transform:rotate(-90deg)}
.tc-stack{display:flex}
.tc-stack span{width:24px;height:24px;display:grid;place-items:center;border:1px solid var(--icon-line);background:var(--panel);margin-left:-6px;color:var(--text-dim)}
.tc-stack span:first-child{margin-left:0}
.tc-list{display:flex;flex-wrap:wrap;gap:6px;padding:12px 16px 16px;border-top:1px solid var(--line)}
.tc-list.stacked{flex-direction:column;flex-wrap:nowrap}
.tchip{display:inline-flex;align-items:center;gap:8px;padding:6px 10px;border:1px solid var(--line);background:var(--card);font-size:13px;color:var(--text-dim);transition:border-color .35s,color .35s,background-color .35s}
.tc-list.stacked .tchip{width:100%}
.tchip.run{border-color:var(--accent-icon-line);color:var(--text);background-color:var(--accent-bg)}
.tchip.done{color:var(--text)}
.tchip .si .ms{font-size:15px}
.tchip code{font-family:var(--mono);font-size:12px;color:var(--text)}
.tchip .meta{margin-left:auto;padding-left:8px;font-family:var(--mono);font-size:11px;font-weight:700}
.plus{color:var(--success)}.minus{color:var(--danger)}
.tc-msg{font-size:14px;color:var(--text-dim);padding:2px 0}

/* 08 chat */
.chat{display:flex;flex-direction:column;height:400px}
.msgs{flex:1;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:14px;scroll-behavior:smooth;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.m-user{align-self:flex-end;max-width:82%;background:var(--chip);padding:8px 12px;font-size:14px}
.m-agent{display:flex;flex-direction:column;gap:8px;max-width:92%}
.rchips{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.rchip{display:inline-flex;align-items:center;gap:6px;padding:2px 8px;border:1px solid var(--line);font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--muted)}
.rchip .ms{font-size:13px;color:var(--accent)}
.m-text{font-size:14px;line-height:1.6}
.chat-in{display:flex;align-items:center;gap:8px;padding:10px;border-top:1px solid var(--line)}
.chat-in input{flex:1;min-width:0;background:transparent;border:0;outline:0;color:var(--text);font:inherit;font-size:14px;padding:6px}
.chat-in input::placeholder{color:var(--muted)}

/* 09 recommendation */
.rec-head{display:flex;gap:16px;align-items:flex-start;padding:18px 16px 12px}
.rec-q{font-weight:600;font-size:16px;line-height:1.4}
.rec-d{margin-top:4px;font-size:14px;color:var(--text-dim);line-height:1.5}
.conf{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-top:1px solid var(--line)}
.segs{display:flex;gap:3px}
.segs i{width:22px;height:6px;background:var(--line);transition:background-color .35s ease}
.segs i.on{background:var(--accent)}
.alt-tog{display:flex;align-items:center;gap:8px;width:100%;padding:12px 16px;border-top:1px solid var(--line);font-size:13px;font-weight:600;color:var(--text-dim);text-align:left;transition:color .25s}
.alt-tog:hover{color:var(--text)}
.alt-tog .chev{margin-left:auto;transition:transform .5s var(--ease)}
.alt-tog[aria-expanded="true"] .chev{transform:rotate(180deg)}
.alt{display:flex;align-items:center;gap:12px;padding:10px 16px;font-size:13px;color:var(--text-dim);border-top:1px solid var(--line)}
.alt .pill{margin-left:auto}
.rec-foot{display:flex;justify-content:flex-end;gap:8px;padding:14px 16px;border-top:1px solid var(--line)}
.rec-foot .btn{padding:8px 14px;font-size:13px}

/* 10 context cards */
.ctx-list{display:flex;flex-direction:column;padding:8px}
.ctx-card{width:100%;text-align:left;margin-top:-1px}
.ctx-card .node{flex-direction:column;align-items:stretch;gap:8px;padding:12px 14px}
.ctx-top{display:flex;align-items:center;gap:10px}
.ctx-top .t{font-weight:600;font-size:14px}
.ctx-top .mono-xs{margin-left:auto;font-size:11px}
.ctx-body{font-size:13px;line-height:1.55;color:var(--text-dim)}
.ctx-src{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted)}
.ctx-src .kbd{color:var(--text)}
.ctx-card .node.on .kbd{border-color:var(--accent-icon-line);color:var(--accent)}

/* 11 diff table and 12 records share the grid table */
.gt{overflow-x:auto;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.gt-in{min-width:640px}
.gt-row{display:grid;align-items:center;border-bottom:1px solid var(--line);font-size:13px;position:relative;background:var(--panel);transition:background-color .3s ease}
.gt-row>div{padding:10px 14px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.gt-head{position:sticky;top:0;z-index:2}
.gt-head>div{font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted)}
.gt-body .gt-row:hover{background:rgba(var(--fg-rgb),.015)}
.diff-cols{grid-template-columns:minmax(160px,1.3fr) 1fr 1fr 1fr}
.scan-bar{position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--accent);opacity:0;transition:opacity .25s}
.gt-row.scanning{background:var(--accent-bg)}
.gt-row.scanning .scan-bar{opacity:1}
.cell-diff{display:inline-flex;align-items:center;gap:6px;max-width:100%}
.old{text-decoration:line-through;color:var(--danger);background:rgba(255,90,95,.08);padding:0 4px;transition:opacity .3s,max-width .45s var(--ease);max-width:200px;overflow:hidden;white-space:nowrap}
.new{color:var(--success);background:rgba(62,207,142,.08);padding:0 4px;opacity:0;transform:translateX(-4px);transition:opacity .35s,transform .45s var(--ease)}
.cell-diff.show .new{opacity:1;transform:none}
.cell-diff.accepted .old{opacity:0;max-width:0;padding:0}
.cell-diff.accepted .new{background:transparent;color:var(--text)}
.cell-diff.rejected .new{opacity:0;max-width:0;padding:0}
.cell-diff.rejected .old{text-decoration:none;color:var(--text);background:transparent}
.diff-foot{display:flex;align-items:center;justify-content:space-between;padding:12px 14px;gap:10px;flex-wrap:wrap}
.diff-foot .btn{padding:8px 14px;font-size:13px}
.diff-title{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line);font-weight:600;font-size:14px}

.rec-cols{grid-template-columns:40px minmax(200px,1.5fr) minmax(200px,1.4fr) 140px 170px minmax(160px,1fr)}
.rec-scroll{max-height:440px;overflow:auto;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.rec-scroll .gt-in{min-width:960px}
.sortable{display:inline-flex;align-items:center;gap:4px;cursor:pointer;transition:color .25s}
.sortable:hover,.sortable.on{color:var(--text)}
.sortable .ms{font-size:14px;opacity:0;transition:opacity .25s,transform .35s var(--ease)}
.sortable.on .ms{opacity:1}
.sortable.desc .ms{transform:rotate(180deg)}
.co{display:flex;align-items:center;gap:10px}
.av{width:24px;height:24px;flex:none;display:grid;place-items:center;font-family:var(--mono);font-weight:700;font-size:11px;border:1px solid var(--icon-line);background:var(--icon-bg)}
.co b{font-weight:600}
.co span{color:var(--muted)}
.tags{display:flex;gap:4px}
.strength{display:flex;align-items:center;gap:8px}
.strength .segs i{width:10px;height:6px}
.strength .segs.s4 i{background:var(--success)}
.strength .segs.s0 i,.strength .segs i.off{background:var(--line)}
.lnk{color:var(--text-dim);text-decoration:none;border-bottom:1px solid var(--line);transition:color .25s,border-color .25s}
.lnk:hover{color:var(--accent);border-color:var(--accent)}
.cb{width:14px;height:14px;border:1px solid var(--icon-line);display:grid;place-items:center;transition:background-color .2s,border-color .2s;color:#120a02}
.cb .ms{font-size:12px;opacity:0;transition:opacity .2s}
.cb.on{background:var(--accent);border-color:var(--accent)}
.cb.on .ms{opacity:1}
.gt-row.sel{background:var(--accent-bg)}
.rec-foot-row{display:grid;font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted)}
.rec-foot-row>div{padding:10px 14px}

/* 13 filter table */
.chips-bar{display:flex;flex-wrap:wrap;gap:6px;padding:14px}
.fchip{display:inline-flex;align-items:center;gap:8px;padding:6px 10px;border:1px solid var(--line);font-size:13px;font-weight:600;color:var(--text-dim);transition:border-color .3s,color .3s,background-color .3s}
.fchip .n{font-family:var(--mono);font-size:10px;font-weight:700;color:var(--muted);transition:color .3s}
.fchip.on{border-color:var(--accent);color:var(--accent);background-color:var(--accent-bg)}
.fchip.on .n{color:var(--accent)}
.ft-cols{grid-template-columns:minmax(160px,1.6fr) 84px 140px minmax(100px,1fr)}
#c13 .gt-in{min-width:520px}
.ft-empty{padding:28px 14px;text-align:center;color:var(--muted);font-size:13px}

/* 14 sidebar */
.sb-wrap{display:flex;width:100%;max-width:420px;height:456px;border:1px solid var(--line);background:var(--panel)}
.sb{position:relative;width:250px;flex:none;border-right:1px solid var(--line);display:flex;flex-direction:column;transition:width .5s var(--ease);overflow:hidden}
.sb.mini{width:58px}
.sb-ws{display:flex;align-items:center;gap:10px;padding:12px;border-bottom:1px solid var(--line);white-space:nowrap}
.sb-ws .av{border-color:var(--accent-icon-line);background:var(--accent-icon-bg);color:var(--accent)}
.sb-ws .t{font-weight:600;font-size:14px}
.sb-tog{margin-left:auto}
.sb-list{position:relative;flex:1;padding:8px;overflow:hidden}
.sb-hl{position:absolute;left:8px;right:8px;top:0;height:0;background:rgba(var(--fg-rgb),.04);opacity:0;transition:transform .35s var(--ease),height .35s var(--ease),opacity .2s;pointer-events:none}
.sb-it{position:relative;display:flex;align-items:center;gap:12px;width:100%;padding:8px 9px;font-size:13px;font-weight:500;color:var(--text-dim);text-align:left;white-space:nowrap;transition:color .25s}
.sb-it:hover{color:var(--text)}
.sb-it.act{color:var(--accent)}
.sb-it.act::before{content:"";position:absolute;left:-8px;top:6px;bottom:6px;width:2px;background:var(--accent)}
.sb-it .lbl,.sb-ws .t,.sb-sec .lbl,.sb-inv,.sb-up .lbl,.sb-it .ct{transition:opacity .3s ease}
.sb.mini .lbl,.sb.mini .sb-ws .t,.sb.mini .sb-inv,.sb.mini .ct{opacity:0;pointer-events:none}
.sb-it .ct{margin-left:auto;font-family:var(--mono);font-size:10px;font-weight:700;color:var(--muted)}
.sb-sec{display:flex;align-items:center;gap:8px;width:100%;padding:12px 9px 6px;font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--muted);text-align:left;white-space:nowrap}
.sb-sec .ms{margin-left:auto;font-size:14px;transition:transform .5s var(--ease),opacity .3s}
.sb-sec[aria-expanded="false"] .ms{transform:rotate(-90deg)}
.sb.mini .sb-sec .ms{opacity:0}
.sb-it.chat-it{padding-left:9px}
.sb-it.chat-it .dot{width:6px;height:6px;flex:none;background:var(--line);margin:0 5px}
.sb-it.chat-it.act .dot{background:var(--accent)}
.sb-bot{padding:10px;border-top:1px solid var(--line);display:flex;flex-direction:column;gap:10px}
.sb-inv{display:flex;flex-direction:column;gap:6px;white-space:nowrap}
.sb-inv .bar{height:2px;background:var(--line);position:relative}
.sb-inv .bar i{position:absolute;inset:0 70% 0 0;background:var(--accent)}
.sb-up{display:flex;align-items:center;justify-content:center;gap:8px;padding:8px;background:var(--accent);color:#120a02;font-weight:600;font-size:13px;white-space:nowrap}
.sb-main{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:16px;text-align:center}
.sb-main .t{font-weight:600;font-size:15px}

/* 15 search */
.pal{width:100%;max-width:440px;background:var(--panel);border:1px solid var(--icon-line)}
.pal-in{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line)}
.pal-in .ms{color:var(--muted)}
.pal-in input{flex:1;min-width:0;background:transparent;border:0;outline:0;color:var(--text);font:inherit;font-size:15px}
.pal-in input::placeholder{color:var(--muted)}
.pal-list{position:relative;padding:6px}
.pal-hl{position:absolute;left:6px;right:6px;top:0;height:0;background:var(--accent-bg);box-shadow:inset 2px 0 0 var(--accent);transition:transform .3s var(--ease),height .3s var(--ease),opacity .2s;pointer-events:none}
.pal-it{position:relative;display:flex;align-items:center;gap:12px;width:100%;padding:9px 10px;font-size:14px;color:var(--text-dim);text-align:left;transition:color .2s}
.pal-it.act{color:var(--accent)}
.pal-it .kbd{margin-left:auto;opacity:0;transition:opacity .2s}
.pal-it.act .kbd{opacity:1}
.pal-it mark{background:transparent;color:var(--text);font-weight:600}
.pal-it.act mark{color:var(--accent)}
.pal-empty{padding:26px 14px;text-align:center}
.pal-empty .t{font-weight:600;font-size:14px}
.pal-empty .d{margin-top:4px;font-size:13px;color:var(--muted)}
.pal-foot{display:flex;gap:14px;padding:10px 14px;border-top:1px solid var(--line)}
.pal-foot span{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)}

/* 16 flowchart */
.flow{position:relative;width:360px;height:420px;flex:none}
.flow svg.wires{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.wire{fill:none;stroke:rgba(var(--fg-rgb),.18);stroke-width:1;transition:stroke .4s ease}
.wire.lit{stroke:var(--accent)}
.wire-flow{fill:none;stroke:var(--accent);stroke-width:1.5;stroke-dasharray:4 10;opacity:0;transition:opacity .3s;animation:flowdash 1s linear infinite}
.wire-flow.lit{opacity:1}
@keyframes flowdash{to{stroke-dashoffset:-14}}
.fnode{position:absolute;text-align:left}
.fnode .node{flex-direction:column;align-items:stretch;gap:6px;padding:10px 12px;width:100%}
.fnode .ftop{display:flex;align-items:center;gap:8px}
.fnode .ftop .ms{color:var(--muted);font-size:16px;transition:color .3s}
.fnode .node.on .ftop .ms{color:var(--accent)}
.fnode .ft{font-weight:600;font-size:14px;transition:color .3s}
.fnode .node.on .ft{color:var(--accent)}
.fnode .fd{font-size:12px;color:var(--muted)}
.cond{display:flex;flex-wrap:wrap;align-items:center;gap:4px;font-size:12px;color:var(--muted)}
.cond .tag{font-family:var(--mono);font-size:11px}
.blabel{position:absolute;font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--muted);background:var(--bg);padding:0 4px;transition:color .3s}
.blabel.lit{color:var(--accent)}

/* 17 insight cards */
.ins-head{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line)}
.ins-head .t{font-weight:600;font-size:14px}
.pager{margin-left:auto;display:flex;align-items:center;gap:6px}
.pager button{width:28px;height:28px;display:grid;place-items:center;border:1px solid var(--line);color:var(--muted);transition:color .25s,border-color .25s}
.pager button:hover{color:var(--text);border-color:var(--icon-line)}
.ins-body{padding:16px;transition:opacity .25s ease,transform .3s var(--ease)}
.ins-body.out{opacity:0;transform:translateY(4px)}
.ins-text{font-size:15px;line-height:1.6}
.ins-text code{font-family:var(--mono);font-size:13px;padding:0 5px;background:var(--chip)}
.ins-text code.bad{color:var(--danger);background:rgba(255,90,95,.08)}
.ins-text code.good{color:var(--success);background:rgba(62,207,142,.08)}
.chart{position:relative;margin-top:16px;border:1px solid var(--line);height:130px;cursor:crosshair;touch-action:none}
.chart svg{position:absolute;inset:0;width:100%;height:100%}
.chart .ln{fill:none;stroke:var(--accent);stroke-width:1.5;vector-effect:non-scaling-stroke}
.chart .grid-l{stroke:var(--line);stroke-width:1;vector-effect:non-scaling-stroke}
.scrub{position:absolute;top:0;bottom:0;width:1px;background:var(--icon-line);opacity:0;transition:opacity .2s;pointer-events:none}
.scrub-dot{position:absolute;width:7px;height:7px;background:var(--accent);box-shadow:0 0 0 4px var(--bg-deep);transform:translate(-50%,-50%);opacity:0;transition:opacity .2s;pointer-events:none}
.scrub-tip{position:absolute;top:8px;padding:3px 8px;background:var(--panel);border:1px solid var(--icon-line);font-family:var(--mono);font-weight:700;font-size:11px;white-space:nowrap;opacity:0;transition:opacity .2s;pointer-events:none}
.chart.active .scrub,.chart.active .scrub-dot,.chart.active .scrub-tip{opacity:1}
.ins-acts{display:flex;gap:8px;padding:0 16px 16px}
.ins-acts .btn{padding:8px 14px;font-size:13px}

/* 18 code block */
.code-head{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line)}
.code-head .t{font-family:var(--mono);font-size:12px;font-weight:700}
.code-head .ghost{margin-left:auto}
.code-body{overflow-x:auto;padding:10px 0;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.code-body pre{margin:0;font-family:var(--mono);font-size:12.5px;line-height:1.75;counter-reset:ln}
.cl{display:block;padding:0 16px 0 0;white-space:pre}
.cl::before{counter-increment:ln;content:counter(ln);display:inline-block;width:38px;padding-right:14px;text-align:right;color:rgba(var(--fg-rgb),.25)}
.cl.add{background:rgba(62,207,142,.07)}
.cl.add::before{content:"+";color:var(--success)}
.cl.del{background:rgba(255,90,95,.07);color:rgba(var(--fg-rgb),.6)}
.cl.del::before{content:"-";color:var(--danger)}
.k{color:var(--code-k)}.s{color:var(--code-s)}.f{color:var(--code-f)}.c{color:var(--code-c)}.ty{color:var(--code-ty)}

/* 19 fine-tune */
.ftc{display:grid;grid-template-columns:1fr 190px;width:100%;max-width:480px;border:1px solid var(--line);background:var(--panel)}
.ft-prev{display:grid;place-items:center;min-height:300px;border-right:1px solid var(--line);padding:16px;overflow:hidden}
.ft-box{display:flex;flex-direction:column;justify-content:space-between;padding:14px;border:1px solid var(--accent-icon-line);background:var(--accent-bg);max-width:100%}
.ft-box .t{font-weight:600;font-size:14px}
.ft-box .p{font-family:var(--mono);font-weight:700;font-size:20px;color:var(--accent)}
.ft-box.pill{justify-content:center;align-items:center}
.ft-box.pill .p{display:none}
.ft-insp{display:flex;flex-direction:column}
.ft-insp .hd{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid var(--line);font-weight:600;font-size:13px}
.ft-sec{padding:10px 12px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:1fr 1fr;gap:6px}
.ft-sec .lab{grid-column:1/-1}
.fld{display:flex;align-items:center;gap:6px;border:1px solid var(--line);padding:5px 7px;transition:border-color .35s,background-color .35s}
.fld span{font-family:var(--mono);font-weight:700;font-size:10px;color:var(--muted);width:12px}
.fld input,.fld select{width:100%;min-width:0;background:transparent;border:0;outline:0;color:var(--text);font-family:var(--mono);font-size:12px;-moz-appearance:textfield}
.fld input::-webkit-outer-spin-button,.fld input::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}
.fld select{appearance:none;cursor:pointer}
.fld select option{background:var(--panel);color:var(--text)}
.fld.full{grid-column:1/-1}
.fld.chg{border-color:var(--accent);background-color:var(--accent-bg)}
.ft-go{margin:12px;justify-content:center;white-space:nowrap;padding-left:10px;padding-right:10px}

/* 20 selection actions */
.sel-p{padding:20px 18px 6px;font-size:15px;line-height:1.75;position:relative}
.sent{cursor:text;transition:background-color .3s,color .3s;padding:2px 0}
.sent:hover{background:rgba(var(--fg-rgb),.04)}
.sent.picked{background:rgba(255,133,13,.16);color:var(--text)}
.sel-bar{position:absolute;z-index:4;display:flex;background:var(--panel);border:1px solid var(--icon-line);opacity:0;transform:translateY(4px);transition:opacity .2s ease,transform .3s var(--ease);pointer-events:none;white-space:nowrap}
.sel-bar.show{opacity:1;transform:none;pointer-events:auto}
.sel-bar button{display:inline-flex;align-items:center;gap:5px;padding:6px 8px;font-size:11.5px;font-weight:600;color:var(--text-dim);border-right:1px solid var(--line);transition:color .2s,background-color .2s}
.sel-bar button:last-child{border-right:0}
.sel-bar button:hover{color:var(--accent);background:var(--accent-bg)}
.sel-bar .ms{font-size:14px}
.explain{margin:4px 18px 16px;padding:10px 12px;border-left:2px solid var(--accent);font-size:13px;line-height:1.6;color:var(--text-dim)}
.sel-hint{padding:0 18px 16px}

/* 21 agent screen */
.ag{display:grid;grid-template-columns:1fr 300px;width:100%;border:1px solid var(--line);background:var(--panel)}
.ag-screen{border-right:1px solid var(--line);display:flex;flex-direction:column;min-width:0}
.ag-bar{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line)}
.ag-bar .t{font-weight:600;font-size:13px}
.live{display:inline-flex;align-items:center;gap:6px;margin-left:auto;font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--accent)}
.live i{width:6px;height:6px;background:var(--accent);animation:dot 1.4s ease-in-out infinite}
.live.rec{color:var(--danger)}
.live.rec i{background:var(--danger);border-radius:50%}
.live.teach{color:var(--success)}
.live.teach i{background:var(--success)}
.ag-view{position:relative;padding:14px;flex:1}
.desk{position:relative;aspect-ratio:16/9.4;border:1px solid var(--line);background:var(--desk);display:grid;grid-template-rows:28px 1fr;overflow:hidden}
.desk-top{display:flex;align-items:center;gap:6px;padding:0 10px;border-bottom:1px solid var(--line)}
.desk-top i{width:7px;height:7px;background:rgba(var(--fg-rgb),.14)}
.desk-top .u{margin-left:10px;flex:1;max-width:240px;height:14px;background:rgba(var(--fg-rgb),.05);font-family:var(--mono);font-size:9px;color:var(--muted);display:flex;align-items:center;padding:0 6px}
.desk-app{display:grid;grid-template-columns:24% 1fr 26%;min-height:0}
.d-layers{border-right:1px solid var(--line);padding:8px;display:flex;flex-direction:column;gap:3px}
.d-layer{font-size:10px;color:var(--muted);padding:4px 6px;border:1px solid transparent;transition:border-color .3s,color .3s,background-color .3s;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.d-layer.on{border-color:var(--accent);color:var(--accent);background:var(--accent-bg)}
.d-canvas{position:relative;background-image:radial-gradient(rgba(var(--fg-rgb),.06) 1px,transparent 1.2px);background-size:8px 8px;display:grid;place-items:center}
.d-frame{width:62%;aspect-ratio:4/3;border:1px solid var(--line);background:rgba(var(--fg-rgb),.02);display:flex;flex-direction:column;gap:6%;padding:6%;transition:border-color .3s}
.d-frame.on{border-color:var(--accent)}
.d-card{flex:1;border:1px solid var(--line);transition:padding .5s var(--ease),border-color .3s;padding:4%;display:flex;flex-direction:column;gap:6%}
.d-card i{display:block;height:6px;background:rgba(var(--fg-rgb),.08)}
.d-card i:first-child{width:50%}
.d-card.on{border-color:var(--accent-icon-line)}
.d-props{border-left:1px solid var(--line);padding:8px;display:flex;flex-direction:column;gap:6px}
.d-prop{display:flex;justify-content:space-between;font-family:var(--mono);font-size:9px;color:var(--muted);padding:4px 6px;border:1px solid var(--line);transition:border-color .3s,color .3s}
.d-prop.on{border-color:var(--accent);color:var(--accent)}
.d-export{margin-top:auto;padding:5px;font-size:10px;font-weight:600;text-align:center;background:var(--chip);color:var(--text);transition:background-color .3s,color .3s}
.d-export.on{background:var(--accent);color:#120a02}
.d-toast{position:absolute;left:50%;top:38px;margin-left:-60px;padding:4px 8px;border:1px solid var(--success);color:var(--success);font-family:var(--mono);font-weight:700;font-size:9px;text-transform:uppercase;background:var(--desk);opacity:0;transform:translateY(4px);transition:opacity .3s,transform .4s var(--ease)}
.d-toast.show{opacity:1;transform:none}
.cursor{position:absolute;left:50%;top:50%;width:16px;height:16px;z-index:5;transition:left .9s var(--ease),top .9s var(--ease),opacity .3s;pointer-events:none;filter:drop-shadow(0 1px 2px rgba(0,0,0,.6))}
.cursor svg{width:16px;height:16px;display:block}
.cursor path{fill:var(--cursor-fill);stroke:var(--cursor-stroke)}
.click{position:absolute;width:18px;height:18px;margin:-9px 0 0 -9px;border:1px solid var(--accent);z-index:4;pointer-events:none;animation:clk .5s var(--ease) forwards}
@keyframes clk{from{opacity:1;transform:scale(.3)}to{opacity:0;transform:scale(1.4)}}
.teach-banner{position:absolute;left:24px;right:24px;top:24px;z-index:6;padding:8px 12px;border:1px solid var(--success);background:var(--desk);font-size:12px;color:var(--text);transition:opacity .3s,transform .4s var(--ease)}
.teach-banner.hide{opacity:0;transform:translateY(-4px);pointer-events:none}
.desk.teach .d-layer,.desk.teach .d-prop,.desk.teach .d-export{cursor:pointer}
.ag-log{display:flex;flex-direction:column;min-width:0}
.ag-log .hd{padding:12px 14px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}
.ag-steps{flex:1;padding:6px 0;overflow:auto}

@media (max-width:1100px){
  .ag{grid-template-columns:1fr}
  .ag-screen{border-right:0;border-bottom:1px solid var(--line)}
}
@media (max-width:720px){
  .ftc{grid-template-columns:1fr}
  .ft-prev{border-right:0;border-bottom:1px solid var(--line);min-height:240px}
  .flow{transform:scale(.86);transform-origin:center}
  .sb{width:200px}
  .desk-app{grid-template-columns:26% 1fr}
  .d-props{display:none}
}

/* ---------- standalone structure ---------- */
.top-nav{display:flex;gap:2px}
.top-nav a{padding:8px 10px;font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted);text-decoration:none;transition:color .25s}
.top-nav a:hover{color:var(--accent)}
.lib-sec .sec-head{display:grid;grid-template-columns:1fr auto;align-items:end;gap:8px 24px;padding:56px 48px 22px;border-bottom:1px solid var(--line)}
.sec-head .k{grid-column:1/-1}
.sec-head h2{margin:0;font-weight:600;font-size:26px;line-height:1.2;letter-spacing:-.3px}
.sec-head p{margin:6px 0 0;color:var(--muted);font-size:14px;max-width:52ch}
.sec-head .cnt{font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted);padding-bottom:4px}
.hero-groups{height:100%;display:flex;flex-direction:column;justify-content:center;padding:28px}
.hg{display:grid;grid-template-columns:150px 1fr;align-items:start;gap:14px;padding:12px 14px;border:1px solid var(--line);margin-top:-1px;background:var(--panel)}
.hg-h{display:flex;align-items:center;justify-content:space-between;gap:8px;text-decoration:none;font-weight:600;font-size:14px;transition:color .25s}
.hg-h:hover{color:var(--accent)}
.hg-h .num{font-family:var(--mono);font-size:10px;font-weight:700;color:var(--muted)}
.hg-links{display:flex;flex-wrap:wrap;gap:4px}
.hg-links a{padding:2px 7px;background:var(--chip);font-size:12px;font-weight:500;color:var(--text-dim);text-decoration:none;transition:color .25s,background-color .25s}
.hg-links a:hover{color:var(--accent);background:var(--accent-bg)}

/* step loader */
.ld-node{flex-direction:column;align-items:stretch;gap:14px}
.ld-track{display:grid;grid-template-columns:repeat(4,1fr);gap:4px}
.ld-track i{height:3px;background:var(--line);position:relative;overflow:hidden;transition:background-color .3s}
.ld-track i.done{background:var(--accent)}
.ld-track i.cur::after{content:"";position:absolute;inset:0;background:var(--accent);transform-origin:left;animation:fillx 3s linear forwards}
@keyframes fillx{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.radar{position:relative;width:22px;height:22px;border:1px solid var(--accent-icon-line);overflow:hidden}
.radar::before{content:"";position:absolute;inset:-60%;background:conic-gradient(from 0deg,transparent 0 280deg,var(--accent) 360deg);animation:spin 1.8s linear infinite}
.radar::after{content:"";position:absolute;left:50%;top:50%;width:4px;height:4px;margin:-2px 0 0 -2px;background:var(--accent)}
.stackb{display:flex;flex-direction:column;gap:3px;width:18px}
.stackb i{height:3px;background:var(--accent);transform-origin:left;animation:stackx 1.5s var(--ease) infinite;animation-delay:calc(var(--d) * 160ms)}
@keyframes stackx{0%{transform:scaleX(.15);opacity:.35}45%,70%{transform:scaleX(1);opacity:1}100%{transform:scaleX(.15);opacity:.35}}
.blink{display:flex;align-items:center;gap:2px}
.blink b{width:4px;height:3px;background:var(--muted);opacity:0;animation:typeb 1.8s steps(1) infinite;animation-delay:calc(var(--d) * 300ms)}
@keyframes typeb{0%{opacity:0}10%,80%{opacity:1}100%{opacity:0}}
.blink i{width:6px;height:14px;background:var(--accent);animation:blinkc 1s steps(1) infinite}
@keyframes blinkc{0%,49%{opacity:1}50%,100%{opacity:0}}
.sweep{position:relative;width:20px;display:flex;flex-direction:column;gap:3px;overflow:hidden}
.sweep i{display:block;height:2px;background:rgba(var(--fg-rgb),.15)}
.sweep::after{content:"";position:absolute;top:0;bottom:0;left:-8px;width:8px;background:linear-gradient(90deg,transparent,var(--accent),transparent);animation:sweepx 1.4s ease-in-out infinite}
@keyframes sweepx{0%{left:-8px}100%{left:20px}}

/* reasoning trail: a connecting line that grows with each step */
.trail>div{position:relative}
.trail>div:not(:last-child) .trace-item::after{content:"";position:absolute;left:23.5px;top:30px;bottom:-11px;width:1px;background:var(--line);transition:background-color .4s ease}
.trail>div:not(:last-child) .trace-item.done::after{background:rgba(62,207,142,.45)}
.trail .trace-item{position:relative}
.trail .trace-item .st{position:relative;z-index:1;background:var(--panel);box-shadow:0 0 0 3px var(--panel)}

/* status pill */
.sp-wrap{display:flex;flex-direction:column;align-items:center;gap:10px;width:100%;max-width:420px}
.sp{display:inline-flex;align-items:center;gap:10px;padding:7px 8px;border:1px solid var(--line);background:var(--panel);overflow:hidden;white-space:nowrap;transition:width .5s var(--ease),border-color .35s ease,background-color .35s ease}
.sp.wait{border-color:var(--accent);background-color:var(--accent-fill)}
.sp.done{border-color:rgba(62,207,142,.4)}
.sp-ic{width:26px;height:26px;flex:none;display:grid;place-items:center;border:1px solid var(--icon-line);background:var(--icon-bg)}
.sp.wait .sp-ic{border-color:var(--accent-icon-line);color:var(--accent)}
.sp-dot{width:6px;height:6px;background:var(--muted)}
.sp-dot.pulse{background:var(--accent);animation:dot 1.2s ease-in-out infinite}
.sp-t{font-weight:600;font-size:14px;padding-right:6px}
.sp-act{display:none;padding:5px 10px;background:var(--accent);color:#120a02;font-weight:600;font-size:12px}
.sp.wait .sp-act{display:inline-flex}
.sp-bar{display:none;width:100%;height:2px;background:var(--line);position:relative;overflow:hidden}
.sp-bar i{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--accent);transition:width .6s var(--ease)}
.sp-wrap.bar{align-items:stretch}
.sp-wrap.bar .sp{width:100%!important}
.sp-wrap.bar .sp-bar{display:block}
.sp-wrap.bar .sp-act{margin-left:auto}

/* context meter */
.cm-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--line)}
.cm-head .t{font-weight:600;font-size:14px}
.cm-bar{display:flex;gap:2px;height:14px;margin:16px 16px 4px}
.cm-seg{flex-grow:0;flex-shrink:0;transition:flex-basis .7s var(--ease),opacity .25s ease}
.cm-seg[data-k="files"],.sw.files{background:var(--accent)}
.cm-seg[data-k="chat"],.sw.chat{background:rgba(255,133,13,.5)}
.cm-seg[data-k="tools"],.sw.tools{background:rgba(var(--fg-rgb),.3)}
.cm-seg[data-k="free"],.sw.free{background:repeating-linear-gradient(135deg,rgba(var(--fg-rgb),.14) 0 1px,transparent 1px 5px);box-shadow:inset 0 0 0 1px var(--line)}
.cm-bar.hov .cm-seg:not(.on){opacity:.3}
.cm-legend{padding:8px 8px 4px}
.cm-row{display:flex;align-items:center;gap:10px;padding:8px;font-size:13px;color:var(--text-dim);transition:color .25s,background-color .25s}
.cm-row.on{color:var(--text);background:rgba(var(--fg-rgb),.03)}
.cm-row .v{margin-left:auto}
.sw{width:10px;height:10px;flex:none}
.cm-foot{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-top:1px solid var(--line)}
.cm-foot .btn{padding:8px 14px;font-size:13px}

/* voice capture */
.vc{padding:16px}
.vc-top{display:flex;justify-content:space-between}
.vc-wave{display:flex;align-items:center;justify-content:center;gap:3px;height:64px;margin:12px 0}
.vc-wave i{width:4px;height:4px;background:rgba(var(--fg-rgb),.2);transition:height .12s ease,background-color .3s}
.vc.listening .vc-wave i{background:var(--accent)}
.vc-text{min-height:72px;font-size:15px;line-height:1.6;padding:10px 12px;border:1px solid var(--line);background:var(--card-solid)}
.vc-ph{color:var(--muted)}
.vc-ctrl{display:flex;align-items:center;gap:12px;margin-top:14px}
.vc-mic{width:52px;height:52px;flex:none;display:grid;place-items:center;background:var(--accent);color:#120a02;transition:transform .3s var(--ease),background-color .3s}
.vc-mic .ms{font-size:22px}
.vc.listening .vc-mic{background:var(--danger)}
.vc-after{display:flex;gap:8px;margin-left:auto;opacity:0;transform:translateY(4px);pointer-events:none;transition:opacity .3s,transform .4s var(--ease)}
.vc-after.show{opacity:1;transform:none;pointer-events:auto}
.vc-after .btn{padding:8px 14px;font-size:13px}

/* compare view */
.cmp{position:relative;width:100%;max-width:900px;aspect-ratio:16/7.2;border:1px solid var(--line);background:var(--panel);overflow:hidden;cursor:ew-resize;user-select:none;touch-action:none}
.cmp-layer{position:absolute;inset:0;display:grid;grid-template-rows:auto auto 1fr;gap:6%;padding:3% 4%;background:var(--panel)}
.cmp-after{clip-path:inset(0 0 0 50%)}
.mk-nav{display:flex;align-items:center;gap:10px}
.mk-nav i{display:block;width:34px;height:6px;background:rgba(var(--fg-rgb),.15)}
.mk-nav span{flex:1}
.mk-hero{display:flex;flex-direction:column}
.mk-hero i{display:block;height:7px;background:rgba(var(--fg-rgb),.14)}
.mk-btn{display:block;width:90px;height:22px;background:var(--accent)}
.mk-cards{display:flex;gap:3%;align-items:stretch;min-height:0}
.mk-card{flex:1;border:1px solid var(--line);padding:3%;display:flex;flex-direction:column;gap:8px;background:var(--card-solid)}
.mk-card i{display:block;height:6px;background:rgba(var(--fg-rgb),.12)}
.mk-card i:first-child{width:55%}
.mk-card.on{border-color:var(--accent-icon-line)}
.cmp-tag{position:absolute;bottom:12px;padding:2px 8px;font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;border:1px solid var(--line);background:var(--panel);color:var(--muted);z-index:2}
.cmp-tag.l{left:12px}
.cmp-tag.r{right:12px;color:var(--accent);border-color:var(--accent-icon-line)}
.cmp-handle{position:absolute;top:0;bottom:0;left:50%;width:1px;background:var(--accent);z-index:3}
.cmp-handle .grip{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);display:flex;align-items:center;padding:6px 2px;background:var(--accent);color:#120a02}
.cmp-handle .grip .ms{font-size:14px}
.cmp-handle:focus-visible{outline:none}
.cmp-handle:focus-visible .grip{outline:1px solid var(--accent);outline-offset:3px}

@media (max-width:1100px){ .top-nav{display:none} }
@media (max-width:720px){
  .lib-sec .sec-head{padding:40px 20px 18px}
  .hg{grid-template-columns:1fr}
  .hero-groups{padding:16px}
  .cmp{aspect-ratio:4/3}
}

/* ---------- batch four ---------- */
.tg{width:34px;height:20px;flex:none;border:1px solid var(--icon-line);background:var(--icon-bg);position:relative;transition:background-color .3s,border-color .3s,opacity .3s}
.tg::after{content:"";position:absolute;top:3px;left:3px;width:12px;height:12px;background:var(--muted);transition:transform .4s var(--ease),background-color .3s}
.tg[aria-checked="true"]{background:var(--accent);border-color:var(--accent)}
.tg[aria-checked="true"]::after{transform:translateX(14px);background:#fff}
.tg:disabled{opacity:.35;cursor:not-allowed}
.tg-row{display:inline-flex;align-items:center;gap:10px;font-size:13px;color:var(--text-dim);cursor:pointer}
.pill.warn{color:var(--accent);border-color:var(--accent-icon-line);background:var(--accent-bg)}
.pill.fail{color:var(--danger);border-color:rgba(255,90,95,.35);background:rgba(255,90,95,.06)}

/* run cost */
.rcst{padding:0}
.rcs-top{display:flex;align-items:flex-start;justify-content:space-between;padding:16px}
.rcs-num{display:flex;align-items:baseline;gap:6px;margin-top:4px;font-family:var(--mono);font-weight:700;font-size:30px;letter-spacing:-.5px}
.rcs-of{font-size:13px;color:var(--muted)}
.rcs-bar{position:relative;height:6px;margin:0 16px 14px;background:var(--line)}
.rcs-bar i{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--accent);transition:width .25s linear,background-color .3s}
.rcs-bar.hot i{background:var(--danger)}
.rcs-mark{position:absolute;left:90%;top:-4px;bottom:-4px;width:1px;background:var(--text-dim)}
.rcs-rows{border-top:1px solid var(--line);padding:6px 0}
.rcs-row{display:flex;justify-content:space-between;padding:7px 16px;font-size:13px;color:var(--text-dim)}
.rcs-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px;border-top:1px solid var(--line)}
.rcs-foot .btn{padding:8px 14px;font-size:13px}

/* toast stack */
.ts-wrap{position:relative;width:100%;max-width:380px;height:300px}
.ts-stack{position:absolute;left:0;right:0;bottom:0;top:0}
.ti{position:absolute;left:0;right:0;bottom:0;display:flex;align-items:flex-start;gap:12px;padding:12px 12px 12px 14px;background:var(--panel);border:1px solid var(--line);transform-origin:bottom center;transition:transform .5s var(--ease),opacity .35s ease;box-shadow:0 10px 30px -18px rgba(0,0,0,.6)}
.ti .ibx{width:28px;height:28px;flex:none;display:grid;place-items:center;border:1px solid var(--icon-line);background:var(--icon-bg)}
.ti .tt{font-weight:600;font-size:14px}
.ti .tdd{font-size:13px;color:var(--text-dim);margin-top:1px}
.ti .x{margin-left:auto;color:var(--muted);width:22px;height:22px;display:grid;place-items:center;flex:none;transition:color .2s}
.ti .x:hover{color:var(--text)}
.ti .act{margin-top:8px;font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--accent)}

/* agent lanes */
.ln-head{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line)}
.ln-head .t{font-weight:600;font-size:14px}
.ln-head .ghost{margin-left:auto}
.ln-row{display:grid;grid-template-columns:44px minmax(160px,1fr) minmax(140px,220px) 120px;align-items:center;gap:16px;padding:14px 16px;border-bottom:1px solid var(--line)}
.ln-row:last-child{border-bottom:0}
.ln-name{font-weight:600;font-size:14px}
.ln-task{font-size:13px;color:var(--text-dim)}
.ln-track{display:grid;grid-template-columns:repeat(3,1fr);gap:3px}
.ln-track i{height:4px;background:var(--line);position:relative;overflow:hidden}
.ln-track i b{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--accent);transition:width .15s linear}
.ln-row.done .ln-track i b{background:var(--success)}
.ln-row .pill{justify-self:end}
.ln-row .nbox{width:36px;height:36px;box-shadow:0 0 0 5px var(--bg-deep)}
.ln-row.run .nbox{border-color:var(--accent-icon-line);color:var(--accent)}

/* prompt starters */
.ps-grid{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border-bottom:1px solid var(--line)}
.ps-card{display:flex;flex-direction:column;align-items:flex-start;gap:8px;padding:14px;background:var(--panel);text-align:left;transition:background-color .25s,color .25s}
.ps-card:hover{background:var(--accent-fill)}
.ps-card.on{background:var(--accent-fill);box-shadow:inset 0 0 0 1px var(--accent)}
.ps-card .ms{color:var(--accent)}
.ps-card .t{font-weight:600;font-size:14px}
.ps-card .d{font-size:12px;color:var(--muted);line-height:1.45}
.ps-comp{display:flex;align-items:flex-end;gap:10px;padding:12px}
.ps-text{flex:1;min-height:42px;font-size:14px;line-height:1.5;padding:4px}
.ps-caret{display:inline-block;width:6px;height:15px;background:var(--accent);vertical-align:-2px;margin-left:1px;animation:blinkc 1s steps(1) infinite}

/* attachment tray */
.at{padding:12px}
.at-drop{padding:10px;transition:background .3s}
.at-drop::before{transition:opacity .3s}
.at-drop.over::before{opacity:1}
.at-in{display:flex;flex-direction:column;align-items:center;gap:6px;padding:20px 12px;border:1px dashed var(--icon-line);background:var(--panel);text-align:center}
.at-drop.over .at-in{border-color:var(--accent)}
.at-in .t{font-weight:600;font-size:14px}
.at-link{color:var(--accent);font:inherit;text-transform:inherit;border-bottom:1px solid var(--accent-icon-line)}
.at-file{display:grid;grid-template-columns:38px 1fr auto 22px;align-items:center;gap:10px;padding:10px 4px 4px}
.at-file .kbd{justify-content:center}
.at-file .nm{font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.at-file .sz{font-size:10px}
.at-prog{grid-column:2/4;height:2px;background:var(--line);position:relative;overflow:hidden;margin-bottom:6px}
.at-prog i{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--accent);transition:width .2s linear}
.at-file.ok .at-prog i{background:var(--success)}
.at-x{color:var(--muted);transition:color .2s}
.at-x:hover{color:var(--danger)}

/* response versions */
.rv{padding:18px 18px 0}
.rv-body{display:flex;flex-direction:column;gap:10px;align-items:flex-start;min-height:96px}
.rv-text{font-size:18px;line-height:1.45;font-weight:600;letter-spacing:-.2px;transition:opacity .2s ease,transform .3s var(--ease)}
.rv-text.out{opacity:0;transform:translateY(4px)}
.rv-foot{display:flex;align-items:center;justify-content:space-between;margin:14px -18px 0;padding:10px 12px 10px 18px;border-top:1px solid var(--line)}
.rv-foot .ghost[disabled]{opacity:.4;cursor:default}

/* feedback sheet */
.fb-bar{display:flex;align-items:center;justify-content:space-between;padding:6px 10px 6px 16px;border-top:1px solid var(--line)}
.fb-form{display:flex;flex-direction:column;gap:10px;padding:14px 16px 16px;border-top:1px solid var(--line)}
.fb-chips{display:flex;flex-wrap:wrap;gap:6px}
.fb-ta{width:100%;resize:none;background:transparent;border:1px solid var(--line);color:var(--text);font:inherit;font-size:13px;padding:8px 10px;outline:0;transition:border-color .25s}
.fb-ta:focus{border-color:var(--icon-line)}
.fb-actions{display:flex;justify-content:flex-end;gap:8px}
.fb-actions .btn{padding:8px 14px;font-size:13px}
.fb-thx{display:flex;align-items:center;gap:10px;padding:14px 16px;border-top:1px solid var(--line);font-size:13px;color:var(--text-dim)}

/* permission gate */
.pg-head{display:flex;gap:14px;align-items:flex-start;padding:18px 16px 14px}
.pg-q{font-weight:600;font-size:16px;line-height:1.4}
.pg-d{margin-top:4px;font-size:13px;color:var(--text-dim)}
.pg-scopes{border-top:1px solid var(--line);padding:6px 0}
.pg-scope{display:flex;align-items:center;gap:12px;width:100%;padding:9px 16px;font-size:13px;text-align:left;color:var(--text-dim);transition:color .25s}
.pg-scope.on{color:var(--text)}
.pg-scope .pill{margin-left:auto}
.pg-dur{padding:12px 16px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px}
.pg-foot{display:flex;justify-content:flex-end;gap:8px;padding:12px 16px;border-top:1px solid var(--line)}
.pg-foot .btn{padding:8px 14px;font-size:13px}
.pg-granted{padding:20px 16px;display:flex;flex-direction:column;gap:12px;align-items:flex-start}
.pg-granted .tags{display:flex;flex-wrap:wrap;gap:6px}
.seg{position:relative;display:flex;border:1px solid var(--line)}
.seg button{position:relative;z-index:1;padding:6px 10px;font-size:12px;font-weight:600;color:var(--muted);transition:color .3s;white-space:nowrap}
.seg button.on{color:var(--accent)}
.seg-ind{position:absolute;top:0;bottom:0;left:0;width:0;background:var(--accent-bg);box-shadow:inset 0 -1px 0 var(--accent);transition:transform .45s var(--ease),width .45s var(--ease)}

/* launch checklist */
.lc-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--line)}
.lc-head .t{font-weight:600;font-size:14px}
.lc-bar{display:flex;gap:2px;height:4px;margin:12px 16px 4px}
.lc-bar i{flex:1;background:var(--line);transition:background-color .35s}
.lc-bar i.pass{background:var(--success)}.lc-bar i.warn{background:var(--accent)}.lc-bar i.fail{background:var(--danger)}
.lc-row{display:flex;align-items:center;gap:12px;padding:8px 16px;font-size:13px;color:var(--text-dim);transition:color .3s}
.lc-row.ran{color:var(--text)}
.lc-row .st{width:16px;height:16px;display:grid;place-items:center;flex:none}
.lc-row .note{display:block;font-size:11px;color:var(--muted)}
.lc-row .r{margin-left:auto;display:flex;align-items:center;gap:8px}
.lc-row .res{font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase}
.res.pass{color:var(--success)}.res.warn{color:var(--accent)}.res.fail{color:var(--danger)}

/* comment pins */
.cpn{display:grid;grid-template-columns:1fr 300px;width:100%;max-width:960px;border:1px solid var(--line);background:var(--panel)}
.cpn-canvas{position:relative;aspect-ratio:16/10;border-right:1px solid var(--line);cursor:crosshair;overflow:hidden}
.pin{position:absolute;z-index:3;width:24px;height:24px;margin:-12px 0 0 -12px;display:grid;place-items:center;background:var(--accent);color:#120a02;font-family:var(--mono);font-weight:700;font-size:11px;cursor:pointer;transition:transform .35s var(--ease),background-color .3s,box-shadow .3s;animation:iconin .4s var(--ease) both}
.pin.sel{transform:scale(1.15);box-shadow:0 0 0 3px var(--panel),0 0 0 4px var(--accent)}
.pin.res{background:var(--success)}
.pin.res.sel{box-shadow:0 0 0 3px var(--panel),0 0 0 4px var(--success)}
.cpn-side{display:flex;flex-direction:column;min-width:0}
.cpn-sh{display:flex;align-items:center;justify-content:space-between;padding:10px 12px 10px 14px;border-bottom:1px solid var(--line)}
.cpn-thread{flex:1;padding:12px 14px;display:flex;flex-direction:column;gap:12px;overflow:auto;min-height:180px}
.cm{display:flex;flex-direction:column;gap:3px}
.cm .who{display:flex;align-items:center;gap:6px;font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--muted)}
.cm .who .ms{font-size:13px}
.cm.agent .who{color:var(--accent)}
.cm .tx{font-size:13px;line-height:1.5}

/* field extraction */
.fx{display:grid;grid-template-columns:1.1fr 1fr;width:100%;max-width:960px;border:1px solid var(--line);background:var(--panel)}
.fx-doc{border-right:1px solid var(--line);display:flex;flex-direction:column}
.fx-dh{display:flex;align-items:center;gap:8px;padding:12px 16px;border-bottom:1px solid var(--line)}
.fx-p{margin:0;padding:18px 20px;font-size:14px;line-height:1.85;color:var(--text-dim)}
.fx-s{transition:background-color .35s,color .35s,box-shadow .35s;padding:1px 0}
.fx-s.hit{background:var(--accent-bg);color:var(--text);box-shadow:inset 0 -1px 0 var(--accent)}
.fx-s.hov{background:rgba(255,133,13,.22)}
.fx-fh{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid var(--line)}
.fx-fh .t{font-weight:600;font-size:14px}
.fx-f{display:grid;grid-template-columns:110px 1fr;gap:10px;align-items:baseline;padding:11px 16px;border-bottom:1px solid var(--line);transition:background-color .25s}
.fx-f:last-child{border-bottom:0}
.fx-f:hover{background:rgba(var(--fg-rgb),.02)}
.fx-f .l{font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--muted)}
.fx-f .v{font-size:14px;font-weight:600;min-height:21px}
.fx-f .v.empty{color:var(--muted);font-weight:500}
.fx-f .v.miss{color:var(--accent)}

/* task board */
.kb{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;width:100%;max-width:960px}
.kb-col{border:1px solid var(--line);background:var(--panel);display:flex;flex-direction:column;min-height:300px;transition:border-color .25s,background-color .25s}
.kb-col.over{border-color:var(--accent);background:var(--accent-fill)}
.kb-h{display:flex;align-items:center;justify-content:space-between;padding:10px 12px;border-bottom:1px solid var(--line)}
.kb-h .t{font-weight:600;font-size:13px}
.kb-list{flex:1;display:flex;flex-direction:column;gap:8px;padding:10px}
.kb-card{display:flex;flex-direction:column;gap:8px;padding:10px 12px;border:1px solid var(--line);background:var(--card-solid);cursor:grab;transition:border-color .25s,opacity .2s}
.kb-card:active{cursor:grabbing}
.kb-card.drag{opacity:.4}
.kb-card .t{font-size:13px;font-weight:600}
.kb-card .meta{display:flex;align-items:center;justify-content:space-between}
.kb-card .own{display:inline-flex;align-items:center;gap:5px;font-size:11px;color:var(--muted)}
.kb-card .own.agent{color:var(--accent)}
.kb-card .own .ms{font-size:13px}
.kb-card.moving{border-color:var(--accent)}

/* agent settings */
.as-sec{padding:14px 16px;border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:10px}
.as-sec .seg{align-self:stretch}
.as-sec .seg button{flex:1}
.as-desc{font-size:13px;color:var(--text-dim);line-height:1.5;min-height:39px}
.tg-line{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:13px;transition:opacity .3s}
.tg-line.locked{opacity:.55}
.as-row{flex-direction:row;align-items:center;justify-content:space-between;font-size:13px}
.as-foot{display:flex;align-items:center;justify-content:space-between;padding:12px 16px}
.as-foot .btn{padding:8px 14px;font-size:13px}
.as-foot .mono-xs.dirty{color:var(--accent)}

/* file explorer */
.fe-head{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid var(--line)}
.fe-head .t{font-weight:600;font-size:14px}
.fe-tree{padding:8px 6px;font-size:13px}
.fe-it{display:flex;align-items:center;gap:8px;width:100%;padding:5px 10px;text-align:left;color:var(--text-dim);transition:color .2s,background-color .2s}
.fe-it:hover{color:var(--text);background:rgba(var(--fg-rgb),.025)}
.fe-it.sel{color:var(--text);background:var(--accent-bg)}
.fe-it .ms{font-size:15px;flex:none}
.fe-it .chev{transition:transform .45s var(--ease);color:var(--muted)}
.fe-it[aria-expanded="false"] .chev{transform:rotate(-90deg)}
.fe-kids{padding-left:16px;margin-left:16px;border-left:1px solid var(--line)}
.fe-b{margin-left:auto;width:18px;height:18px;display:grid;place-items:center;font-family:var(--mono);font-weight:700;font-size:10px;border:1px solid transparent}
.fe-b.M{color:var(--accent);border-color:var(--accent-icon-line)}
.fe-b.A{color:var(--success);border-color:rgba(62,207,142,.35)}
.fe-b.D{color:var(--danger);border-color:rgba(255,90,95,.35)}
.fe-it.del .nm{text-decoration:line-through;opacity:.7}
.fe-foot{display:flex;justify-content:space-between;gap:10px;padding:10px 16px;border-top:1px solid var(--line)}
.fe-foot .mono-xs{text-transform:none}

/* version history */
.vh{width:100%;max-width:960px;border:1px solid var(--line);background:var(--panel)}
.vh-top{display:grid;grid-template-columns:1.5fr 1fr}
.vh-prev{position:relative;aspect-ratio:16/9;border-right:1px solid var(--line);overflow:hidden}
.vh-prev .cmp-layer{transition:opacity .3s ease}
.vh-prev .cmp-layer.out{opacity:0}
.vh-prev .mk-card,.vh-prev .mk-hero i,.vh-prev .mk-btn{transition:height .6s var(--ease),width .6s var(--ease),margin .6s var(--ease),background-color .4s,border-color .4s}
.vh-info{display:flex;flex-direction:column;align-items:flex-start;gap:8px;padding:20px}
.vh-title{font-weight:600;font-size:20px;letter-spacing:-.2px}
.vh-desc{margin:0;font-size:14px;line-height:1.55;color:var(--text-dim);min-height:66px}
.vh-info .btn{margin-top:auto;padding:8px 14px;font-size:13px}
.vh-line{position:relative;height:74px;margin:0 32px;border-top:0}
.vh-track{position:absolute;left:0;right:0;top:28px;height:1px;background:var(--icon-line)}
.vh-fill{position:absolute;left:0;top:28px;height:1px;background:var(--accent);width:0;transition:width .5s var(--ease)}
.vh-stop{position:absolute;top:28px;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;gap:8px;padding:0}
.vh-stop .d{width:12px;height:12px;border:1px solid var(--icon-line);background:var(--panel);transition:background-color .3s,border-color .3s,transform .35s var(--ease)}
.vh-stop.past .d{background:var(--accent);border-color:var(--accent)}
.vh-stop.sel .d{transform:scale(1.35);border-color:var(--accent);background:var(--accent)}
.vh-stop .lb{position:absolute;top:18px;white-space:nowrap;font-family:var(--mono);font-weight:700;font-size:10px;text-transform:uppercase;color:var(--muted);transition:color .3s}
.vh-stop.sel .lb{color:var(--accent)}
.vh-stop.cur .lb::after{content:" now"}

@media (max-width:1100px){
  .cpn,.fx,.vh-top{grid-template-columns:1fr}
  .cpn-canvas,.fx-doc,.vh-prev{border-right:0;border-bottom:1px solid var(--line)}
}
@media (max-width:720px){
  .ln-row{grid-template-columns:36px 1fr;gap:10px}
  .ln-track{grid-column:2}
  .ln-row .pill{grid-column:2;justify-self:start}
  .kb{grid-template-columns:1fr}
  .kb-col{min-height:0}
  .vh-line{margin:0 22px}
}

/* ---------- batch five ---------- */
.ch{padding:0}
.ch-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px 10px}
.ch-val{display:flex;align-items:center;gap:10px;margin-top:4px;font-family:var(--mono);font-weight:700;font-size:26px;letter-spacing:-.5px}
.ch-legend{display:flex;gap:16px;padding:10px 16px 14px;font-size:12px;color:var(--text-dim)}
.ch-legend span{display:inline-flex;align-items:center;gap:6px}
.sw.dash{background:repeating-linear-gradient(90deg,var(--muted) 0 3px,transparent 3px 5px);height:2px;width:12px}
.ch-tip{position:absolute;top:6px;padding:6px 8px;background:var(--panel);border:1px solid var(--icon-line);font-size:12px;white-space:nowrap;opacity:0;transition:opacity .2s;pointer-events:none;z-index:2}
.ch-tip .mono-xs{display:block;font-size:10px}
.ch-tip b{font-family:var(--mono)}

/* line chart */
.ch-plot{position:relative;height:190px;margin:0 16px 0 44px;cursor:crosshair;touch-action:none}
.ch-plot svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.ch-plot .ln{fill:none;stroke:var(--accent);stroke-width:1.75;vector-effect:non-scaling-stroke}
.ch-plot .ln.prev{stroke:var(--muted);stroke-dasharray:3 3;stroke-width:1}
.ch-plot .gl{stroke:var(--line);stroke-width:1;vector-effect:non-scaling-stroke}
.ch-ylab{position:absolute;left:-40px;top:0;bottom:0;width:32px}
.ch-ylab span{position:absolute;right:0;transform:translateY(-50%);font-family:var(--mono);font-size:10px;color:var(--muted)}
.ch-plot.active .scrub,.ch-plot.active .scrub-dot,.ch-plot.active .ch-tip{opacity:1}

/* bar chart */
.bc{display:flex;align-items:flex-end;gap:12px;height:200px;margin:6px 16px 0;padding-bottom:22px;position:relative;border-bottom:1px solid var(--line);background:linear-gradient(var(--line),var(--line)) 0 25%/100% 1px no-repeat,linear-gradient(var(--line),var(--line)) 0 50%/100% 1px no-repeat,linear-gradient(var(--line),var(--line)) 0 75%/100% 1px no-repeat}
.bc-col{position:relative;flex:1;height:100%;display:flex;align-items:flex-end;justify-content:center;gap:3px;cursor:pointer}
.bc-col .b{width:40%;height:0;transition:height .7s var(--ease),width .5s var(--ease),opacity .25s}
.bc-col .b.a{background:var(--accent)}
.bc-col .b.d{background:rgba(var(--fg-rgb),.35)}
.bc.stacked .bc-col{flex-direction:column-reverse;align-items:center;justify-content:flex-start;gap:0}
.bc.stacked .bc-col .b{width:60%}
.bc-col .lab{position:absolute;bottom:-20px;font-family:var(--mono);font-size:10px;color:var(--muted)}
.bc.hov .bc-col:not(.on) .b{opacity:.35}
.bc .ch-tip{top:-4px}

/* donut */
.dn-body{display:grid;grid-template-columns:150px 1fr;gap:16px;align-items:center;padding:6px 16px 16px}
.dn-ring{position:relative;width:150px;height:150px}
.dn-ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.dn-track{fill:none;stroke:var(--line);stroke-width:14}
.dn-seg{fill:none;stroke-width:14;transition:stroke-dasharray .9s var(--ease),opacity .25s,stroke-width .3s var(--ease);cursor:pointer}
.dn-svg-hov .dn-seg:not(.on){opacity:.3}
.dn-seg.on{stroke-width:17}
.dn-center{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;pointer-events:none}
.dn-ring .ch-tip{top:0;left:0}
.dn-row{cursor:pointer}
.dn-row.pinned{color:var(--text);background:var(--accent-bg);box-shadow:inset 2px 0 0 var(--accent)}
.dn-row.pinned .v{color:var(--accent)}
.dn-v{font-family:var(--mono);font-weight:700;font-size:22px}
.dn-legend{display:flex;flex-direction:column}
.dn-row{display:flex;align-items:center;gap:10px;padding:8px;font-size:13px;color:var(--text-dim);transition:color .25s,background-color .25s;cursor:default}
.dn-row.on{color:var(--text);background:rgba(var(--fg-rgb),.03)}
.dn-row .v{margin-left:auto}

/* heatmap */
.hm-wrap{display:flex;gap:8px;padding:4px 16px 0;overflow-x:auto}
.hm-days{display:grid;grid-template-rows:repeat(7,13px);gap:3px;margin-top:18px;font-size:9px}
.hm-days span:nth-child(1){grid-row:1}.hm-days span:nth-child(2){grid-row:3}.hm-days span:nth-child(3){grid-row:5}
.hm-months{position:relative;height:16px;font-size:9px}
.hm-months span{position:absolute;top:0}
.hm-grid{display:grid;grid-auto-flow:column;grid-template-rows:repeat(7,13px);grid-auto-columns:13px;gap:3px}
.hm-c{width:13px;height:13px;opacity:0;transform:scale(.6);transition:opacity .35s ease,transform .45s var(--ease),box-shadow .2s}
.hm-c.in{opacity:1;transform:none}
.hm-c:hover{box-shadow:0 0 0 1px var(--text)}
.l0{background:rgba(var(--fg-rgb),.06)}.l1{background:rgba(255,133,13,.25)}.l2{background:rgba(255,133,13,.45)}.l3{background:rgba(255,133,13,.7)}.l4{background:var(--accent)}
.hm-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px 14px}
.hm-foot .mono-xs{text-transform:none}
.hm-scale{display:inline-flex;align-items:center;gap:3px}
.hm-scale i{width:10px;height:10px;display:inline-block}

/* stat cards */
.kpi-wrap{width:100%;max-width:1000px}
.kpi-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
.kpi{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.kpi-c{background:var(--panel);border:1px solid var(--line);padding:18px 18px 16px;display:flex;flex-direction:column;gap:18px;min-width:0;transition:border-color .3s}
.kpi-c:hover{border-color:var(--icon-line)}
.kpi-c .lab{font-size:14px;font-weight:600}
.kpi-c .lab .per{color:var(--muted);font-weight:500}
.kpi-c .body{display:grid;grid-template-columns:auto 1fr;align-items:end;gap:14px}
.kpi-c .num{font-family:var(--mono);font-weight:700;font-size:30px;letter-spacing:-.6px;line-height:1.1;margin-bottom:10px}
.kpi-c .chart-r{position:relative;height:84px;min-width:0}
.kpi-c .spark{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.kpi-c .spark .tl{fill:none;stroke:var(--accent);stroke-width:1.75;vector-effect:non-scaling-stroke;transition:stroke .3s}
.kpi-c.down .spark .tl{stroke:var(--danger)}
.kpi-c .mk-line{position:absolute;top:0;bottom:0;width:0;border-left:1px dashed rgba(var(--fg-rgb),.22);transition:left .6s var(--ease)}
.kpi-c .mk-dot{position:absolute;width:8px;height:8px;margin:-4px 0 0 -4px;background:var(--accent);box-shadow:0 0 0 3px var(--panel);transition:left .6s var(--ease),top .6s var(--ease),background-color .3s}
.kpi-c.down .mk-dot{background:var(--danger)}
.kpi-c .mk-lab{position:absolute;transform:translate(-50%,-100%);margin-top:-10px;padding:1px 6px;font-family:var(--mono);font-weight:700;font-size:10px;color:var(--text);background:var(--chip);white-space:nowrap;transition:left .6s var(--ease),top .6s var(--ease)}

/* date picker and range picker */
.dp{width:100%;max-width:330px;padding:12px}
.dp-sel{display:grid;grid-template-columns:.8fr 1.3fr 1fr;gap:6px}
.dp-s{position:relative;padding:0}
.dp-s select{padding:8px 26px 8px 10px;font-family:var(--sans);font-size:13px;width:100%}
.dp-s .ms{position:absolute;right:7px;top:50%;transform:translateY(-50%);width:1em;color:var(--muted);pointer-events:none;font-size:15px}
.dp-s:focus-within{border-color:var(--accent-icon-line)}
.dp-val{margin:8px 0 12px;text-transform:none}
.dp-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
.dp-head .t{font-weight:600;font-size:14px}
.dp-head .ib{width:28px;height:28px}
.dp-dow{display:grid;grid-template-columns:repeat(7,1fr);text-align:center;font-size:10px;margin-bottom:4px}
.dp-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;transition:opacity .2s ease,transform .3s var(--ease)}
.dp-grid.out-l{opacity:0;transform:translateX(-14px)}
.dp-grid.out-r{opacity:0;transform:translateX(14px)}
.dd{position:relative;height:36px;display:grid;place-items:center;font-size:13px;color:var(--text);transition:background-color .2s,color .2s}
.dd:hover{background:rgba(var(--fg-rgb),.05)}
.dd.mute{color:var(--muted);opacity:.5}
.dd.wk{color:var(--text-dim)}
.dd.today{box-shadow:inset 0 0 0 1px var(--accent-icon-line)}
.dd.today::after{content:"";position:absolute;bottom:5px;width:4px;height:4px;background:var(--accent)}
.dd.sel,.dd.r-s,.dd.r-e{background:var(--accent-hi);color:#120a02;font-weight:600}
.dd.sel::after,.dd.r-s::after,.dd.r-e::after{background:#120a02}
.dd.r-in{background:var(--accent-bg);color:var(--text)}
.dd.mute.r-s,.dd.mute.r-e{opacity:1}
.dd.mute.r-in{opacity:.85}
.dd.r-pv{background:rgba(var(--fg-rgb),.05)}
.dd:focus-visible{outline:1px solid var(--accent);outline-offset:-1px}
.dp-foot{display:flex;justify-content:space-between;margin-top:10px}
.rp{width:100%;max-width:470px}
.rp-body{display:grid;grid-template-columns:130px 1fr}
.rp-presets{display:flex;flex-direction:column;padding:10px 8px;border-right:1px solid var(--line);gap:2px}
.rp-pre{padding:8px 10px;text-align:left;font-size:13px;color:var(--text-dim);transition:color .2s,background-color .2s}
.rp-pre:hover{color:var(--text);background:rgba(var(--fg-rgb),.03)}
.rp-pre.on{color:var(--accent);background:var(--accent-bg)}
.rp-cal{padding:12px}
.rp .dd{height:32px}
.rp-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 14px;border-top:1px solid var(--line);font-size:13px}
.rp-foot .btn{padding:8px 14px;font-size:13px}

/* time slots */
.ts-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line)}
.ts-top .t{font-weight:600;font-size:15px}
.ts-days{display:grid;grid-template-columns:repeat(5,1fr);border-bottom:1px solid var(--line)}
.ts-day{display:flex;flex-direction:column;align-items:center;gap:2px;padding:12px 6px;border-right:1px solid var(--line);transition:background-color .25s,color .25s;color:var(--text-dim)}
.ts-day:last-child{border-right:0}
.ts-day .n{font-family:var(--mono);font-weight:700;font-size:18px;color:var(--text)}
.ts-day .wd{font-size:12px}
.ts-day .free{font-family:var(--mono);font-size:10px;font-weight:700;text-transform:uppercase;color:var(--muted)}
.ts-day:hover{background:rgba(var(--fg-rgb),.025)}
.ts-day.on{background:var(--accent-fill);box-shadow:inset 0 -2px 0 var(--accent)}
.ts-day.on .n{color:var(--accent)}
.ts-slots{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:6px;padding:14px 16px;min-height:150px;align-content:start}
.slot{padding:9px 6px;border:1px solid var(--line);font-family:var(--mono);font-weight:700;font-size:12px;text-align:center;transition:border-color .2s,background-color .2s,color .2s}
.slot:hover:not(:disabled){border-color:var(--accent-icon-line);color:var(--accent)}
.slot.on{background:var(--accent-hi);border-color:var(--accent-hi);color:#120a02}
.slot:disabled{color:var(--muted);opacity:.45;text-decoration:line-through;cursor:not-allowed}
.ts-bar{display:flex;align-items:center;gap:10px;padding:12px 16px;border-top:1px solid var(--line);font-size:14px}
.ts-bar .btn{margin-left:auto;padding:8px 14px;font-size:13px}

@media (max-width:720px){
  .kpi{grid-template-columns:1fr 1fr}
  .dn-body{grid-template-columns:1fr;justify-items:center}
  .rp-body{grid-template-columns:1fr}
  .rp-presets{flex-direction:row;flex-wrap:wrap;border-right:0;border-bottom:1px solid var(--line)}
  .ts-days{grid-template-columns:repeat(5,minmax(56px,1fr));overflow-x:auto}
}

/* code viewer */
.code-btns{display:flex;gap:8px}
.ghost[aria-expanded="true"]{color:var(--accent);border-color:var(--accent-icon-line)}
.cd{border-top:1px solid var(--line);background:var(--panel)}
.cd-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:8px 16px 8px 32px;border-bottom:1px solid var(--line);flex-wrap:wrap}
.cd-tabs{display:flex;border:1px solid var(--line)}
.cd-tab{padding:6px 12px;font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted);border-right:1px solid var(--line);transition:color .25s,background-color .25s}
.cd-tab:last-child{border-right:0}
.cd-tab[aria-selected="true"]{color:var(--accent);background:var(--accent-bg)}
.cd-tab:hover{color:var(--text)}
.cd-meta{text-transform:none}
.cd-pre{margin:0;max-height:440px;overflow:auto;padding:12px 0;font-family:var(--mono);font-size:12px;line-height:1.7;counter-reset:ln;scrollbar-width:thin;scrollbar-color:var(--line) transparent;transition:opacity .2s ease}
.cd-pre.out{opacity:0}
.cd-pre .cl::before{width:44px}
.cd-pre .cmt{color:var(--code-c)}
.cd-pre .sec{color:var(--accent)}
@media (max-width:720px){ .cd-bar{padding-left:20px} .code-btns .vl{display:none} }

/* accent fills: lighter at rest, deeper on hover */
.btn.primary,.send,.vc-mic,.sb-up,.sp-act{background-color:var(--accent-hi);border-color:var(--accent-hi)}
.send,.sb-up,.sp-act{transition:background-color .25s ease,opacity .3s ease,transform .3s var(--ease)}
.btn.primary:not([disabled]):hover,.send:not([disabled]):hover,.vc:not(.listening) .vc-mic:hover,.sb-up:hover,.sp-act:hover{background-color:var(--accent);border-color:var(--accent)}

/* light theme refinements */
:root:not([data-theme="dark"]) .menu,:root:not([data-theme="dark"]) .sel-bar,:root:not([data-theme="dark"]) .toast,:root:not([data-theme="dark"]) .scrub-tip{box-shadow:0 8px 24px -12px rgba(12,14,32,.25)}
@media (prefers-color-scheme: dark){ :root:not([data-theme="light"]) .menu,:root:not([data-theme="light"]) .sel-bar,:root:not([data-theme="light"]) .toast,:root:not([data-theme="light"]) .scrub-tip{box-shadow:none} }
.theme-btn .ms{transition:transform .5s var(--ease)}
.theme-btn:active .ms{transform:rotate(-30deg)}

/* ---------- batch six ---------- */
#c57 .stage{min-height:520px}
.bt{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:38px;padding:0 16px;font-family:var(--sans);font-size:13.5px;font-weight:600;border:1px solid transparent;white-space:nowrap;transition:background-color .2s ease,border-color .2s ease,color .2s ease,transform .15s ease,box-shadow .2s ease,opacity .2s ease}
.bt:active:not(:disabled){transform:scale(.97)}
.bt:focus-visible{outline:none;box-shadow:0 0 0 3px var(--accent-bg);border-color:var(--accent)}
.bt-primary{background:var(--accent-hi);color:#120a02}
.bt-primary:hover:not(:disabled){background:var(--accent)}
.bt-secondary{background:var(--panel);border-color:var(--icon-line);color:var(--text)}
.bt-secondary:hover:not(:disabled){border-color:var(--text-dim)}
.bt-ghost{background:transparent;color:var(--text)}
.bt-ghost:hover:not(:disabled){background:var(--chip)}
.bt-danger{background:rgba(255,90,95,.08);border-color:rgba(255,90,95,.3);color:var(--danger)}
.bt-danger:hover:not(:disabled){background:rgba(255,90,95,.14)}
.bt-sm{height:30px;padding:0 11px;font-size:12.5px;gap:6px}
.bt-lg{height:46px;padding:0 22px;font-size:15px}
.bt-icon{width:38px;padding:0}
.bt:disabled{opacity:.45;cursor:not-allowed}
.bt.ok{background:var(--success);color:#fff;border-color:var(--success)}
.bt-spin{display:inline-block;width:14px;height:14px;flex:none;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:spin .8s linear infinite}
.bt-ic{display:inline-grid;place-items:center;width:16px;height:16px}
/* buttons */
.bt-wrap{display:flex;flex-direction:column;gap:22px;width:100%;max-width:440px}
.bt-row{display:flex;flex-direction:column;gap:10px}
.bt-set{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.bt-live{min-width:126px}

/* tooltip */
.tp-zone{position:relative;display:flex;flex-direction:column;align-items:center;gap:30px;padding:30px 0}
.tp-bar{display:flex;align-items:center;gap:2px;padding:4px;background:var(--panel);border:1px solid var(--line)}
.tp-btn{width:36px;height:36px;display:grid;place-items:center;color:var(--text-dim);transition:color .2s,background-color .2s}
.tp-btn:hover,.tp-btn:focus-visible{color:var(--text);background:var(--chip);outline:none}
.tp-sep{width:1px;height:20px;background:var(--line);margin:0 4px}
.tp-info{display:inline-flex;align-items:center;gap:6px;font-size:13px;color:var(--text-dim);border-bottom:1px dashed var(--icon-line);padding-bottom:1px}
.tp-info:hover,.tp-info:focus-visible{color:var(--text);outline:none}
.tp{position:absolute;left:0;top:0;z-index:5;display:flex;align-items:center;gap:8px;padding:6px 9px;background:var(--text);color:var(--panel);font-size:12px;font-weight:500;white-space:nowrap;pointer-events:none;opacity:0;transform:translate(-50%,calc(-100% - 6px)) translateY(4px);transition:opacity .16s ease,transform .25s var(--ease)}
.tp.show{opacity:1;transform:translate(-50%,calc(-100% - 6px))}
.tp.below{transform:translate(-50%,6px) translateY(-4px)}
.tp.below.show{transform:translate(-50%,6px)}
.tp-k{font-family:var(--mono);font-size:10.5px;opacity:.65}
.tp-k:empty{display:none}
.tp-d{display:none}
.tp.rich{flex-direction:column;align-items:flex-start;gap:3px;white-space:normal;width:230px;padding:10px 12px;background:var(--panel);color:var(--text);border:1px solid var(--icon-line);box-shadow:0 12px 30px -14px rgba(0,0,0,.35)}
.tp.rich .tp-t{font-weight:600;font-size:13px}
.tp.rich .tp-d{display:block;font-size:12.5px;line-height:1.5;color:var(--text-dim);font-weight:400}

/* search input */
.sx{position:relative;width:100%;max-width:380px;align-self:flex-start;margin-top:20px}
.sx-field{display:flex;align-items:center;gap:10px;height:44px;padding:0 10px 0 13px;background:var(--panel);border:1px solid var(--icon-line);cursor:text;transition:border-color .2s,box-shadow .2s}
.sx-field.focus{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
.sx-ic{color:var(--muted)}
.sx-field input{flex:1;min-width:0;background:transparent;border:0;outline:0;color:var(--text);font:inherit;font-size:14px}
.sx-field input::placeholder{color:var(--muted)}
.sx-end{display:flex;align-items:center;gap:6px}
.sx-spin,.sx-clear{display:none}
.sx.loading .sx-spin{display:inline-block;color:var(--muted)}
.sx.has .sx-clear{display:grid;place-items:center;width:22px;height:22px;color:var(--muted)}
.sx.has .sx-kbd{display:none}
.sx-clear:hover{color:var(--text)}
.sx-pop{position:absolute;left:0;right:0;top:calc(100% + 6px);z-index:4;background:var(--panel);border:1px solid var(--icon-line);opacity:0;visibility:hidden;transform:translateY(-4px);transition:opacity .2s ease,transform .3s var(--ease),visibility 0s linear .3s;box-shadow:0 14px 32px -16px rgba(0,0,0,.3)}
.sx-pop.show{opacity:1;visibility:visible;transform:none;transition:opacity .2s ease,transform .3s var(--ease),visibility 0s}
.sx-list{padding:6px}
.sx-h{padding:6px 8px 4px;font-size:11.5px;color:var(--muted)}
.sx-it{display:flex;align-items:center;gap:10px;width:100%;padding:8px;text-align:left;font-size:13.5px;color:var(--text-dim);transition:background-color .15s,color .15s}
.sx-it .ms{color:var(--muted);font-size:15px}
.sx-it .ty{margin-left:auto;font-size:11.5px;color:var(--muted)}
.sx-it.act{background:var(--accent-bg);color:var(--text)}
.sx-it mark{background:transparent;color:var(--accent);font-weight:600}
.sx-empty{padding:18px 10px;text-align:center;font-size:13px;color:var(--muted)}

/* country select */
.cc{position:relative;width:100%;max-width:320px;align-self:flex-start;margin-top:12px;display:flex;flex-direction:column;gap:6px}
.cc-lab{font-size:12.5px;font-weight:500;color:var(--text-dim)}
.cc-trig{display:flex;align-items:center;gap:10px;height:44px;padding:0 12px;background:var(--panel);border:1px solid var(--icon-line);text-align:left;transition:border-color .2s,box-shadow .2s}
.cc-trig[aria-expanded="true"],.cc-trig:focus-visible{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg);outline:none}
.cc-flag{width:22px;height:22px;flex:none;border-radius:50%;box-shadow:0 0 0 1px rgba(0,0,0,.06)}
.cc-name{flex:1;font-size:14px;font-weight:500}
.cc-car{color:var(--muted);transition:transform .35s var(--ease)}
.cc-trig[aria-expanded="true"] .cc-car{transform:rotate(180deg)}
.cc-pop{position:absolute;left:0;right:0;top:calc(100% + 6px);z-index:4;background:var(--panel);border:1px solid var(--icon-line);padding:6px;opacity:0;visibility:hidden;transform:translateY(-4px) scale(.99);transform-origin:top center;transition:opacity .2s ease,transform .3s var(--ease),visibility 0s linear .3s;box-shadow:0 16px 36px -18px rgba(0,0,0,.35)}
.cc-pop.show{opacity:1;visibility:visible;transform:none;transition:opacity .2s ease,transform .3s var(--ease),visibility 0s}
.cc-search{display:flex;align-items:center;gap:8px;padding:8px 10px;background:var(--chip);margin-bottom:4px;color:var(--muted)}
.cc-search input{flex:1;min-width:0;background:transparent;border:0;outline:0;color:var(--text);font:inherit;font-size:13.5px}
.cc-list{max-height:236px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.cc-it{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px;text-align:left;font-size:13.5px;color:var(--text);border:1px solid transparent;transition:background-color .15s,border-color .15s}
.cc-it .code{margin-left:auto;font-size:12px;color:var(--muted);font-family:var(--mono)}
.cc-it .ms{font-size:14px;color:var(--accent);opacity:0}
.cc-it.sel .ms{opacity:1}
.cc-it.act{background:var(--chip);border-color:var(--line)}
.cc-none{padding:16px;text-align:center;font-size:13px;color:var(--muted)}

/* social sign-in */
.so{display:flex;flex-direction:column;gap:8px;width:100%;max-width:340px}
.so-btn{position:relative;display:flex;align-items:center;justify-content:center;gap:10px;height:44px;padding:0 14px;background:var(--panel);border:1px solid var(--icon-line);font-size:14px;font-weight:500;color:var(--text);transition:border-color .2s,background-color .2s,transform .15s}
.so-btn:hover{border-color:var(--text-dim)}
.so-btn:active{transform:scale(.985)}
.so-logo{display:grid;place-items:center;width:18px;height:18px;flex:none}
.so-logo svg{width:18px;height:18px}
.so-mono{color:var(--text)}
.so-btn.busy{color:var(--text-dim)}
.so-btn.done{border-color:rgba(62,207,142,.5);color:var(--success)}
.so-div{display:flex;align-items:center;gap:12px;margin:6px 0;font-size:12px;color:var(--muted)}
.so-div::before,.so-div::after{content:"";flex:1;height:1px;background:var(--line)}
.so-email{display:flex;align-items:center;justify-content:center;gap:8px;height:40px;font-size:13.5px;font-weight:500;color:var(--text-dim);transition:color .2s}
.so-email:hover{color:var(--text)}

/* sign in and form fields */
.sn{max-width:360px;padding:24px}
.sn-mark{width:36px;height:36px;display:grid;place-items:center;background:var(--accent-hi);color:#120a02;margin-bottom:16px}
.sn-h{margin:0;font-size:20px;font-weight:600;letter-spacing:-.02em}
.sn-sub{margin:4px 0 18px;font-size:13.5px;color:var(--text-dim)}
.sn-or{display:flex;align-items:center;gap:12px;margin:16px 0;font-size:12px;color:var(--muted)}
.sn-or::before,.sn-or::after{content:"";flex:1;height:1px;background:var(--line)}
.fz{display:flex;flex-direction:column;gap:6px;margin-bottom:14px}
.fz-l{display:flex;justify-content:space-between;align-items:baseline;font-size:12.5px;font-weight:500;color:var(--text-dim)}
.fz-l a,.fz-l button{font-size:12.5px;color:var(--accent);text-decoration:none}
.fz-in{display:flex;align-items:center;gap:8px;height:42px;padding:0 12px;background:var(--panel);border:1px solid var(--icon-line);transition:border-color .2s,box-shadow .2s}
.fz-in:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
.fz-in input,.fz-in select,.fz-in textarea{flex:1;min-width:0;background:transparent;border:0;outline:0;color:var(--text);font:inherit;font-size:14px}
.fz-in input::placeholder,.fz-in textarea::placeholder{color:var(--muted)}
.fz-in select{appearance:none;cursor:pointer}
.fz-in select option{background:var(--panel);color:var(--text)}
.fz-in .ms{color:var(--muted)}
.fz-in.area{height:auto;padding:10px 12px;align-items:flex-start}
.fz-in textarea{resize:none;min-height:84px;line-height:1.5}
.fz.err .fz-in{border-color:var(--danger);box-shadow:0 0 0 3px rgba(255,90,95,.12)}
.fz-e{font-size:12px;color:var(--danger);display:none}
.fz.err .fz-e{display:block}
.fz-eye{display:grid;place-items:center;width:26px;height:26px;color:var(--muted)}
.fz-eye:hover{color:var(--text)}
.fz-row{display:flex;align-items:center;justify-content:space-between;margin:-2px 0 18px;font-size:13px;color:var(--text-dim)}
.fz-check{display:inline-flex;align-items:center;gap:8px;cursor:pointer}
.sn .bt-primary,.fm .fm-submit{width:100%;height:42px}
.sn-foot{margin-top:16px;text-align:center;font-size:13px;color:var(--text-dim)}
.sn-foot button{color:var(--accent);font-weight:500}
.sn-done{display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px;padding:18px 0 6px}
.sn-done .nbox{color:var(--success)}
.fm{padding:24px}
.fm-h{margin:0;font-size:18px;font-weight:600;letter-spacing:-.02em}
.fm-sub{margin:4px 0 20px;font-size:13.5px;color:var(--text-dim)}
.fm-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px}
.fm-grid .full{grid-column:1/-1}
.fm-chips{display:flex;flex-wrap:wrap;gap:6px}
.fm-chip{display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border:1px solid var(--icon-line);background:var(--panel);font-size:13px;font-weight:500;color:var(--text-dim);transition:border-color .2s,background-color .2s,color .2s}
.fm-chip .ms{font-size:14px;display:none}
.fm-chip.on{border-color:var(--accent);background:var(--accent-bg);color:var(--text)}
.fm-chip.on .ms{display:inline-flex}
.fm-count{font-size:11.5px;color:var(--muted);font-weight:400}
.fm-foot{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:4px}
.fm-foot .fz-check{font-size:13px;color:var(--text-dim)}
.fm .fm-submit{width:auto;padding:0 22px}

/* comments */
.dz{max-width:440px}
.dz-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px}
.dz-head .t{font-weight:600;font-size:15px}
.dz-comp{position:relative;margin:0 16px 4px;border:1px solid var(--icon-line);background:var(--panel);transition:border-color .2s,box-shadow .2s}
.dz-comp.focus{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
.dz-ed{min-height:46px;padding:12px 12px 4px;font-size:14px;line-height:1.5;outline:none;color:var(--text)}
.dz-ed:empty::before{content:attr(data-ph);color:var(--muted)}
.dz-men{display:inline-block;padding:0 6px;color:var(--accent);background:var(--accent-bg);font-weight:500}
.dz-tools{display:flex;align-items:center;justify-content:flex-end;gap:8px;padding:6px 8px 8px}
.dz-tools .ib{width:30px;height:30px}
.dz-menu{position:absolute;left:10px;top:44px;z-index:5;width:240px;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 14px 32px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px);transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.dz-menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.dz-mi{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;text-align:left;font-size:13.5px;font-weight:500;color:var(--text);transition:background-color .15s}
.dz-mi.act{background:var(--chip)}
.dz-av{position:relative;width:28px;height:28px;flex:none}
.dz-av img{width:100%;height:100%;border-radius:50%;display:block}
.dz-av i{position:absolute;right:-1px;bottom:-1px;width:9px;height:9px;border-radius:50%;background:var(--muted);box-shadow:0 0 0 2px var(--panel)}
.dz-av i.on{background:#22c55e}
.dz-list{padding:6px 0 4px}
.dz-c{padding:14px 16px;border-top:1px solid var(--line)}
.dz-c:first-child{border-top:0}
.dz-top{display:flex;align-items:center;gap:10px}
.dz-top .dz-av{width:32px;height:32px}
.dz-n{font-size:14px;font-weight:600}
.dz-role{font-size:11.5px;color:var(--muted)}
.dz-time{margin-left:auto;font-size:12px;color:var(--muted)}
.dz-body{margin:8px 0 10px 42px;font-size:14px;line-height:1.55;color:var(--text-dim)}
.dz-acts{display:flex;align-items:center;gap:6px;margin-left:42px}
.dz-r{display:inline-flex;align-items:center;gap:5px;height:26px;padding:0 9px;border:1px solid var(--line);font-size:12.5px;font-weight:600;color:var(--text-dim);transition:border-color .2s,background-color .2s,color .2s,transform .15s}
.dz-r:active{transform:scale(.94)}
.dz-r.on{border-color:var(--accent-icon-line);background:var(--accent-bg);color:var(--text)}
.dz-reply{margin-left:6px;font-size:12.5px;font-weight:500;color:var(--text-dim)}
.dz-reply:hover{color:var(--text)}

/* notifications */
.nt{max-width:440px}
.nt-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px 6px}
.nt-head .t{font-weight:600;font-size:15px}
.nt-mark{font-size:12.5px;font-weight:500;color:var(--accent)}
.nt-mark:disabled{color:var(--muted);cursor:default}
.nt-tabs{padding:0 6px}
.nt-badge{display:inline-grid;place-items:center;min-width:18px;height:18px;padding:0 5px;margin-left:6px;font-size:11px;font-weight:600;color:var(--accent);background:var(--accent-bg);transition:opacity .3s}
.nt-badge.zero{opacity:0}
.nt-it{position:relative;display:flex;gap:12px;padding:14px 16px 14px 22px;border-bottom:1px solid var(--line);transition:background-color .3s ease}
.nt-it:last-child{border-bottom:0}
.nt-it.unread{background:var(--accent-fill)}
.nt-dot{position:absolute;left:9px;top:24px;width:6px;height:6px;border-radius:50%;background:var(--accent);transition:opacity .3s,transform .3s var(--ease)}
.nt-it:not(.unread) .nt-dot{opacity:0;transform:scale(.4)}
.nt-it .dz-av{width:34px;height:34px}
.nt-ini{width:34px;height:34px;flex:none;display:grid;place-items:center;border-radius:50%;font-size:12px;font-weight:600}
.nt-txt{flex:1;min-width:0;padding-right:20px;font-size:13.5px;line-height:1.5;color:var(--text-dim)}
.nt-txt b{color:var(--text);font-weight:600}
.nt-time{display:block;margin-top:2px;font-size:12px;color:var(--muted)}
.nt-acts{display:flex;gap:8px;margin-top:10px}
.nt-file{display:flex;align-items:center;gap:10px;margin-top:10px;padding:8px 10px;border:1px solid var(--line);background:var(--panel);max-width:260px}
.nt-file .fi{width:30px;height:30px;display:grid;place-items:center;flex:none;background:var(--chip);color:var(--text-dim)}
.nt-file .fn{font-size:13px;font-weight:600;color:var(--text)}
.nt-file .fs{font-size:11.5px;color:var(--muted)}
.nt-x{position:absolute;right:10px;top:12px;width:26px;height:26px;display:grid;place-items:center;color:var(--muted);opacity:0;transition:opacity .2s,color .2s}
.nt-it:hover .nt-x,.nt-x:focus-visible{opacity:1}
.nt-x:hover{color:var(--text)}
.nt-empty{padding:34px 16px;text-align:center;font-size:13.5px;color:var(--muted)}
.nt-empty .ms{display:block;margin:0 auto 8px;font-size:22px}

@media (max-width:720px){ .fm-grid{grid-template-columns:1fr} }

/* ---------- batch seven ---------- */
/* toast */
.tst-wrap{display:flex;flex-direction:column;align-items:center;gap:22px;width:100%;max-width:380px}
.tst-slot{width:100%;min-height:96px;display:flex;align-items:flex-end}
.tst{position:relative;display:flex;align-items:flex-start;gap:12px;width:100%;padding:13px 12px 15px 14px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 14px 34px -18px rgba(0,0,0,.4);overflow:hidden;animation:tst-in .5s var(--ease) both}
.tst.out{animation:tst-out .3s ease forwards}
@keyframes tst-in{from{opacity:0;transform:translateY(14px) scale(.97)}to{opacity:1;transform:none}}
@keyframes tst-out{to{opacity:0;transform:translateY(8px) scale(.98)}}
.tst-ic{width:30px;height:30px;flex:none;display:grid;place-items:center;border:1px solid var(--icon-line);background:var(--icon-bg)}
.tst[data-v="success"] .tst-ic{color:var(--success)}
.tst[data-v="error"] .tst-ic{color:var(--danger)}
.tst[data-v="info"] .tst-ic{color:var(--accent)}
.tst-tx{flex:1;min-width:0}
.tst-t{font-size:14px;font-weight:600}
.tst-d{margin-top:2px;font-size:13px;color:var(--text-dim);line-height:1.45}
.tst-act{margin-top:8px;font-size:12.5px;font-weight:600;color:var(--accent)}
.tst-x{width:24px;height:24px;flex:none;display:grid;place-items:center;color:var(--muted);transition:color .2s}
.tst-x:hover{color:var(--text)}
.tst-bar{position:absolute;left:0;bottom:0;height:2px;width:100%;background:var(--accent);transform-origin:left;transform:scaleX(1)}
.tst[data-v="success"] .tst-bar{background:var(--success)}
.tst[data-v="error"] .tst-bar{background:var(--danger)}
.tst[data-v="loading"] .tst-bar{display:none}
/* reactions */
.rx{padding:16px 16px 6px;overflow:visible!important}
.rx-top{display:flex;align-items:center;gap:10px}
.rx-top .dz-av{width:38px;height:38px}
.rx-n{font-size:14px;font-weight:600}
.rx-m{font-size:12.5px;color:var(--muted)}
.rx-body{margin:12px 0 12px;font-size:14px;line-height:1.6;color:var(--text)}
.rx-sum{display:flex;align-items:center;gap:8px;padding-bottom:10px;border-bottom:1px solid var(--line);font-size:12.5px;color:var(--text-dim)}
.rx-stack{display:flex}
.rx-stack span{width:20px;height:20px;display:grid;place-items:center;margin-left:-5px;border-radius:50%;background:var(--panel);box-shadow:0 0 0 2px var(--panel);font-size:12px;line-height:1;animation:iconin .35s var(--ease) both}
.rx-stack span:first-child{margin-left:0}
.rx-com{margin-left:auto}
.rx-bar{display:flex;gap:4px;padding:4px 0}
.rx-like-wrap{position:relative;flex:1;display:flex}
.rx-act{flex:1;display:flex;align-items:center;justify-content:center;gap:7px;height:38px;font-size:13.5px;font-weight:600;color:var(--text-dim);transition:color .2s,background-color .2s,transform .2s}
.rx-act:hover{background:var(--chip);color:var(--text)}
.rx-em{display:none;font-size:17px;line-height:1}
.rx-like.on .rx-em{display:inline-block}
.rx-like.on .rx-ic{display:none}
.rx-like.pop{animation:rx-pop .5s cubic-bezier(.34,1.56,.64,1)}
@keyframes rx-pop{0%{transform:scale(1)}35%{transform:scale(.88)}70%{transform:scale(1.08)}100%{transform:scale(1)}}
.rx-tray{position:absolute;left:0;bottom:calc(100% + 6px);z-index:6;display:flex;gap:2px;padding:6px 8px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -14px rgba(0,0,0,.4);opacity:0;visibility:hidden;transform:translateY(8px) scale(.9);transform-origin:20% 100%;transition:opacity .2s ease,transform .35s cubic-bezier(.34,1.56,.64,1),visibility 0s linear .35s}
.rx-tray.show{opacity:1;visibility:visible;transform:none;transition:opacity .2s ease,transform .35s cubic-bezier(.34,1.56,.64,1),visibility 0s}
.rx-e{position:relative;width:42px;height:42px;display:grid;place-items:center;font-size:27px;line-height:1;opacity:0;transform:translateY(12px) scale(.4);transition:transform .25s cubic-bezier(.34,1.56,.64,1)}
.rx-tray.show .rx-e{animation:rx-e-in .45s cubic-bezier(.34,1.56,.64,1) both;animation-delay:calc(var(--i) * 40ms)}
@keyframes rx-e-in{from{opacity:0;transform:translateY(12px) scale(.4)}to{opacity:1;transform:none}}
.rx-tray.show .rx-e:hover,.rx-tray.show .rx-e.act{transform:translateY(-8px) scale(1.38)}
.rx-tray.show .rx-e:hover,.rx-tray.show .rx-e.act{animation:none;opacity:1}
.rx-tip{position:absolute;bottom:calc(100% + 6px);left:50%;transform:translateX(-50%) translateY(4px);padding:3px 8px;border-radius:999px;background:var(--text);color:var(--panel);font-size:11px;font-weight:600;white-space:nowrap;opacity:0;transition:opacity .15s,transform .2s var(--ease);pointer-events:none}
.rx-e:hover .rx-tip,.rx-e.act .rx-tip{opacity:1;transform:translateX(-50%)}
.rx-fly{position:absolute;z-index:8;font-size:27px;line-height:1;pointer-events:none}
.rx-burst{position:absolute;width:6px;height:6px;border-radius:50%;pointer-events:none;z-index:7;animation:rx-burst .6s ease-out forwards}
@keyframes rx-burst{from{transform:translate(0,0) scale(1);opacity:1}to{transform:translate(var(--dx),var(--dy)) scale(.3);opacity:0}}
/* buttons switcher */
.bt-wrap .bt-row{display:none}
.bt-wrap .bt-row.on{display:flex;animation:enter .4s var(--ease) both}
.bt-wrap .bt-lab{display:none}
.bt-wrap .bt-set{justify-content:center}
.bt-wrap{align-items:center}

/* ---------- batch eight ---------- */
/* thinking */
.tk2{width:100%;max-width:380px}
.tk2-h{display:inline-flex;align-items:center;gap:8px;font-size:14.5px;font-weight:500;color:var(--text-dim)}
.tk2-ic{color:var(--muted)}
.tk2-chev{color:var(--muted);transition:transform .45s var(--ease)}
.tk2-h[aria-expanded="false"] .tk2-chev{transform:rotate(-90deg)}
.tk2-list{margin:10px 0 0 7px;padding:2px 0 2px 18px;border-left:1px solid var(--line);display:flex;flex-direction:column}
.tk2-row{display:flex;align-items:center;gap:10px;padding:6px 0;font-size:14px;color:var(--text);animation:enter .4s var(--ease) both}
.tk2-row .st{width:16px;height:16px;flex:none;display:grid;place-items:center;color:var(--muted)}
.tk2-row .m{font-size:12.5px;color:var(--muted)}
.tk2-p{padding:4px 0;font-size:14px;line-height:1.65;color:var(--text-dim)}
/* step loader, compact */
.ld2{display:inline-flex;flex-direction:column;align-items:stretch;gap:8px}
.ld2-pill{display:inline-flex;align-items:center;gap:10px;padding:6px 14px 6px 6px;border:1px solid var(--line);background:var(--panel);white-space:nowrap;overflow:hidden;transition:width .5s var(--ease)}
.ld2 .glyph{width:28px;height:28px;box-shadow:none;border:1px solid var(--accent-icon-line);background:var(--accent-icon-bg)}
.ld2 .glyph>div{scale:.72}
.ld2 .loader-label{font-size:14px;font-weight:600}
.ld2-n{font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted)}
.ld2 .ld-track{gap:3px}
.ld2 .ld-track i{height:2px}

/* ---------- batch nine ---------- */
.ev-b{--c:#5d9bfb;--cb:rgba(93,155,251,.1);--cl:rgba(93,155,251,.35)}
.ev-m{--c:#3ecf8e;--cb:rgba(62,207,142,.1);--cl:rgba(62,207,142,.35)}
.ev-r{--c:#ff5a5f;--cb:rgba(255,90,95,.1);--cl:rgba(255,90,95,.35)}
.ev-l{--c:#a993ff;--cb:rgba(169,147,255,.12);--cl:rgba(169,147,255,.38)}
.ec-tag{display:inline-flex;align-items:center;gap:6px;padding:3px 9px;border:1px solid var(--line);font-size:12px;font-weight:600;color:var(--text-dim);transition:opacity .25s,background-color .25s,border-color .25s}
.ec-tag i{width:7px;height:7px;flex:none;background:var(--c)}
/* event calendar */
.ec{position:relative;width:100%;max-width:360px;padding:12px;overflow:visible!important}
.ec-tags{display:flex;flex-wrap:wrap;gap:6px;margin:2px 0 12px}
.ec-tags .ec-tag{cursor:pointer}
.ec-tags .ec-tag.off{opacity:.4}
.ec-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px;transition:opacity .2s ease,transform .3s var(--ease)}
.ec-grid.out-l{opacity:0;transform:translateX(-14px)}
.ec-grid.out-r{opacity:0;transform:translateX(14px)}
.ec-d{position:relative;height:42px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;font-size:13px;color:var(--text);transition:background-color .2s,color .2s,box-shadow .2s}
.ec-d:hover{background:rgba(var(--fg-rgb),.05)}
.ec-d.mute{color:var(--muted);opacity:.5}
.ec-d.today .n{color:var(--accent);font-weight:700}
.ec-d.sel{background:var(--accent-hi);color:#120a02}
.ec-d.sel.today .n{color:inherit}
.ec-dots{display:flex;gap:3px;height:5px}
.ec-dots i{width:5px;height:5px;background:var(--c);transition:opacity .25s,transform .3s var(--ease)}
.ec-dots i.off{opacity:0;transform:scale(0)}
.ec-pop{position:absolute;z-index:6;width:300px;padding:14px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 22px 50px -20px rgba(0,0,0,.45);opacity:0;visibility:hidden;transform:scale(.92) translateY(6px);transition:opacity .2s ease,transform .4s cubic-bezier(.34,1.4,.64,1),visibility 0s linear .4s}
.ec-pop.show{opacity:1;visibility:visible;transform:none;transition:opacity .2s ease,transform .4s cubic-bezier(.34,1.4,.64,1),visibility 0s}
.ec-pop-h{display:flex;align-items:center;justify-content:space-between;gap:8px}
.ec-acts{display:flex;gap:2px}
.ec-acts button{width:28px;height:28px;display:grid;place-items:center;color:var(--muted);transition:color .2s,background-color .2s}
.ec-acts button:hover{color:var(--text);background:var(--chip)}
.ec-pop-t{margin:10px 0 8px;font-size:16px;font-weight:600;letter-spacing:-.01em}
.ec-meta{display:flex;flex-direction:column;gap:5px;font-size:13px;color:var(--text-dim)}
.ec-meta span{display:flex;align-items:center;gap:8px}
.ec-meta .ms{color:var(--muted)}
.ec-guests{display:flex;align-items:center;gap:0;margin:14px 0 8px}
.ec-guests .dz-av{width:30px;height:30px;margin-left:-7px;border-radius:50%;box-shadow:0 0 0 2px var(--panel)}
.ec-guests .dz-av:first-child{margin-left:0}
.ec-add{width:30px;height:30px;margin-left:6px;display:grid;place-items:center;border-radius:50%;border:1px dashed var(--icon-line);color:var(--muted);transition:color .2s,border-color .2s}
.ec-add:hover{color:var(--text);border-color:var(--text-dim)}
.ec-rsvp{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--text-dim)}
.ec-rsvp b{color:var(--text);font-weight:600}
.ec-rsvp i{width:1px;height:12px;background:var(--line)}
.ec-about{margin-top:12px;padding-top:12px;border-top:1px solid var(--line);font-size:13px;line-height:1.55;color:var(--text-dim)}
.ec-about b{display:block;margin-bottom:3px;color:var(--text);font-weight:600}
.ec-pop-f{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}
/* agenda */
.agd{max-width:440px;overflow:hidden}
.agd-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--line)}
.agd-head .t{font-weight:600;font-size:15px}
.agd-scroll{max-height:400px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:var(--line) transparent;-webkit-mask:linear-gradient(#000 calc(100% - 28px),transparent);mask:linear-gradient(#000 calc(100% - 28px),transparent);padding-bottom:20px}
.agd-g{display:grid;grid-template-columns:44px 1fr;gap:12px;padding:14px 16px 4px}
.agd-day{display:flex;flex-direction:column;align-items:center;padding-top:4px}
.agd-day .wd{font-size:11px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}
.agd-day .n{font-size:22px;font-weight:600;line-height:1.2;color:var(--text-dim)}
.agd-g.today .agd-day .wd,.agd-g.today .agd-day .n{color:var(--text)}
.agd-list{display:flex;flex-direction:column;gap:8px;min-width:0}
.agd-c{display:flex;gap:12px;width:100%;padding:12px;text-align:left;border:1px solid var(--line);border-left:2px solid var(--c);background:var(--panel);transition:border-color .25s,background-color .25s,opacity .3s,transform .3s var(--ease)}
.agd-c:hover{background:var(--cb)}
.agd-c.past{opacity:.55}
.agd-c .dz-av{width:30px;height:30px;flex:none}
.agd-ic{width:30px;height:30px;flex:none;display:grid;place-items:center;background:var(--c);color:#fff}
.agd-tx{flex:1;min-width:0}
.agd-tt{font-size:14px;font-weight:600;color:var(--text)}
.agd-tm{margin-top:1px;font-size:12.5px;color:var(--text-dim)}
.agd-ds{margin-top:6px;font-size:12.5px;line-height:1.5;color:var(--text-dim);display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;overflow:hidden}
.agd-c.open .agd-ds{-webkit-line-clamp:unset}
.agd-now{position:relative;height:1px;margin:2px 0 2px -6px;background:var(--accent)}
.agd-now::before{content:"";position:absolute;left:-4px;top:-3px;width:7px;height:7px;border-radius:50%;background:var(--accent)}
.agd-now span{position:absolute;right:0;top:-9px;padding:0 6px;font-size:10.5px;font-weight:600;color:var(--accent);background:var(--panel)}
.agd-c.hide,.agd-g.hide{display:none}
/* invite */
.iv{position:relative;max-width:420px;padding:16px;overflow:visible!important}
.iv-head .t{font-size:15px;font-weight:600}
.iv-head .d{margin-top:2px;font-size:13px;color:var(--text-dim)}
.iv-row{display:flex;gap:8px;margin-top:14px}
.iv-field{position:relative;flex:1;min-width:0;display:flex;flex-wrap:wrap;align-items:center;gap:5px;min-height:40px;padding:5px 8px;background:var(--panel);border:1px solid var(--icon-line);cursor:text;transition:border-color .2s,box-shadow .2s}
.iv-field:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
.iv-chips{display:contents}
.iv-chip{display:inline-flex;align-items:center;gap:5px;height:26px;padding:0 4px 0 3px;background:var(--chip);font-size:12.5px;font-weight:500;animation:iconin .3s var(--ease) both}
.iv-chip .dz-av{width:20px;height:20px}
.iv-chip button{width:18px;height:18px;display:grid;place-items:center;color:var(--muted)}
.iv-chip button:hover{color:var(--text)}
.iv-field input{flex:1;min-width:120px;height:26px;background:transparent;border:0;outline:0;font:inherit;font-size:13.5px;color:var(--text)}
.iv-field input::placeholder{color:var(--muted)}
.iv-perm{flex:none;display:inline-flex;align-items:center;gap:4px;height:40px;padding:0 10px 0 12px;border:1px solid var(--icon-line);background:var(--panel);font-size:13px;font-weight:500;color:var(--text);white-space:nowrap}
.iv-perm .ms{color:var(--muted)}
.iv-sug{position:absolute;left:16px;right:16px;z-index:5;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px);transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.iv-sug.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.iv-s{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;text-align:left;transition:background-color .15s}
.iv-s.act{background:var(--chip)}
.iv-s .dz-av{width:28px;height:28px}
.iv-s .n{font-size:13.5px;font-weight:500;color:var(--text)}
.iv-s .e{font-size:12px;color:var(--muted)}
.iv-ini{width:28px;height:28px;flex:none;display:grid;place-items:center;border-radius:50%;background:var(--chip);color:var(--text-dim);font-size:12px;font-weight:600}
.iv-sec{margin:16px 0 6px;font-size:12px;font-weight:600;color:var(--muted)}
.iv-p{display:flex;align-items:center;gap:10px;padding:7px 0}
.iv-p .dz-av,.iv-p .iv-ini{width:32px;height:32px}
.iv-p .who{flex:1;min-width:0}
.iv-p .n{font-size:13.5px;font-weight:500;color:var(--text)}
.iv-p .e{font-size:12px;color:var(--muted)}
.iv-p .tag{margin-left:6px}
.iv-role{display:inline-flex;align-items:center;gap:3px;padding:4px 6px;font-size:12.5px;color:var(--text-dim);transition:color .2s,background-color .2s}
.iv-role:hover{color:var(--text);background:var(--chip)}
.iv-role .ms{font-size:13px}
.iv-role.owner{pointer-events:none}
.iv-role.owner .ms{display:none}
.iv-p.new{animation:enter .45s var(--ease) both}
.iv-foot{display:flex;justify-content:space-between;gap:8px;margin-top:14px;padding-top:14px;border-top:1px solid var(--line)}
.iv-menu{position:absolute;z-index:7;width:190px;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px) scale(.98);transform-origin:top right;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.iv-menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.iv-mi{display:flex;align-items:center;gap:8px;width:100%;padding:8px 10px;text-align:left;font-size:13px;color:var(--text);transition:background-color .15s}
.iv-mi:hover{background:var(--chip)}
.iv-mi .d{display:block;font-size:11.5px;color:var(--muted)}
.iv-mi .ms{margin-left:auto;color:var(--accent);opacity:0}
.iv-mi.sel .ms{opacity:1}
.iv-mi.rm{color:var(--danger);border-top:1px solid var(--line);margin-top:2px}

/* ---------- batch ten ---------- */
/* custom select */
.ns-hide{display:none!important}
.csel{flex:1;min-width:0;display:flex;align-items:center;align-self:stretch;background:transparent;border:0;padding:0;text-align:left;font:inherit;font-size:14px;color:var(--text);cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fld .csel{font-family:var(--mono);font-size:12px}
.csel-pop{position:fixed;z-index:120;min-width:160px;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px) scale(.98);transform-origin:top left;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.csel-pop.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.csel-i{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px;font-size:13.5px;color:var(--text);text-align:left;white-space:nowrap;transition:background-color .15s}
.csel-i.act{background:var(--chip)}
.csel-i .ms{margin-left:auto;color:var(--accent);opacity:0}
.csel-i.sel .ms{opacity:1}
/* payment form */
.pay{padding:0;overflow:hidden}
.pay-grid{display:grid;grid-template-columns:1.3fr 1fr}
.pay-main{padding:20px}
.pay-sum{display:flex;flex-direction:column;gap:10px;padding:20px;border-left:1px solid var(--line);background:var(--surface)}
.pay-methods{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:16px}
.pay-m{display:flex;flex-direction:column;align-items:flex-start;gap:8px;padding:10px 12px;border:1px solid var(--icon-line);background:var(--panel);font-size:13px;font-weight:500;color:var(--text-dim);text-align:left;transition:border-color .2s,box-shadow .2s,color .2s}
.pay-m:hover{color:var(--text)}
.pay-m .lg{display:flex;align-items:center;height:18px}
.pay-m .lg svg{width:18px;height:18px}
.pay-m.on{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg);color:var(--text)}
.pay-row{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}
.pay-brands{display:flex;gap:4px;flex:none}
.pay-brands span{padding:2px 5px;border:1px solid var(--line);font-family:var(--mono);font-size:9.5px;font-weight:700;color:var(--muted);transition:color .2s,border-color .2s,background-color .2s}
.pay-brands span.on{color:var(--text);border-color:var(--text-dim)}
.pay-plan{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;padding-bottom:12px;border-bottom:1px solid var(--line)}
.pay-plan b{display:block;font-size:14px;font-weight:600}
.pay-plan div span{font-size:12.5px;color:var(--muted)}
.pay-plan .v{font-size:14px;font-weight:600}
.pay-line{display:flex;justify-content:space-between;font-size:13px;color:var(--text-dim)}
.pay-line.disc{color:var(--success)}
.pay-promo{display:flex;gap:6px}
.pay-promo .fz-in{flex:1;height:38px}
.pay-promo .bt{height:38px}
.pay-total{display:flex;justify-content:space-between;margin-top:2px;padding-top:12px;border-top:1px solid var(--line);font-size:15px;font-weight:600}
.pay-go{width:100%;height:44px;margin-top:4px}
.pay-note{margin:0;font-size:12px;color:var(--muted);text-align:center}
.pay-wallet{display:flex;flex-direction:column;gap:10px;padding:6px 0 4px}
.pay-wbtn{display:flex;align-items:center;justify-content:center;gap:8px;height:48px;background:#0b0b0c;color:#fff;font-size:15px;font-weight:600;transition:transform .15s,opacity .2s}
.pay-wbtn:hover{opacity:.9}
.pay-wbtn:active{transform:scale(.985)}
.pay-wbtn svg{width:18px;height:18px}
.pay-wnote{font-size:12.5px;color:var(--muted);text-align:center}
.pay-done{display:flex;flex-direction:column;align-items:flex-start;gap:6px;padding:30px 4px}
.pay-done .nbox{color:var(--success);margin-bottom:8px}
.pay-done .t{font-size:17px;font-weight:600}
.pay-done .d{font-size:13.5px;color:var(--text-dim)}
@media (max-width:820px){ .pay-grid{grid-template-columns:1fr} .pay-sum{border-left:0;border-top:1px solid var(--line)} .pay-methods{grid-template-columns:1fr 1fr} }
/* event calendar: agenda below the month */
.ec-up{margin-top:12px;padding-top:12px;border-top:1px solid var(--line)}
.ec-uh{display:flex;justify-content:space-between;margin-bottom:6px;font-size:12px;font-weight:600;color:var(--muted)}
.ec-ui{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;text-align:left;transition:background-color .15s}
.ec-ui:hover{background:var(--chip)}
.ec-ui i{width:8px;height:8px;flex:none;background:var(--c)}
.ec-ui .t{flex:1;min-width:0;font-size:13px;font-weight:500;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ec-ui .m{font-size:12px;color:var(--muted);white-space:nowrap}
/* agenda: calendar grid behind the cards */
.agd-g{background-image:linear-gradient(var(--line) 1px,transparent 1px);background-size:100% 24px;background-position:0 13px}
.agd-day{align-self:stretch;margin-right:-1px;border-right:1px solid var(--line);background:var(--panel)}

/* ---------- batch eleven ---------- */
/* details panel */
.dt{max-width:420px;padding:16px}
.dt-head{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.dt-head .ms{color:var(--muted)}
.dt-head .t{font-size:15px;font-weight:600}
.dt-row{display:grid;grid-template-columns:130px 1fr;align-items:center;gap:10px;min-height:38px}
.dt-k{display:flex;align-items:center;gap:10px;font-size:13.5px;color:var(--text-dim)}
.dt-k .ms{color:var(--muted)}
.dt-v{display:flex;flex-wrap:wrap;align-items:center;gap:6px;min-width:0;padding:4px 6px;margin-left:-6px;font-size:13.5px;color:var(--text);cursor:text;transition:background-color .15s}
.dt-v:hover{background:var(--chip)}
.dt-v a{color:var(--accent);text-decoration:none;display:inline-flex;align-items:center;gap:5px}
.dt-v a .ms{font-size:13px}
.dt-v input{width:100%;background:transparent;border:0;outline:0;font:inherit;color:var(--text)}
.dt-v.edit{background:var(--chip);box-shadow:0 0 0 1px var(--accent)}
.dt-v .tag{display:inline-flex;align-items:center;gap:4px}
.dt-v .dz-av{width:20px;height:20px}
.dt-row.new{animation:enter .4s var(--ease) both}
.dt-add{display:inline-flex;align-items:center;gap:10px;margin-top:4px;padding:6px 0;font-size:13.5px;font-weight:500;color:var(--text)}
.dt-add .ms{color:var(--accent)}
.dt-foot{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}
.dt-foot .btn{justify-content:center;gap:8px}
.dt-ext{margin-left:auto;color:var(--muted)}
/* citation hover card */
.ci{position:relative;max-width:440px;padding:18px;overflow:visible!important}
.ci-p{margin:0;font-size:14.5px;line-height:1.75;color:var(--text)}
.ci-n{display:inline-grid;place-items:center;min-width:18px;height:18px;margin:0 2px;padding:0 4px;vertical-align:2px;font-family:var(--mono);font-size:10px;font-weight:700;color:var(--accent);background:var(--accent-bg);border:1px solid var(--accent-icon-line);cursor:pointer;transition:background-color .2s,color .2s}
.ci-n.on,.ci-n:hover,.ci-n:focus-visible{background:var(--accent);color:#fff;outline:none}
.ci-src{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}
.ci-s{display:inline-flex;align-items:center;gap:7px;padding:4px 9px 4px 4px;border:1px solid var(--line);font-size:12px;color:var(--text-dim);transition:border-color .2s,color .2s}
.ci-s b{display:grid;place-items:center;width:18px;height:18px;font-size:10px;color:#fff;background:var(--c,#555)}
.ci-s.on{border-color:var(--accent);color:var(--text)}
.ci-card{position:absolute;z-index:6;width:300px;padding:12px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 18px 44px -18px rgba(0,0,0,.45);opacity:0;visibility:hidden;transform:translateY(6px) scale(.97);transition:opacity .18s ease,transform .32s var(--ease),visibility 0s linear .32s;pointer-events:none}
.ci-card.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .32s var(--ease),visibility 0s}
.ci-ch{display:flex;align-items:center;gap:8px}
.ci-ch b{display:grid;place-items:center;width:22px;height:22px;flex:none;font-size:11px;color:#fff;background:var(--c,#555)}
.ci-ch .t{font-size:13px;font-weight:600;color:var(--text);line-height:1.3}
.ci-ch .d{font-size:11.5px;color:var(--muted)}
.ci-q{margin-top:10px;padding-left:10px;border-left:2px solid var(--accent);font-size:12.5px;line-height:1.55;color:var(--text-dim)}
.ci-q mark{background:var(--accent-bg);color:var(--text)}
/* agent run timeline */
.tl{position:relative;padding:0;overflow:visible!important}
.tl-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line)}
.tl-head .t{font-size:14px;font-weight:600}
.tl-sub{margin-top:2px;font-size:12.5px;color:var(--muted)}
.tl-body{position:relative;padding:8px 16px 4px}
.tl-axis{position:relative;height:22px;margin-left:170px;border-bottom:1px solid var(--line)}
.tl-axis span{position:absolute;top:2px;transform:translateX(-50%);font-family:var(--mono);font-size:10px;color:var(--muted)}
.tl-axis span::after{content:"";position:absolute;left:50%;top:16px;width:1px;height:5px;background:var(--line)}
.tl-row{display:grid;grid-template-columns:170px 1fr;align-items:center;height:36px}
.tl-name{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text-dim);white-space:nowrap;overflow:hidden}
.tl-name .ms{color:var(--muted)}
.tl-row.live .tl-name{color:var(--text)}
.tl-lane{position:relative;height:100%;background-image:linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:calc(100% / 6) 100%}
.tl-bar{position:absolute;top:10px;height:16px;width:0;transition:width .12s linear;cursor:pointer}
.tl-bar.k-model,.tlk-model{background:#a993ff}
.tl-bar.k-tool,.tlk-tool{background:var(--accent)}
.tl-bar.k-retry,.tlk-retry{background:repeating-linear-gradient(135deg,var(--danger) 0 3px,rgba(255,90,95,.45) 3px 6px)}
.tl-bar:hover{filter:brightness(1.1)}
.tl-head-line{position:absolute;top:8px;bottom:4px;width:1px;background:var(--text);opacity:0;pointer-events:none;transition:opacity .2s}
.tl-head-line.on{opacity:.5}
.tl-legend{display:flex;gap:16px;padding:10px 16px 14px;font-size:12px;color:var(--text-dim)}
.tl-legend span{display:inline-flex;align-items:center;gap:6px}
.tl-legend i{width:12px;height:8px}
.tl-tip{position:absolute}
/* memory panel */
.mm{max-width:420px}
.mm-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--line)}
.mm-head .t{font-size:15px;font-weight:600}
.mm-sub{margin-top:2px;font-size:12.5px;color:var(--muted)}
.mm-list{padding:6px 8px}
.mm-g{padding:8px 8px 4px;font-size:11.5px;font-weight:600;color:var(--muted)}
.mm-it{position:relative;display:flex;align-items:flex-start;gap:10px;padding:8px;transition:background-color .15s,opacity .3s}
.mm-it:hover{background:var(--chip)}
.mm-it .mm-pin{color:var(--accent);margin-top:1px}
.mm-tx{flex:1;min-width:0}
.mm-tx .t{font-size:13.5px;line-height:1.45;color:var(--text)}
.mm-tx .s{margin-top:2px;font-size:12px;color:var(--muted)}
.mm-acts{display:flex;gap:2px;opacity:0;transition:opacity .15s}
.mm-it:hover .mm-acts,.mm-it:focus-within .mm-acts{opacity:1}
.mm-acts button{width:26px;height:26px;display:grid;place-items:center;color:var(--muted)}
.mm-acts button:hover{color:var(--text)}
.mm-acts button.on{color:var(--accent)}
.mm.off .mm-list{opacity:.4;pointer-events:none}
.mm-add{display:flex;gap:8px;padding:10px 12px;border-top:1px solid var(--line)}
.mm-add input{flex:1;min-width:0;height:32px;padding:0 10px;background:var(--panel);border:1px solid var(--icon-line);outline:0;font:inherit;font-size:13.5px;color:var(--text)}
.mm-add input:focus{border-color:var(--accent)}
/* pricing */
.pr{width:100%;max-width:900px}
.pr-top{display:flex;align-items:center;justify-content:center;gap:10px;margin-bottom:16px}
.pr-save{font-size:12.5px;font-weight:600;color:var(--success)}
.pr-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.pr-c{display:flex;flex-direction:column;padding:20px;background:var(--panel);border:1px solid var(--line)}
.pr-c.pop{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
.pr-n{display:flex;align-items:center;justify-content:space-between;font-size:14px;font-weight:600}
.pr-n .tag{font-size:11px}
.pr-p{display:flex;align-items:baseline;gap:4px;margin:14px 0 4px}
.pr-p b{font-family:var(--mono);font-size:32px;font-weight:700;letter-spacing:-1px}
.pr-p span{font-size:13px;color:var(--muted)}
.pr-d{min-height:40px;font-size:13px;line-height:1.5;color:var(--text-dim)}
.pr-c .btn{justify-content:center;margin:14px 0 16px}
.pr-f{display:flex;flex-direction:column;gap:8px;padding-top:14px;border-top:1px solid var(--line)}
.pr-f span{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text-dim)}
.pr-f .ms{color:var(--success);font-size:14px}
/* model compare */
.mc{padding:0}
.mc-prompt{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid var(--line);font-size:14px;font-weight:500}
.mc-prompt .ms{color:var(--muted)}
.mc-cols{display:grid;grid-template-columns:1fr 1fr}
.mc-col{display:flex;flex-direction:column;gap:10px;padding:16px;min-height:190px;transition:background-color .3s}
.mc-col+.mc-col{border-left:1px solid var(--line)}
.mc-col.win{background:var(--accent-bg)}
.mc-mh{display:flex;align-items:center;justify-content:space-between}
.mc-mb{display:inline-flex;align-items:center;gap:6px;padding:4px 8px;border:1px solid var(--line);font-size:12.5px;font-weight:600;color:var(--text);transition:border-color .2s}
.mc-mb:hover{border-color:var(--icon-line)}
.mc-mb .ms{font-size:13px;color:var(--muted)}
.mc-out{flex:1;font-size:16px;line-height:1.5;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.mc-meta{display:flex;gap:14px;font-family:var(--mono);font-size:11px;color:var(--muted)}
.mc-meta b{color:var(--text);font-weight:700}
.mc-vote{display:flex;justify-content:center;gap:8px;padding:12px 16px;border-top:1px solid var(--line)}
.mc-vote .btn.on{border-color:var(--accent);color:var(--accent)}
/* onboarding checklist */
.ob{max-width:400px}
.ob-head{display:flex;align-items:center;gap:14px;padding:16px;border-bottom:1px solid var(--line)}
.ob-ring{position:relative;width:44px;height:44px;flex:none}
.ob-ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.ob-ring circle{fill:none;stroke-width:4}
.ob-ring .bg{stroke:var(--line)}
.ob-ring .fg{stroke:var(--accent);transition:stroke-dashoffset .7s var(--ease)}
.ob-ring span{position:absolute;inset:0;display:grid;place-items:center;font-family:var(--mono);font-size:11px;font-weight:700}
.ob-head .t{font-size:15px;font-weight:600}
.ob-head .d{margin-top:2px;font-size:12.5px;color:var(--muted)}
.ob-list{padding:6px 8px 8px}
.ob-s{padding:8px}
.ob-sh{display:flex;align-items:center;gap:10px;width:100%;text-align:left;font-size:13.5px;font-weight:500;color:var(--text)}
.ob-ck{width:20px;height:20px;flex:none;display:grid;place-items:center;border:1.5px solid var(--icon-line);border-radius:50%;color:#fff;transition:background-color .3s,border-color .3s}
.ob-ck .ms{font-size:12px;opacity:0;transform:scale(.5);transition:opacity .2s,transform .35s cubic-bezier(.34,1.56,.64,1)}
.ob-s.done .ob-ck{background:var(--success);border-color:var(--success)}
.ob-s.done .ob-ck .ms{opacity:1;transform:none}
.ob-s.done .ob-sh .t{color:var(--muted);text-decoration:line-through}
.ob-sh .chev{margin-left:auto;color:var(--muted);transition:transform .4s var(--ease)}
.ob-s.open .ob-sh .chev{transform:rotate(180deg)}
.ob-bd{padding:6px 0 4px 30px;font-size:13px;line-height:1.5;color:var(--text-dim)}
.ob-bd .btn{margin-top:10px}
.ob-done{display:flex;flex-direction:column;align-items:center;gap:6px;padding:28px 16px;text-align:center}
.ob-done .nbox{color:var(--success);margin-bottom:6px}
/* stepper */
.stp{max-width:430px}
.stp-head{display:flex;align-items:center;padding:16px;border-bottom:1px solid var(--line)}
.stp-i{display:flex;align-items:center;gap:8px;font-size:12.5px;font-weight:600;color:var(--muted);white-space:nowrap;transition:color .3s}
.stp-i b{width:22px;height:22px;display:grid;place-items:center;border:1px solid var(--icon-line);font-size:11px;transition:background-color .3s,border-color .3s,color .3s}
.stp-i.cur{color:var(--text)}
.stp-i.cur b{border-color:var(--accent);color:var(--accent)}
.stp-i.done b{background:var(--accent);border-color:var(--accent);color:#fff}
.stp-ln{flex:1;height:2px;margin:0 10px;background:var(--line);position:relative;overflow:hidden}
.stp-ln i{position:absolute;inset:0;background:var(--accent);transform:scaleX(0);transform-origin:left;transition:transform .5s var(--ease)}
.stp-ln.done i{transform:none}
.stp-body{padding:16px}
.stp-body .fz{margin-bottom:12px}
.stp-hint{font-size:12.5px;color:var(--muted)}
.stp-plans{display:flex;flex-direction:column;gap:8px}
.stp-plan{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--icon-line);text-align:left;transition:border-color .2s,box-shadow .2s}
.stp-plan.on{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
.stp-plan .t{font-size:13.5px;font-weight:600}
.stp-plan .d{font-size:12.5px;color:var(--muted)}
.stp-plan .p{margin-left:auto;font-family:var(--mono);font-size:13px;font-weight:700}
.stp-foot{display:flex;justify-content:space-between;padding:12px 16px;border-top:1px solid var(--line)}
.stp-foot .btn[disabled]{opacity:.4}
/* harness */
.hn{display:flex;flex-direction:column;width:100%;max-width:820px;height:600px;background:var(--panel);border:1px solid var(--line);overflow:hidden}
.hn-bar{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line)}
.hn-dot{width:8px;height:8px;background:var(--success)}
.hn-bar .t{font-size:14px;font-weight:600}
.hn-model{margin-left:auto;padding:3px 9px;border:1px solid var(--line);font-size:12px;font-weight:500;color:var(--text-dim)}
.hn-msgs{flex:1;overflow-y:auto;padding:20px 20px 10px;display:flex;flex-direction:column;gap:16px;scroll-behavior:smooth;scrollbar-width:thin;scrollbar-color:var(--line) transparent}
.hn-hello{margin:auto 0;text-align:center}
.hn-hello .h{font-size:24px;font-weight:600;letter-spacing:-.02em}
.hn-hello .d{margin-top:4px;font-size:14px;color:var(--text-dim)}
.hn-sugs{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:20px;text-align:left}
.hn-sug{display:flex;flex-direction:column;gap:8px;padding:14px;border:1px solid var(--line);background:var(--panel);font-size:13.5px;font-weight:500;color:var(--text);text-align:left;transition:border-color .2s,background-color .2s}
.hn-sug:hover{border-color:var(--icon-line);background:var(--chip)}
.hn-sug .ms{color:var(--accent)}
.hn-u{align-self:flex-end;max-width:75%;padding:9px 13px;background:var(--chip);font-size:14px;animation:enter .35s var(--ease) both}
.hn-a{display:flex;flex-direction:column;gap:10px;max-width:92%;animation:enter .35s var(--ease) both}
.hn-a .tk2{max-width:none}
.hn-txt{font-size:14.5px;line-height:1.65;color:var(--text)}
.hn-card{border:1px solid var(--line);background:var(--panel);animation:enter .45s var(--ease) both}
.hn-card-h{display:flex;align-items:center;justify-content:space-between;padding:10px 14px;border-bottom:1px solid var(--line);font-size:13px;font-weight:600}
.hn-acts{display:flex;gap:8px;padding:10px 14px;border-top:1px solid var(--line)}
.hn-comp{display:flex;align-items:center;gap:8px;margin:0 16px 16px;padding:6px 6px 6px 14px;border:1px solid var(--icon-line);background:var(--panel)}
.hn-comp input{flex:1;min-width:0;height:34px;background:transparent;border:0;outline:0;font:inherit;font-size:14px;color:var(--text)}
@media (max-width:760px){ .hn-sugs{grid-template-columns:1fr} .pr-grid{grid-template-columns:1fr} .mc-cols{grid-template-columns:1fr} .mc-col+.mc-col{border-left:0;border-top:1px solid var(--line)} .tl-axis{margin-left:120px} .tl-row{grid-template-columns:120px 1fr} }

/* ================= Soft style ================= */
.hero-copy .mono-tag{align-self:flex-start}
.style-seg button{font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;padding:7px 10px}
.soft-note{display:none}
.brand,.btn,.sound-btn,.style-seg button{white-space:nowrap}
@media (max-width:1480px){ .top-nav{display:none} }

:root[data-style="soft"]{
  --bg:#fafafa;--panel:#ffffff;--stage:#fafafa;--line:rgba(17,19,24,.08);--surface:transparent;--card:#ffffff;--card-solid:#ffffff;
  --icon-bg:#f4f4f5;--icon-line:rgba(17,19,24,.1);--chip:#f3f4f6;--text:#111318;--text-dim:#5b5f6b;--muted:#8b8f99;
  --ink:#116ff8;--ink-rgb:17,111,248;--on-ink:#ffffff;--ink-hover:#0a5fdc;
  --accent:#116ff8;--accent-bg:#eaf2ff;--accent-muted:#4a8ffa;--accent-icon-bg:#f4f4f5;--accent-icon-line:rgba(17,19,24,.08);--accent-fill:#f3f8ff;--accent-hi:#116ff8;
  --success:#159a63;--danger:#e0445a;--top-bg:rgba(255,255,255,.85);--bg-deep:#ffffff;--shimmer-hi:#111318;--hatch-on:transparent;
  --grad:#116ff8;--grad-deep:#0a5fdc;
  --pb-bg:#eaf2ff;--pb-line:#c8dcff;--pb-tx:#1563d6;
  --pl-bg:#f2edff;--pl-line:#ddd2ff;--pl-tx:#6b47d6;
  --pm-bg:#e7f8f0;--pm-line:#bfead6;--pm-tx:#138a57;
  --pp-bg:#fff2e6;--pp-line:#ffd8b8;--pp-tx:#c2610f;
  --pr-bg:#ffeef1;--pr-line:#ffcfd8;--pr-tx:#cf3653;
  --py-bg:#fffae3;--py-line:#f4e3a0;--py-tx:#9a7404;
  --pk-bg:#fff0f7;--pk-line:#ffcfe5;--pk-tx:#c1307a;
  --pt-bg:#e6f9fa;--pt-line:#bcecef;--pt-tx:#0f818a;
  --pg-bg:#f4f5f7;--pg-line:#e2e4ea;--pg-tx:#4b5163;
  --soft-shadow:0 1px 2px rgba(17,19,24,.04);--glow:transparent;
  --spring:cubic-bezier(.34,1.56,.64,1);
  color-scheme:light;
}
@media (prefers-color-scheme: dark){ :root[data-style="soft"]:not([data-theme="light"]){
  --bg:#0b0c0f;--panel:#121317;--stage:#17181d;--line:rgba(255,255,255,.08);--card:#17181d;--card-solid:#17181d;
  --icon-bg:rgba(255,255,255,.06);--icon-line:rgba(255,255,255,.12);--chip:rgba(255,255,255,.06);--text:#ededee;--text-dim:#a1a3ab;--muted:#76787f;
  --ink:#2f80ff;--ink-rgb:47,128,255;--on-ink:#ffffff;--ink-hover:#4b92ff;
  --accent:#4b92ff;--accent-bg:rgba(47,128,255,.16);--accent-muted:#7eb0ff;--accent-icon-bg:rgba(255,255,255,.06);--accent-icon-line:rgba(255,255,255,.12);--accent-fill:rgba(47,128,255,.1);--accent-hi:#2f80ff;
  --success:#4cc38a;--danger:#ff6b7d;--top-bg:rgba(18,19,23,.85);--bg-deep:#121317;--shimmer-hi:#ffffff;
  --grad:#2f80ff;--grad-deep:#4b92ff;
  --pb-bg:rgba(90,150,255,.15);--pb-line:rgba(90,150,255,.32);--pb-tx:#9cc2ff;
  --pl-bg:rgba(155,125,255,.15);--pl-line:rgba(155,125,255,.32);--pl-tx:#c3b1ff;
  --pm-bg:rgba(70,205,150,.13);--pm-line:rgba(70,205,150,.3);--pm-tx:#7fe0b4;
  --pp-bg:rgba(255,155,80,.14);--pp-line:rgba(255,155,80,.32);--pp-tx:#ffbd85;
  --pr-bg:rgba(255,105,130,.14);--pr-line:rgba(255,105,130,.32);--pr-tx:#ff9aae;
  --py-bg:rgba(240,200,60,.13);--py-line:rgba(240,200,60,.3);--py-tx:#f0d27a;
  --pk-bg:rgba(255,100,175,.13);--pk-line:rgba(255,100,175,.3);--pk-tx:#ff9fcf;
  --pt-bg:rgba(60,200,210,.13);--pt-line:rgba(60,200,210,.3);--pt-tx:#7fdde4;
  --pg-bg:rgba(255,255,255,.06);--pg-line:rgba(255,255,255,.12);--pg-tx:#c3c6d1;
  --soft-shadow:none;
  color-scheme:dark;
} }
:root[data-style="soft"][data-theme="dark"]{
  --bg:#0b0c0f;--panel:#121317;--stage:#17181d;--line:rgba(255,255,255,.08);--card:#17181d;--card-solid:#17181d;
  --icon-bg:rgba(255,255,255,.06);--icon-line:rgba(255,255,255,.12);--chip:rgba(255,255,255,.06);--text:#ededee;--text-dim:#a1a3ab;--muted:#76787f;
  --ink:#2f80ff;--ink-rgb:47,128,255;--on-ink:#ffffff;--ink-hover:#4b92ff;
  --accent:#4b92ff;--accent-bg:rgba(47,128,255,.16);--accent-muted:#7eb0ff;--accent-icon-bg:rgba(255,255,255,.06);--accent-icon-line:rgba(255,255,255,.12);--accent-fill:rgba(47,128,255,.1);--accent-hi:#2f80ff;
  --success:#4cc38a;--danger:#ff6b7d;--top-bg:rgba(18,19,23,.85);--bg-deep:#121317;--shimmer-hi:#ffffff;
  --grad:#2f80ff;--grad-deep:#4b92ff;
  --pb-bg:rgba(90,150,255,.15);--pb-line:rgba(90,150,255,.32);--pb-tx:#9cc2ff;
  --pl-bg:rgba(155,125,255,.15);--pl-line:rgba(155,125,255,.32);--pl-tx:#c3b1ff;
