/* theme switch */
.theme-sw{position:relative;display:inline-flex;align-items:center;width:64px;height:32px;padding:3px;border-radius:999px;background:var(--sh-chip);border:1px solid var(--sh-line);flex:none;cursor:pointer}
.theme-sw .ts-thumb{position:absolute;top:3px;left:3px;width:26px;height:26px;border-radius:50%;background:var(--sh-card);box-shadow:0 1px 3px rgba(0,0,0,.18),0 0 0 .5px rgba(0,0,0,.06);transition:transform .45s cubic-bezier(.34,1.56,.64,1)}
.theme-sw .ts-ic{position:relative;z-index:1;flex:1;display:grid;place-items:center;height:26px;color:var(--sh-muted);transition:color .3s ease,transform .45s var(--ease)}
.theme-sw .ts-ic .ms{font-size:15px}
.theme-sw .ts-ic.sun{color:var(--sh-text)}
.theme-sw[aria-checked="true"] .ts-thumb{transform:translateX(30px)}
.theme-sw[aria-checked="true"] .ts-ic.sun{color:var(--sh-muted);transform:rotate(-40deg)}
.theme-sw[aria-checked="true"] .ts-ic.moon{color:var(--sh-text);transform:rotate(-12deg)}
.theme-sw:focus-visible{outline:2px solid var(--sh-blue);outline-offset:2px}
/* filter dropdown */
.flt{position:relative}
body.ui .top .flt-btn{font-family:var(--sans);font-size:13px;font-weight:500;color:var(--sh-text);background:var(--sh-card);border:1px solid var(--sh-line)}
body.ui .top .flt-btn:hover{border-color:var(--sh-line-2)}
.flt-btn .ms{font-size:14px;color:var(--sh-muted);transition:transform .35s var(--ease)}
.flt-btn[aria-expanded="true"] .ms.car{transform:rotate(180deg)}
.flt-menu{position:absolute;right:0;top:calc(100% + 8px);z-index:50;min-width:180px;padding:5px;background:var(--sh-card);border:1px solid var(--sh-line);border-radius:14px;box-shadow:0 16px 36px -16px rgba(0,0,0,.25);opacity:0;visibility:hidden;transform:translateY(-4px) scale(.98);transform-origin:top right;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.flt-menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.flt-i{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px;border-radius:9px;font-size:13.5px;color:var(--sh-text);text-align:left;transition:background-color .15s}
.flt-i:hover{background:var(--sh-chip)}
.flt-i .ms{margin-left:auto;font-size:14px;opacity:0}
.flt-i.on .ms{opacity:1}
/* sidebar: search, saved, collapsible groups */
.side-search{display:flex;align-items:center;gap:8px;height:36px;margin:0 0 18px;padding:0 6px 0 12px;background:var(--sh-card);border:1px solid var(--sh-line);border-radius:999px;transition:border-color .2s,box-shadow .2s}
.side-search:focus-within{border-color:var(--sh-blue);box-shadow:0 0 0 3px rgba(17,111,248,.12)}
.side-search .ms{color:var(--sh-muted);font-size:15px}
.side-search input{flex:1;min-width:0;background:transparent;border:0;outline:0;font:inherit;font-size:13.5px;color:var(--sh-text)}
.side-search input::placeholder{color:var(--sh-muted)}
.side-search .kbd{font-family:var(--sans);font-size:11.5px;font-weight:500;color:var(--sh-muted);border:1px solid var(--sh-line);background:var(--sh-bg);border-radius:6px;padding:1px 7px;text-transform:none}
.side-grp{margin-bottom:10px}
.side-h{display:flex;align-items:center;gap:6px;width:100%;padding:7px 6px 7px 4px;margin-bottom:4px;border-bottom:1px solid var(--sh-line);font-size:12.5px;font-weight:600;color:var(--sh-text);text-align:left;text-decoration:none;cursor:pointer;transition:color .2s}
.side-h .chev{display:grid;place-items:center;width:18px;height:18px;color:var(--sh-muted);font-size:14px;transition:transform .35s var(--ease)}
.side-grp.closed .side-h .chev{transform:rotate(-90deg)}
.side-h .nm{flex:1}
.side-n{display:inline-grid;place-items:center;min-width:24px;height:22px;padding:0 6px;font-size:11.5px;font-weight:600;color:var(--sh-dim);background:var(--sh-bg);border:1px solid var(--sh-line);border-radius:7px;corner-shape:squircle}
@supports (corner-shape: squircle){ .side-n{border-radius:11px} }
.side-list{display:grid;grid-template-rows:1fr;transition:grid-template-rows .4s var(--ease),opacity .3s ease}
.side-list>.side-ul{min-height:0;overflow:hidden}
.side-grp.closed .side-list{grid-template-rows:0fr;opacity:0}
.side-a.hide{display:none}
.side-saved .side-h .chev{color:var(--sh-blue)}
.saved-hint{padding:4px 10px 8px;font-size:12px;line-height:1.5;color:var(--sh-muted)}
.side-empty,.content-empty{display:none;flex-direction:column;align-items:flex-start;gap:10px;padding:8px 6px}
.side-empty.show{display:flex}
.side-empty .suggest-btn{font-size:12.5px}
.side-empty p,.content-empty p{margin:0;font-size:13px;color:var(--sh-dim);line-height:1.5}
.suggest-btn{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 13px 0 7px;white-space:nowrap;border-radius:999px;background:var(--sh-ink);color:var(--sh-on-ink);font-size:13px;font-weight:600;transition:transform .2s cubic-bezier(.34,1.56,.64,1),opacity .2s}
.suggest-btn .ms{width:20px;height:20px;display:grid;place-items:center;border-radius:50%;background:rgba(255,255,255,.18);font-size:14px}
.suggest-btn:hover{transform:translateY(-1px)}
.suggest-btn.done{background:#159a63;color:#fff}
.content-empty{align-items:center;text-align:center;padding:60px 20px;border:1px dashed var(--sh-line-2);border-radius:16px;margin-top:28px}
.content-empty.show{display:flex}
.content-empty .t{font-size:15px;font-weight:600;color:var(--sh-text)}
/* sidebar footer: credit, CTA and partner button */
.side-cta{margin:12px 0 0 !important;color:var(--sh-dim) !important;font-size:12.5px}
.hire-btn{position:relative;display:inline-flex;align-items:center;gap:8px;height:32px;margin-top:10px;padding:0 12px 0 14px;border-radius:999px;background:var(--sh-chip);border:1px solid var(--sh-line);color:var(--sh-text);font-size:13px;font-weight:600;text-decoration:none;overflow:hidden;isolation:isolate;transition:background-color .25s ease,border-color .25s ease,color .25s ease}
.hire-btn .ms{font-size:14px;transition:transform .35s cubic-bezier(.34,1.56,.64,1)}
.hire-btn::before{content:"";position:absolute;inset:0;z-index:-1;background:var(--sh-blue);transform:translateY(101%);transition:transform .4s var(--ease)}
.hire-btn:hover{color:#fff;border-color:var(--sh-blue)}
.hire-btn:hover::before{transform:none}
.hire-btn:hover .ms{transform:translateX(3px)}
.hire-btn::after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(115deg,transparent 35%,rgba(255,255,255,.55) 50%,transparent 65%);background-size:260% 100%;background-position:160% 0;animation:cta-gloss 10s ease-in-out 3s infinite}
/* save button on each component */
.save-btn{margin-left:auto;align-self:flex-start;display:grid;place-items:center;width:32px;height:32px;flex:none;border-radius:999px;color:var(--sh-muted);border:1px solid transparent;transition:color .2s,background-color .2s,border-color .2s,transform .25s cubic-bezier(.34,1.56,.64,1)}
.save-btn:hover{color:var(--sh-text);background:var(--sh-chip)}
.save-btn[aria-pressed="true"]{color:var(--sh-blue)}
.save-btn:active{transform:scale(.88)}
.save-btn .ms{font-size:16px}
/* intro and section headings */
.intro p{max-width:70%}
body.ui .lib-sec .sec-head{display:block;padding:44px 0 20px;margin-bottom:22px;border-bottom:1px solid var(--sh-line);cursor:default}
body.ui .sec-head .sec-no{display:block;margin-bottom:6px;font-family:"JetBrains Mono",ui-monospace,monospace;font-size:11.5px;font-weight:500;color:var(--sh-muted)}
body.ui .sec-head h2{font-size:17px;font-weight:600;letter-spacing:-.015em}
body.ui .sec-head p{max-width:none;margin-top:4px;font-size:14px;color:var(--sh-text);opacity:.6}
body.ui .sec-head .sec-tog{display:none}
.lib-sec.filtered-out,.comp.filtered-out{display:none!important}
@media (max-width:960px){ .intro p{max-width:none} }
@media (max-width:640px){ body.ui .top .flt-btn .lbl{display:none} }

/* workspace rail: collapsed state keeps the toggle and real icons */
.sb.mini .sb-ws{flex-direction:column;align-items:center;gap:10px;padding:12px 0}
.sb.mini .sb-ws .t{display:none}
.sb.mini .sb-tog{margin-left:0}
.sb-it.chat-it .ms{flex:none;font-size:16px}
.sb-it.chat-it:nth-of-type(1) .ms{color:#5d9bfb}
.sb-it.chat-it:nth-of-type(2) .ms{color:#a993ff}
.sb-it.chat-it:nth-of-type(3) .ms{color:#38bf86}
.sb.mini .sb-up{padding:8px 0}
.sb.mini .sb-up .lbl{display:none}
.sb.mini .sb-sec{justify-content:center;padding:12px 0 6px}
.sb.mini .sb-sec::before{content:"";width:18px;height:1px;background:var(--line)}
.sb.mini .sb-sec .lbl{display:none}

@media (prefers-color-scheme: dark){ [data-style="soft"]:not([data-theme="light"]) .l1{background:rgba(47,128,255,.22)} [data-style="soft"]:not([data-theme="light"]) .l2{background:rgba(47,128,255,.42)} [data-style="soft"]:not([data-theme="light"]) .l3{background:rgba(47,128,255,.68)} [data-style="soft"]:not([data-theme="light"]) .nt-it.unread{background:rgba(47,128,255,.06)} [data-style="soft"]:not([data-theme="light"]) .bt-secondary{border-color:rgba(255,255,255,.16)} }
/* ================= Shell, round 4 ================= */
/* switchers keep their rounded-square shape, only buttons are pills */
body.ui .top .style-seg{border-radius:10px}
body.ui .top .style-seg .seg-ind{border-radius:7px}
body.ui .top .style-seg button{border-radius:7px}
body.ui .comp-foot .tabs{border-radius:9px}
body.ui .comp-foot .tabs .ind{border-radius:7px}
body.ui .comp-foot .tab{border-radius:7px}
body.ui .cd-tabs{border-radius:8px}
body.ui .cd-tab{border-radius:6px}
/* sidebar tree: no rule under group names, indented list with a guide line */
.side-h{border-bottom:0;margin-bottom:2px}
.side-ul{margin:0 0 6px 13px;padding-left:10px;border-left:1px solid var(--sh-line)}
.side-ul .side-a{padding:5px 10px}
.side-grp{margin-bottom:4px}
/* intro heading runs the full width */
.intro h1{max-width:none}
/* theme changes apply instantly */
html.no-trans *,html.no-trans *::before,html.no-trans *::after{transition:none!important}
html.no-trans .theme-sw .ts-thumb{transition:transform .45s cubic-bezier(.34,1.56,.64,1)!important}
html.no-trans .theme-sw .ts-ic{transition:color .3s ease,transform .45s var(--ease)!important}
/* sidebar CTA */
.side-pitch{margin-top:14px}
.side-pitch .t{font-size:13px;font-weight:600;color:var(--sh-text);line-height:1.4}
.side-pitch .d{margin:3px 0 0 !important;font-size:12.5px;line-height:1.5;color:var(--sh-dim) !important}
.hire-btn{background:var(--sh-chip)}
.hire-btn::before{inset:auto;left:var(--x,50%);top:var(--y,50%);width:260px;height:260px;margin:-130px 0 0 -130px;border-radius:50%;transform:scale(0);transition:transform .6s cubic-bezier(.22,1,.36,1),opacity .3s ease;opacity:.9}
.hire-btn:hover::before{transform:scale(1);opacity:1}
.hire-btn::after{animation:none;opacity:0}
.hire-btn:hover::after{animation:hire-gloss 1s ease .38s 1 both}
@keyframes hire-gloss{0%{opacity:1;background-position:160% 0}100%{opacity:1;background-position:-60% 0}}

/* ---------- permission gate, stepped ---------- */
#pg{max-width:360px}
.pg-hero{display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:18px 16px 14px}
.pg-hero .nbox{width:36px;height:36px;margin-bottom:8px;box-shadow:none;border-color:var(--accent-icon-line);background:var(--accent-icon-bg);color:var(--accent)}
.pg-q{font-weight:600;font-size:15px;line-height:1.35}
.pg-q.sm{font-size:14px}
.pg-d{margin-top:0;font-size:13px;line-height:1.45;color:var(--text-dim)}
.pg-sub{padding:14px 16px 4px}
.pg-scopes{border-top:0;padding:2px 0 8px}
.pg-st{display:flex;flex-direction:column;align-items:flex-start;gap:1px}
.pg-sd{font-size:12px;color:var(--muted)}
.pg-durs{display:flex;flex-direction:column;padding:2px 0 8px}
.pg-dur{display:flex;align-items:center;gap:12px;width:100%;padding:9px 16px;border:0;border-top:0;font-size:13px;text-align:left;color:var(--text-dim);transition:color .2s}
.pg-dur.on{color:var(--text)}
.pg-dur .pg-sd{margin-left:auto}
.pg-rd{width:14px;height:14px;flex:none;border-radius:50%;border:1px solid var(--icon-line);transition:border .2s}
.pg-dur.on .pg-rd{border:4px solid var(--accent)}
.pg-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 16px;border-top:1px solid var(--line)}
.pg-steps{display:flex;gap:4px}
.pg-steps i{width:14px;height:3px;border-radius:2px;background:var(--line);transition:background-color .3s}
.pg-steps i.on{background:var(--accent)}
.pg-btns{display:flex;gap:8px}
.pg-done{display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:18px 16px 16px}
.pg-done .nbox{box-shadow:none;margin-bottom:8px}
.pg-done .btn{margin-top:10px}
/* reactions: emoji floats up from the button */
.rx{position:relative}
/* soft: one button height inside components */
[data-style="soft"] .comp:not(#c49) .btn{height:32px;padding:0 14px;font-size:13px;line-height:1;border-radius:10px;align-items:center}
[data-style="soft"] .comp:not(#c49) .bt:not(.bt-icon){height:32px;padding:0 13px;font-size:13px;border-radius:10px}
[data-style="soft"] .comp:not(#c49) .ghost{height:32px;padding:0 12px}
[data-style="soft"] .sn #sn-go,[data-style="soft"] .fm .fm-submit{height:44px;font-size:14px;border-radius:12px}
[data-style="soft"] .ft-go{height:32px}
@supports (corner-shape: squircle){ [data-style="soft"] .comp:not(#c49) .btn,[data-style="soft"] .comp:not(#c49) .bt:not(.bt-icon){border-radius:15px} [data-style="soft"] .sn #sn-go,[data-style="soft"] .fm .fm-submit{border-radius:18px} }
/* source stack: more room between cards, a quiet fill for the selected one */
[data-style="soft"] .ctx-list{gap:6px}
[data-style="soft"] .ctx-card{margin-top:0}
[data-style="soft"] .ctx-card .node.on{background-color:var(--stage);border-color:var(--line);box-shadow:none}
/* automation canvas: blue in light mode, white outline and lines in dark */
[data-style="soft"] .fnode .node.on{background-color:var(--pb-bg);border-color:var(--pb-line);box-shadow:inset 0 0 0 1px var(--accent)}
[data-style="soft"] .fnode .node.on .ftop .ms,[data-style="soft"] .fnode .node.on .ft{color:var(--pb-tx)}
[data-style="soft"] .blabel.lit{color:var(--pb-tx)}
@media (prefers-color-scheme: dark){
  [data-style="soft"]:not([data-theme="light"]) .fnode .node.on{background-color:var(--panel);border-color:var(--text);box-shadow:none}
  [data-style="soft"]:not([data-theme="light"]) .fnode .node.on .ftop .ms,[data-style="soft"]:not([data-theme="light"]) .fnode .node.on .ft{color:var(--text)}
  [data-style="soft"]:not([data-theme="light"]) .blabel.lit{color:var(--text)}
  [data-style="soft"]:not([data-theme="light"]) .wire.lit,[data-style="soft"]:not([data-theme="light"]) .wire-flow{stroke:var(--text)}
  [data-style="soft"]:not([data-theme="light"]) .ctx-card .node.on{background-color:rgba(255,255,255,.04)}
}
[data-style="soft"][data-theme="dark"] .fnode .node.on{background-color:var(--panel);border-color:var(--text);box-shadow:none}
[data-style="soft"][data-theme="dark"] .fnode .node.on .ftop .ms,[data-style="soft"][data-theme="dark"] .fnode .node.on .ft{color:var(--text)}
[data-style="soft"][data-theme="dark"] .blabel.lit{color:var(--text)}
[data-style="soft"][data-theme="dark"] .wire.lit,[data-style="soft"][data-theme="dark"] .wire-flow{stroke:var(--text)}
[data-style="soft"][data-theme="dark"] .ctx-card .node.on{background-color:rgba(255,255,255,.04)}
/* sidebar footer, four lines */
.side-foot .side-cta-t{margin:2px 0 0 !important;font-size:13px;font-weight:600;line-height:1.4;color:var(--sh-text) !important}

/* ================= Shell, round 5 ================= */
/* component buttons appear on hover */
body.ui .stage>.code-btns{display:flex;gap:6px;opacity:0;transform:translateY(-4px);transition:opacity .25s ease,transform .35s cubic-bezier(.16,1,.3,1)}
body.ui .comp:hover .stage>.code-btns,body.ui .comp:focus-within .stage>.code-btns{opacity:1;transform:none}
@media (hover:none){ body.ui .stage>.code-btns{opacity:1;transform:none} }
body.ui .code-btns .anim-btn .ms{color:var(--sh-blue);transition:transform .55s cubic-bezier(.34,1.56,.64,1)}
body.ui .code-btns .anim-btn:hover{background:rgba(17,111,248,.07);border-color:rgba(17,111,248,.28);color:var(--sh-text)}
body.ui .code-btns .anim-btn:hover .ms{transform:rotate(72deg) scale(1.18)}
body.ui .code-btns .anim-btn.anim-go .ms{animation:anim-spin .8s cubic-bezier(.16,1,.3,1)}
@keyframes anim-spin{0%{transform:rotate(0) scale(1)}40%{transform:rotate(200deg) scale(1.35)}100%{transform:rotate(360deg) scale(1)}}
/* code modal */
.cdm{position:fixed;inset:0;z-index:100;display:grid;place-items:center;padding:24px;visibility:hidden;pointer-events:none}
.cdm.open{visibility:visible;pointer-events:auto}
.cdm-bg{position:absolute;inset:0;background:rgba(10,10,12,.34);-webkit-backdrop-filter:blur(3px);backdrop-filter:blur(3px);opacity:0;transition:opacity .3s ease}
.cdm.open .cdm-bg{opacity:1}
.cdm-box{position:relative;display:flex;flex-direction:column;width:100%;max-width:900px;height:min(86vh,920px);background:var(--sh-card);border:1px solid var(--sh-line);border-radius:18px;box-shadow:0 30px 80px -30px rgba(0,0,0,.45);overflow:hidden;opacity:0;transform:translateY(14px) scale(.98);transition:opacity .25s ease,transform .5s cubic-bezier(.16,1,.3,1)}
.cdm.open .cdm-box{opacity:1;transform:none}
.cdm-head{display:flex;justify-content:space-between;gap:16px;padding:18px 20px 16px;border-bottom:1px solid var(--sh-line)}
.cdm-meta{min-width:0}
.cdm-t{font-size:15px;font-weight:600;color:var(--sh-text)}
.cdm-path{margin-top:2px;font-family:"JetBrains Mono",ui-monospace,monospace;font-size:12px;color:var(--sh-muted)}
.cdm-note{margin-top:6px;font-size:13px;color:var(--sh-dim)}
.cdm-cmd{display:inline-flex;align-items:center;gap:8px;max-width:100%;margin-top:12px;padding:6px 8px 6px 10px;border-radius:9px;background:var(--sh-stage);border:1px solid var(--sh-line);font-family:"JetBrains Mono",ui-monospace,monospace;font-size:12px;color:var(--sh-dim);transition:border-color .2s}
.cdm-cmd:hover{border-color:var(--sh-line-2)}
.cdm-cmd .c{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cdm-cmd .d,.cdm-cmd .ms{color:var(--sh-muted);flex:none}
.cdm-acts{display:flex;align-items:flex-start;gap:6px;flex:none}
.cdm-copy{height:32px;padding:0 15px;border-radius:999px;background:var(--sh-ink);color:var(--sh-on-ink);font-size:13px;font-weight:600;transition:opacity .2s}
.cdm-copy:hover{opacity:.88}
.cdm-x{width:32px;height:32px;display:grid;place-items:center;border-radius:999px;color:var(--sh-dim);transition:background-color .2s,color .2s}
.cdm-x:hover{background:var(--sh-chip);color:var(--sh-text)}
.cdm-tabs{display:flex;align-items:center;gap:4px;padding:10px 20px;border-bottom:1px solid var(--sh-line)}
.cdm-tab{height:28px;padding:0 11px;border-radius:7px;font-size:12.5px;font-weight:500;color:var(--sh-dim);transition:background-color .2s,color .2s}
.cdm-tab:hover{color:var(--sh-text)}
.cdm-tab[aria-selected="true"]{background:var(--sh-chip);color:var(--sh-text)}
.cdm-lines{margin-left:auto;font-size:12px;color:var(--sh-muted)}
.cd-pre.cdm-pre{flex:1;min-height:0;max-height:none;margin:0;padding:16px 0;overflow:auto;background:var(--sh-stage);color:var(--sh-text)}
.cdm-foot{display:flex;align-items:center;gap:8px;padding:12px 20px;border-top:1px solid var(--sh-line);font-size:12.5px;color:var(--sh-dim)}
.cdm-foot .ms{color:var(--sh-muted)}
.cdm-shared{margin-left:auto;display:inline-flex;align-items:center;gap:4px;font-weight:600;color:var(--sh-text);white-space:nowrap}
@media (max-width:640px){ .cdm{padding:10px} .cdm-foot span{display:none} }
/* header */
body.ui .top .flt-btn{padding:0 11px 0 13px}
body.ui .top #sound-btn{width:32px;padding:0;justify-content:center}
body.ui .top #sound-btn .lbl{display:none}
.theme-sw{padding:0;box-sizing:border-box}
.theme-sw .ts-thumb{top:2px;left:2px;width:26px;height:26px}
.theme-sw .ts-ic{height:100%}
.theme-sw[aria-checked="true"] .ts-thumb{transform:translateX(32px)}
body.ui .brand{position:relative}
body.ui .brand::after{content:"";position:absolute;inset:0;pointer-events:none;-webkit-mask:var(--logo-mask) center/100% 100% no-repeat;mask:var(--logo-mask) center/100% 100% no-repeat;background:linear-gradient(115deg,transparent 38%,rgba(255,255,255,.9) 50%,transparent 62%);background-size:260% 100%;background-position:160% 0}
