/* rewrite toolbar: edit field, two actions and a chevron that slides out the rest */
.sel-bar{display:flex;align-items:center;height:44px;padding:0 4px 0 6px;overflow:hidden;white-space:nowrap;transition:opacity .2s ease,transform .3s var(--ease),width .5s var(--ease),left .5s var(--ease)}
.sel-view{flex:1;min-width:0;height:100%;overflow:hidden}
.sel-track{display:flex;align-items:center;gap:2px;height:100%;transition:transform .5s var(--ease)}
.sel-inw{flex:none;width:150px;display:flex;align-items:center;padding:0 8px;transition:opacity .3s ease}
.sel-bar.exp .sel-inw,.sel-bar.exp .sel-div{opacity:0}
.sel-inw input{width:100%;background:transparent;border:0;outline:0;font:inherit;font-size:13px;color:var(--text)}
.sel-inw input::placeholder{color:var(--muted)}
.sel-div{flex:none;width:1px;height:20px;margin:0 4px;background:var(--line);transition:opacity .3s ease}
.sel-acts{display:flex;gap:2px;flex:none}
.sel-bar .sel-acts button{display:inline-flex;align-items:center;gap:6px;height:34px;padding:0 10px;border:0;font-size:13px;font-weight:500;color:var(--text-dim);transition:color .2s,background-color .2s}
.sel-bar .sel-acts button:hover{color:var(--text);background:var(--chip)}
.sel-bar .sel-more{flex:none;width:32px;height:32px;padding:0;display:grid;place-items:center;border:0;border-left:0;color:var(--muted)}
.sel-bar .sel-more .ms{transition:transform .45s var(--ease)}
.sel-bar.exp .sel-more .ms{transform:rotate(180deg)}
.sel-bar .sel-more:hover{color:var(--text)}
[data-style="soft"] .sel-bar{border-radius:999px;padding:0 4px 0 8px}
[data-style="soft"] .sel-bar .sel-acts button{border-radius:999px}
[data-style="soft"] .sel-bar .sel-more{border-radius:50%}
[data-style="soft"] .sent.picked{background:rgba(17,111,248,.12);box-shadow:none;border:0;outline:0}
