.f-menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.f-mi{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px;font-size:13px;font-weight:500;color:var(--text);text-align:left;transition:background-color .15s}
