/* ================= Round 8: sign up ================= */
.su{margin-top:22px;max-width:560px}
.su-t{font-size:14.5px;font-weight:600;color:var(--sh-text)}
.su-d{margin-top:2px;font-size:13.5px;line-height:1.5;color:var(--sh-dim)}
.su-row{display:flex;gap:8px;max-width:440px;margin-top:12px}
.su-row input{flex:1;min-width:0;height:40px;padding:0 16px;border-radius:999px;border:1px solid var(--sh-line);background:var(--sh-card);font:inherit;font-size:14px;color:var(--sh-text);outline:0;transition:border-color .2s,box-shadow .2s}
.su-row input:focus{border-color:var(--sh-blue);box-shadow:0 0 0 3px rgba(17,111,248,.12)}
.su-row.bad input{border-color:#e5484d;animation:su-shake .4s}
@keyframes su-shake{20%,60%{transform:translateX(-4px)}40%,80%{transform:translateX(4px)}}
.su-btn{height:40px;padding:0 20px;border-radius:999px;background:var(--sh-ink);color:var(--sh-on-ink);font-size:13.5px;font-weight:600;white-space:nowrap;transition:opacity .2s,transform .15s}
