.su-ok{display:inline-flex;align-items:center;gap:8px;margin-top:12px;padding:9px 14px;border-radius:999px;background:rgba(21,154,99,.1);color:#159a63;font-size:13.5px;font-weight:500}

/* ================= Round 9 ================= */
.sc-t{transform-box:fill-box;transform-origin:center}
.hm-days{justify-items:end;text-align:right}
.hm-days span:nth-child(4){grid-row:7}
/* agenda: hatched gap between days, even spacing between cards */
.agd-g{position:relative}
.agd-g:not(:first-child){margin-top:12px}
.agd-g:not(:first-child)::before{content:"";position:absolute;left:0;right:0;top:-13px;height:12px;background:repeating-linear-gradient(135deg,var(--line) 0 1px,transparent 1px 7px);pointer-events:none}
.agd-g{padding-top:12px;padding-bottom:12px}
.agd-day{margin:-12px 0;padding-top:16px}
.agd-list{gap:25px}
.agd-list>.agd-c:not(:last-child)::after{bottom:-13px}
