/* accent colours ease from one to the next */
@property --accent{syntax:'<color>';inherits:true;initial-value:#ff850d}
@property --accent-hi{syntax:'<color>';inherits:true;initial-value:#ff850d}
@property --accent-bg{syntax:'<color>';inherits:true;initial-value:transparent}
@property --accent-fill{syntax:'<color>';inherits:true;initial-value:transparent}
@property --accent-icon-line{syntax:'<color>';inherits:true;initial-value:transparent}
@property --accent-icon-bg{syntax:'<color>';inherits:true;initial-value:transparent}
@property --ink{syntax:'<color>';inherits:true;initial-value:#116ff8}
:root{transition:--accent .5s ease,--accent-hi .5s ease,--accent-bg .5s ease,--accent-fill .5s ease,--accent-icon-line .5s ease,--accent-icon-bg .5s ease,--ink .5s ease}
