.acc-row{flex-wrap:nowrap}
.m-acc{flex-wrap:wrap}
.m-sheet .acc{display:none}
/* style switch: icons, a springy indicator and an eased page swap */
.ss-ic{width:14px;height:14px;flex:none;fill:currentColor;transform-origin:50% 60%;transition:opacity .3s ease,color .3s ease}
.style-seg button{display:inline-flex;align-items:center;gap:6px}
.style-seg button:not(.on) .ss-ic{opacity:.6}
body.ui .top .style-seg .seg-ind,.m-sheet #style-seg .seg-ind{transition:transform .55s cubic-bezier(.34,1.25,.64,1),width .55s cubic-bezier(.34,1.25,.64,1)}
body.ui .top .style-seg button{transition:color .3s ease}
.top{view-transition-name:topbar}
::view-transition-old(root),::view-transition-new(root){animation-duration:.42s;animation-timing-function:cubic-bezier(.4,0,.2,1)}
::view-transition-old(topbar){display:none}
::view-transition-new(topbar){animation:none}
@media (prefers-reduced-motion: reduce){ .ss-ic{transition:none} }
/* style switch: the pill slides with the same plush spring as the light and dark switch, even while the page restyles */
body.ui .top .style-seg .seg-ind,.m-sheet #style-seg .seg-ind,
html.theming body.ui .top .style-seg .seg-ind,html.theming .m-sheet #style-seg .seg-ind,
html.no-trans body.ui .top .style-seg .seg-ind,html.no-trans .m-sheet #style-seg .seg-ind{transition:transform .45s cubic-bezier(.34,1.56,.64,1),width .45s cubic-bezier(.34,1.56,.64,1)!important}
html.theming .style-seg button,html.no-trans .style-seg button{transition:color .3s ease!important}
html.theming .style-seg .ss-ic,html.no-trans .style-seg .ss-ic{transition:opacity .3s ease!important}
/* see it in action */
.pv.pv-wide .pv-in{max-width:none;padding:20px 24px 40px}
.dm-wrap{display:grid;grid-template-columns:360px minmax(0,1fr);gap:20px;align-items:start}
.dm-chat{position:sticky;top:72px;height:calc(100vh - 96px);display:flex;flex-direction:column;background:var(--sh-card);border:1px solid var(--sh-line);border-radius:22px;overflow:hidden}
@supports (corner-shape: squircle){ .dm-chat,.dm-board{corner-shape:squircle;border-radius:32px} }
.dm-ch{display:flex;align-items:center;gap:8px;padding:14px 16px;border-bottom:1px solid var(--sh-line);font-size:14px;font-weight:600;color:var(--sh-text)}
.dm-live{margin-left:auto;padding:2px 8px;border-radius:999px;background:var(--sh-chip);font-size:11.5px;font-weight:600;color:var(--sh-dim)}
.dm-msgs{flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:12px;padding:16px}
.dm-m{font-size:14px;line-height:1.55;color:var(--sh-text)}
.dm-m.u{align-self:flex-end;max-width:85%;padding:9px 13px;border-radius:16px 16px 4px 16px;background:var(--sh-ink);color:var(--sh-on-ink)}
.dm-m.a{color:var(--sh-dim)}
.dm-reply{margin:0;color:var(--sh-text)}
.dm-think{padding:10px 12px;border:1px solid var(--sh-line);border-radius:14px;background:var(--sh-bg)}
.dm-think-h{display:flex;align-items:center;gap:8px;font-size:13px;font-weight:600;color:var(--sh-text)}
.dm-steps{display:flex;flex-direction:column;gap:6px;margin-top:8px}
.dm-step{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--sh-muted);opacity:.45;transition:opacity .3s ease,color .3s ease}
.dm-step .ms{opacity:0;transform:scale(.6);transition:opacity .25s ease,transform .35s cubic-bezier(.34,1.56,.64,1);color:#2f9e6a}
.dm-step.on{opacity:1;color:var(--sh-dim)}
.dm-step.on .ms{opacity:1;transform:none}
.dm-used{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.dm-u{padding:4px 10px;border-radius:999px;border:1px solid var(--sh-line);background:var(--sh-card);font-size:12.5px;font-weight:500;color:var(--sh-text);transition:border-color .2s}
.dm-u:hover{border-color:var(--sh-line-2)}
.dm-chips{display:flex;flex-direction:column;gap:6px;padding:0 16px 12px}
.dm-chip{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;border:1px solid var(--sh-line);background:var(--sh-card);font-size:13.5px;font-weight:500;color:var(--sh-text);text-align:left;transition:border-color .2s,background-color .2s}
.dm-chip:hover:not(:disabled),.dm-chip.on{border-color:var(--sh-line-2);background:var(--sh-bg)}
.dm-chip:disabled{opacity:.55;cursor:default}
.dm-in{display:flex;align-items:center;gap:8px;margin:0 12px 12px;padding:5px 5px 5px 14px;border:1px solid var(--sh-line);border-radius:999px;background:var(--sh-bg)}
.dm-in input{flex:1;min-width:0;height:34px;border:0;background:transparent;outline:0;font:inherit;font-size:14px;color:var(--sh-text)}
.dm-in button{display:grid;place-items:center;width:34px;height:34px;border-radius:999px;background:var(--sh-ink);color:var(--sh-on-ink)}
.dm-board{min-height:calc(100vh - 96px);padding:20px;border:1px solid var(--sh-line);border-radius:22px;background:var(--bg);display:flex;flex-direction:column;gap:16px}
.dm-empty{margin:auto;max-width:440px;text-align:center;display:flex;flex-direction:column;gap:10px;align-items:center}
.dm-empty-t{font-size:22px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.dm-empty-d{font-size:14px;line-height:1.6;color:var(--text-dim)}
.dm-row{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:16px;align-items:start}
.dm-cell{position:relative;min-width:0}
.dm-tag{position:absolute;z-index:5;top:-11px;left:14px;display:inline-flex;align-items:center;gap:5px;padding:3px 9px;border-radius:999px;background:var(--sh-ink);color:var(--sh-on-ink);font-size:11.5px;font-weight:600;opacity:0;transform:translateY(4px);transition:opacity .2s ease,transform .25s cubic-bezier(.16,1,.3,1);pointer-events:none}
.dm-tag i{font-style:normal;padding:0 5px;border-radius:999px;background:var(--accent-hi);color:var(--on-accent,#120a02);font-size:10.5px}
.dm-cell:hover .dm-tag{opacity:1;transform:none;pointer-events:auto}
.dm-cell:hover > .comp .panel,.dm-cell:hover > .dm-pipe{outline:1.5px dashed var(--sh-line-2);outline-offset:4px}
body.ui .dm-cell > .comp{max-width:none!important;margin:0!important;border:0!important;background:none!important;box-shadow:none!important;padding:0!important}
body.ui .dm-cell > .comp > .comp-head,body.ui .dm-cell > .comp > .comp-foot,body.ui .dm-cell .code-btns{display:none!important}
body.ui .dm-cell > .comp .stage{min-height:0!important;padding:0!important;background:none!important;border:0!important;box-shadow:none!important}
body.ui .dm-cell > .comp .stage-inner{min-height:0!important;padding:0!important;display:block!important}
body.ui .dm-cell > .comp .stage-inner > *{max-width:none!important;width:100%!important;margin-left:0!important;margin-right:0!important}
/* dashboard top bar and deal pipeline, built for the demos */
.dm-tb{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 18px;background:var(--panel);border:1px solid var(--line)}
.dm-tb-t{margin-top:2px;font-size:20px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.dm-tb-r{display:flex;align-items:center;gap:10px}
.dm-range{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 10px;border:1px solid var(--icon-line);font-size:12.5px;font-weight:500;color:var(--text)}
.dm-avs{display:flex}
.dm-avs > *{width:26px;height:26px;margin-left:-6px;border-radius:50%;box-shadow:0 0 0 2px var(--panel)}
.dm-avs > *:first-child{margin-left:0}
.dm-pipe{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:14px;background:var(--panel);border:1px solid var(--line)}
.dm-col{display:flex;flex-direction:column;gap:8px;padding:10px;background:var(--bg);border:1px solid transparent;transition:border-color .2s,background-color .2s}
.dm-col.over{border-color:var(--accent);background:var(--accent-bg)}
.dm-col-h{display:flex;align-items:center;justify-content:space-between}
.dm-col-n{font-size:13.5px;font-weight:600;color:var(--text)}
.dm-col-b{display:flex;flex-direction:column;gap:8px;min-height:120px}
.dm-deal{padding:10px 12px;background:var(--panel);border:1px solid var(--line);cursor:grab;transition:box-shadow .2s,border-color .2s}
.dm-deal:hover{border-color:var(--icon-line)}
.dm-deal.drag{opacity:.5}
.dm-deal-t{font-size:13.5px;font-weight:600;color:var(--text)}
.dm-deal-f{display:flex;align-items:center;justify-content:space-between;margin-top:8px}
.dm-deal-v{font-family:var(--mono);font-size:12px;font-weight:700;color:var(--text-dim)}
.dm-deal-f > :last-child{width:22px;height:22px;border-radius:50%}
[data-style="soft"] .dm-tb,[data-style="soft"] .dm-pipe{border-radius:20px}
[data-style="soft"] .dm-range{border-radius:10px}
[data-style="soft"] .dm-col{border-radius:14px}
[data-style="soft"] .dm-deal{border-radius:12px}
[data-style="soft"] .dm-deal-v{font-family:var(--sans)}
@media (max-width:960px){
  .dm-wrap{grid-template-columns:1fr}
  .dm-chat{position:static;height:auto;max-height:none}
  .dm-msgs{max-height:300px}
  .dm-row{grid-template-columns:1fr}
  .dm-cell{grid-column:auto!important}
  .dm-pipe{grid-template-columns:1fr 1fr}
  .dm-tb{flex-wrap:wrap}
}
/* The Lab */
.lab-link{display:inline-flex!important;align-items:center;gap:6px}
.lab-ic{width:15px;height:15px;fill:currentColor;flex:none}
.top-links .lab-link .lab-ic{color:var(--accent-hi)}
.dm-empty{margin:auto;width:100%;max-width:620px;display:flex;flex-direction:column;align-items:center;gap:12px;text-align:center;padding:24px 0}
.dm-empty-t{max-width:520px;font-size:26px;line-height:1.25;font-weight:600;letter-spacing:-.02em;color:var(--text);text-wrap:balance}
.dm-empty-d{max-width:460px;font-size:14.5px;line-height:1.6;color:var(--text-dim);text-wrap:balance}
/* looping skeleton preview */
.sk-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;width:100%;margin-top:28px;text-align:left}
.sk-card{display:flex;flex-direction:column;gap:10px;min-height:118px;padding:16px;background:var(--panel);border:1px solid var(--line);animation:skIn 7s cubic-bezier(.16,1,.3,1) infinite;animation-delay:var(--d)}
@keyframes skIn{0%{opacity:0;transform:translateY(12px);filter:blur(8px)}12%,82%{opacity:1;transform:none;filter:blur(0)}96%,100%{opacity:0;transform:translateY(-8px);filter:blur(5px)}}
.sk{display:block;height:9px;background:linear-gradient(90deg,var(--chip,rgba(17,19,24,.06)) 0%,color-mix(in srgb,var(--chip,rgba(17,19,24,.06)) 35%,var(--panel)) 50%,var(--chip,rgba(17,19,24,.06)) 100%);background-size:220% 100%;animation:skShim 1.5s linear infinite}
@keyframes skShim{from{background-position:120% 0}to{background-position:-120% 0}}
.sk-n{height:22px;width:58%}
.sk-spark{width:100%;height:44px;margin-top:auto;overflow:visible}
.sk-spark path{fill:none;stroke:var(--accent-hi);stroke-width:2.5;stroke-linejoin:round;stroke-linecap:round;stroke-dasharray:260;stroke-dashoffset:260;animation:skDraw 7s ease-in-out infinite;animation-delay:.4s}
@keyframes skDraw{0%,8%{stroke-dashoffset:260}35%,82%{stroke-dashoffset:0}100%{stroke-dashoffset:0;opacity:0}}
.sk-bars{display:flex;align-items:flex-end;gap:8px;height:72px;margin-top:auto}
.sk-bars i{flex:1;height:100%;background:var(--accent-hi);transform-origin:bottom;transform:scaleY(.12);opacity:.9;animation:skBar 7s cubic-bezier(.34,1.3,.64,1) infinite;animation-delay:calc(.5s + var(--i) * .07s)}
@keyframes skBar{0%,8%{transform:scaleY(.12)}30%,82%{transform:scaleY(var(--h))}100%{transform:scaleY(.12)}}
.sk-row{display:flex;align-items:center;gap:10px}
.sk-av{width:26px;height:26px;flex:none;border-radius:50%}
.sk-lines{flex:1;display:flex;flex-direction:column;gap:6px}
.sk-lines .sk{height:8px}
.sk-bub{display:flex;flex-direction:column;gap:6px;max-width:80%;padding:10px 12px;background:var(--bg)}
.sk-bub.r{align-self:flex-end;background:var(--accent-bg)}
.sk-dots{display:flex;gap:4px;padding:4px 2px}
.sk-dots i{width:6px;height:6px;border-radius:50%;background:var(--muted);animation:skDot 1.2s ease-in-out infinite}
.sk-dots i:nth-child(2){animation-delay:.15s}.sk-dots i:nth-child(3){animation-delay:.3s}
@keyframes skDot{0%,60%,100%{opacity:.3;transform:none}30%{opacity:1;transform:translateY(-3px)}}
[data-style="soft"] .sk-card{border-radius:18px}
[data-style="soft"] .sk{border-radius:999px}
[data-style="soft"] .sk-bars i{border-radius:6px 6px 2px 2px}
[data-style="soft"] .sk-bub{border-radius:14px}
@media (prefers-reduced-motion: reduce){ .sk-card,.sk,.sk-spark path,.sk-bars i,.sk-dots i{animation:none!important;opacity:1;filter:none;transform:none} .sk-spark path{stroke-dashoffset:0} .sk-bars i{transform:scaleY(var(--h))} }
/* the Lab assistant */
.lab-bot{position:fixed;right:24px;bottom:24px;z-index:80;display:flex;align-items:flex-end;gap:10px;pointer-events:none}
.lab-face{pointer-events:auto;display:grid;place-items:center;width:56px;height:56px;border-radius:50%;background:var(--sh-ink);color:var(--sh-on-ink);box-shadow:0 10px 28px -10px rgba(17,19,24,.45),0 0 0 4px var(--sh-card);transform:scale(0);transition:transform .5s cubic-bezier(.34,1.56,.64,1)}
.lab-bot.in .lab-face{transform:scale(1);animation:labBob 3.2s ease-in-out 1s infinite}
.lab-face svg{width:34px;height:34px}
@keyframes labBob{0%,100%{translate:0 0}50%{translate:0 -3px}}
.lab-say{pointer-events:auto;max-width:260px;padding:11px 14px;border-radius:16px;background:var(--sh-card);border:1px solid var(--sh-line);box-shadow:0 16px 36px -18px rgba(17,19,24,.35);font-size:13.5px;line-height:1.5;color:var(--sh-text);opacity:0;transform:translateY(6px) scale(.96);transition:opacity .25s ease,transform .4s cubic-bezier(.34,1.4,.64,1);pointer-events:none}
.lab-say.show{opacity:1;transform:none}
.lab-bot[data-side="home"] .lab-say{border-bottom-right-radius:4px;margin-bottom:34px}
.lab-bot[data-side="right"]{flex-direction:row-reverse}
.lab-bot[data-side="right"] .lab-say{border-bottom-left-radius:4px;margin-bottom:34px}
.dm-sug{margin-top:8px}
@media (prefers-reduced-motion: reduce){ .lab-bot.in .lab-face{animation:none} }
/* the assistant's bubble is placed around the face, so the face never shifts */
.lab-bot{display:block;width:56px;height:56px}
.lab-say{position:absolute;width:max-content;max-width:260px}
.lab-bot[data-side="home"] .lab-say,.lab-bot:not([data-side]) .lab-say{right:0;bottom:70px;margin:0}
.lab-bot[data-side="right"] .lab-say{left:70px;bottom:14px;margin:0}
/* ================= The Lab, round 2 ================= */
.dm-board.has-app{padding:0;overflow:hidden;display:block;min-height:calc(100vh - 96px)}
.dm-chip span:first-of-type{flex:1}
.dm-soon{padding:1px 7px;border-radius:999px;background:var(--sh-chip);font-size:11px;font-weight:600;color:var(--sh-muted)}
/* skeleton preview, all neutral */
.sk-grid .sk-card{min-height:110px;justify-content:center}
.sk-grid .sk-n{height:20px;width:46%}
/* app frame */
.la{position:relative;display:grid;grid-template-columns:220px minmax(0,1fr);min-height:calc(100vh - 96px);background:var(--bg);transition:grid-template-columns .38s cubic-bezier(.16,1,.3,1)}
.la.slim{grid-template-columns:64px minmax(0,1fr)}
.la-side{position:sticky;top:0;align-self:start;height:calc(100vh - 96px);display:flex;flex-direction:column;gap:4px;padding:14px 10px;background:var(--panel);border-right:1px solid var(--line);overflow:hidden}
.la-ws{display:flex;align-items:center;gap:10px;padding:6px 8px 14px;color:var(--text)}
.la-logo{display:grid;place-items:center;width:28px;height:28px;flex:none;background:var(--accent-hi);color:var(--on-accent,#120a02);font-size:14px}
.la-wn{flex:1;font-size:14px;font-weight:600;white-space:nowrap}
.la-nav{display:flex;flex-direction:column;gap:2px}
.la-ni,.la-col{display:flex;align-items:center;gap:10px;height:36px;padding:0 10px;font-size:13.5px;font-weight:500;color:var(--text-dim);white-space:nowrap;transition:background-color .2s,color .2s}
.la-ni:hover,.la-col:hover{background:var(--chip,rgba(17,19,24,.05));color:var(--text)}
.la-ni.on{background:var(--accent-bg);color:var(--text);box-shadow:inset 2px 0 0 var(--accent)}
.la-ni span:first-of-type{flex:1;text-align:left}
.la-c{font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted)}
.la-col{margin-top:auto}
.la-me{display:flex;align-items:center;gap:10px;padding:10px 8px 2px;border-top:1px solid var(--line);white-space:nowrap}
.la-me > span:last-child{display:flex;flex-direction:column;font-size:12px;color:var(--muted)}
.la-me b{font-size:13px;font-weight:600;color:var(--text)}
.la-me .dz-av,.la-me .dz-av img{width:30px;height:30px}
.la.slim .la-wn,.la.slim .la-ws > .ms,.la.slim .la-ni span,.la.slim .la-col span,.la.slim .la-me > span:last-child{opacity:0;pointer-events:none}
.la-main{position:relative;min-width:0;display:flex;flex-direction:column}
.la-top{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 20px;background:var(--panel);border-bottom:1px solid var(--line)}
.la-t{margin-top:2px;font-size:20px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.la-tr{display:flex;align-items:center;gap:10px}
.la-body{padding:20px;display:flex;flex-direction:column;gap:16px}
/* KPI strip */
.lk{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));background:var(--panel);border:1px solid var(--line)}
.lk-i{display:flex;flex-direction:column;gap:6px;padding:14px 16px;min-width:0}
.lk-i + .lk-i{border-left:1px solid var(--line)}
.lk-l{font-size:12.5px;font-weight:500;color:var(--text-dim)}
.lk-row{display:flex;align-items:flex-end;justify-content:space-between;gap:8px}
.lk-v{font-size:24px;font-weight:600;letter-spacing:-.02em;color:var(--text);white-space:nowrap}
.lk-sp{width:80px;height:26px;flex:none;overflow:visible}
.lk-sp polyline{fill:none;stroke-width:1.8;stroke-linejoin:round;stroke-linecap:round;vector-effect:non-scaling-stroke}
.lk-sp.up polyline{stroke:var(--green,#159a63)}
.lk-sp.down polyline{stroke:var(--red,#e5484d)}
.lk-c{font-size:12px;font-weight:600}
.lk-c.up{color:var(--green,#159a63)}
.lk-c.down{color:var(--red,#e5484d)}
.lk-c span{font-weight:400;color:var(--muted)}
/* layout grid and cards */
.lg{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));grid-auto-rows:64px;gap:16px;grid-auto-flow:row dense}
.lc{position:relative;display:flex;flex-direction:column;min-width:0;min-height:0;background:var(--panel);border:1px solid var(--line);overflow:hidden}
.lc-h{display:flex;align-items:center;gap:10px;padding:12px 14px 10px}
.lc-grip{display:grid;grid-template-columns:repeat(2,3px);gap:3px;padding:4px 3px;cursor:grab;opacity:.45;transition:opacity .2s}
.lc-grip i{width:3px;height:3px;border-radius:50%;background:var(--text-dim)}
.lc:hover .lc-grip{opacity:1}
.lc-tt{flex:1;min-width:0;display:flex;flex-direction:column}
.lc-tt b{font-size:14px;font-weight:600;color:var(--text)}
.lc-tt span{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lc-lib,.lc-new{display:inline-flex;align-items:center;gap:4px;padding:3px 8px;font-size:11.5px;font-weight:600;white-space:nowrap}
.lc-lib{color:var(--text-dim);border:1px solid var(--line);opacity:0;transition:opacity .2s,color .2s}
.lc:hover .lc-lib{opacity:1}
.lc-lib:hover{color:var(--text)}
.lc-new{background:var(--accent-bg);color:var(--accent)}
.lc-b{flex:1;min-height:0;overflow:auto;padding:0 14px 14px}
.lc-rs{position:absolute;right:0;bottom:0;width:18px;height:18px;cursor:nwse-resize;opacity:0;transition:opacity .2s}
.lc-rs::after{content:"";position:absolute;right:4px;bottom:4px;width:8px;height:8px;border-right:2px solid var(--text-dim);border-bottom:2px solid var(--text-dim)}
.lc:hover .lc-rs{opacity:.7}
.lc.lifting{z-index:20;cursor:grabbing;box-shadow:0 24px 48px -16px rgba(17,19,24,.3);scale:1.01;transition:scale .2s}
.lc.lifting .lc-grip{cursor:grabbing}
.lc.sizing{z-index:20;outline:1.5px dashed var(--accent);outline-offset:3px}
.lg.busy{user-select:none}
/* blocks */
.lc-b .dm-pipe{height:100%;padding:0;border:0;background:none;grid-template-columns:repeat(4,minmax(150px,1fr))}
.lc-b .dm-col-b{min-height:0}
.lc-w{position:relative;width:100%;height:100%;min-height:120px}
.lc-w svg{display:block}
.lc-g line{stroke:var(--line);stroke-width:1}
.lc-g text{font-family:var(--mono);font-size:10.5px;font-weight:700;fill:var(--muted)}
.lc-l{fill:none;stroke:var(--accent-hi);stroke-width:2.2;stroke-linejoin:round;stroke-linecap:round}
.lc-l.tgt{stroke:var(--muted);stroke-dasharray:5 5;stroke-width:1.6}
.lc-a{fill:var(--accent-hi);opacity:.1}
.lc-x{stroke:var(--text-dim);stroke-dasharray:3 3}
.lc-d{fill:var(--panel);stroke:var(--accent-hi);stroke-width:2}
.lc-d.tgt{stroke:var(--muted)}
.lc-tip{position:absolute;left:0;top:0;display:flex;flex-direction:column;gap:3px;padding:8px 10px;background:var(--panel);border:1px solid var(--line);box-shadow:0 10px 24px -12px rgba(17,19,24,.3);font-size:12px;color:var(--text-dim);white-space:nowrap;opacity:0;pointer-events:none;transition:opacity .15s ease,transform .12s ease}
.lc-tip b{color:var(--text);font-size:12.5px}
.lc-tip i{display:inline-block;width:8px;height:2px;margin-right:6px;vertical-align:middle;background:var(--accent-hi)}
.lc-tip i.tgt{background:var(--muted)}
.lf{display:flex;flex-direction:column}
.lf-i{display:flex;align-items:center;gap:10px;padding:9px 0;border-top:1px solid var(--line)}
.lf-i:first-child{border-top:0}
.lf-ic{display:grid;place-items:center;width:28px;height:28px;flex:none;background:var(--bg);color:var(--text-dim)}
.lf-t{flex:1;min-width:0;font-size:13px;line-height:1.4;color:var(--text-dim)}
.lf-t b{font-weight:600;color:var(--text)}
.lf-t span{color:var(--muted)}
.lf-time{font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);white-space:nowrap}
.lt{display:flex;flex-direction:column;min-width:560px}
.lt-h,.lt-r{display:grid;grid-template-columns:minmax(180px,2fr) 1.2fr 1.1fr .8fr 1fr;align-items:center;gap:12px;padding:0 6px}
.lt-h{height:32px;font-family:var(--mono);font-size:11px;font-weight:700;text-transform:uppercase;color:var(--muted);border-bottom:1px solid var(--line)}
.lt-r{height:48px;width:100%;text-align:left;border-bottom:1px solid var(--line);transition:background-color .15s}
.lt-r:hover{background:var(--bg)}
.lt-co{display:flex;align-items:center;gap:10px;min-width:0}
.lt-co > span{display:flex;flex-direction:column;min-width:0}
.lt-lg{display:grid;place-items:center;width:28px;height:28px;flex:none;background:var(--bg);border:1px solid var(--line);font-size:12px;font-weight:700;color:var(--text)}
.lt-lg.big{width:40px;height:40px;font-size:16px}
.lt-n{font-size:13.5px;font-weight:600;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lt-s{font-size:12px;color:var(--muted)}
.lt-ow{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text)}
.lt-ow .dz-av,.lt-ow .dz-av img{width:22px;height:22px}
.lt-v{font-family:var(--mono);font-size:12.5px;font-weight:700;color:var(--text)}
.r{text-align:right}
.lfu{display:flex;flex-direction:column;justify-content:space-between;gap:12px;height:100%}
.lfu-top{display:flex;justify-content:space-between;font-size:13px;color:var(--text-dim)}
.lfu-top b{font-family:var(--mono);font-size:12.5px;color:var(--text)}
.lfu-bar{height:22px;margin-top:6px;background:var(--bg)}
.lfu-bar i{display:block;height:100%;width:var(--w);background:var(--accent-hi);transition:width .6s cubic-bezier(.16,1,.3,1)}
.lfu-drop{display:block;margin-top:4px;font-size:11.5px;color:var(--muted)}
.lso{display:flex;align-items:center;gap:24px;height:100%}
.lso-d{position:relative;width:min(48%,200px);aspect-ratio:1;flex:none}
.lso-d svg{width:100%;height:100%;transform:rotate(-90deg)}
.lso-s{fill:none;stroke-width:14;transition:opacity .2s,stroke-width .25s cubic-bezier(.34,1.56,.64,1)}
.lso-s:hover{stroke-width:17}
.s0{stroke:var(--accent-hi);background:var(--accent-hi)}
.s1{stroke:color-mix(in srgb,var(--accent-hi) 62%,var(--panel));background:color-mix(in srgb,var(--accent-hi) 62%,var(--panel))}
.s2{stroke:color-mix(in srgb,var(--accent-hi) 36%,var(--panel));background:color-mix(in srgb,var(--accent-hi) 36%,var(--panel))}
.s3{stroke:var(--icon-line);background:var(--icon-line)}
.lso-s.dim,.lso-li.dim{opacity:.3}
.lso-c{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}
.lso-c b{font-size:22px;font-weight:600;color:var(--text)}
.lso-c span{font-size:11.5px;color:var(--muted);max-width:80%}
.lso-l{flex:1;display:flex;flex-direction:column;gap:6px;min-width:0}
.lso-li{display:flex;align-items:center;gap:10px;padding:6px 0;font-size:13px;color:var(--text-dim);cursor:default;transition:opacity .2s}
.lso-li i{width:10px;height:10px;flex:none}
.lso-li span{flex:1}
.lso-li b{font-family:var(--mono);font-size:12.5px;color:var(--text)}
.lp{display:flex;flex-direction:column;gap:6px}
.lp-i{position:relative;display:flex;align-items:center;justify-content:space-between;height:34px;padding:0 10px;font-size:13px}
.lp-i::before{content:"";position:absolute;inset:0;width:var(--w);background:var(--accent-bg)}
.lp-p,.lp-i b{position:relative}
.lp-p{font-family:var(--mono);font-size:12px;font-weight:700;color:var(--text)}
.lp-i b{font-family:var(--mono);font-size:12px;color:var(--text-dim)}
.li{display:flex;flex-direction:column;gap:12px;height:100%}
.li p{margin:0;font-size:15px;line-height:1.55;color:var(--text)}
.li-src{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)}
.li-f{display:flex;gap:8px;margin-top:auto}
/* drawer */
.ldr-bg{position:absolute;inset:0;z-index:30;background:rgba(17,19,24,.18);opacity:0;pointer-events:none;transition:opacity .3s ease}
.ldr{position:absolute;top:0;right:0;bottom:0;z-index:31;width:min(400px,90%);display:flex;flex-direction:column;gap:16px;padding:20px;overflow-y:auto;background:var(--panel);border-left:1px solid var(--line);box-shadow:-24px 0 48px -24px rgba(17,19,24,.25);transform:translateX(104%);transition:transform .45s cubic-bezier(.16,1,.3,1)}
.la.drawer .ldr-bg{opacity:1;pointer-events:auto}
.la.drawer .ldr{transform:none}
.ldr-h{display:flex;align-items:center;gap:12px}
.ldr-h > div{flex:1}
.ldr-t{font-size:17px;font-weight:600;color:var(--text)}
.ldr-x{display:grid;place-items:center;width:32px;height:32px;color:var(--text-dim)}
.ldr-x:hover{background:var(--bg);color:var(--text)}
.ldr-kv{display:flex;flex-direction:column;border-top:1px solid var(--line)}
.ldr-kv > div{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:42px;border-bottom:1px solid var(--line);font-size:13px}
.ldr-kv > div > span:first-child{color:var(--muted)}
.ldr-kv > div > span:last-child{display:flex;align-items:center;gap:8px;font-weight:600;color:var(--text)}
.ldr-kv a{color:var(--accent);text-decoration:none}
.ldr-kv .dz-av,.ldr-kv .dz-av img{width:22px;height:22px}
.ldr-sec{font-family:var(--mono);font-size:11px;font-weight:700;text-transform:uppercase;color:var(--muted)}
.ldr-f{display:flex;gap:8px;margin-top:auto;padding-top:8px}
.ldr-f .bt{flex:1;justify-content:center}
/* Soft */
[data-style="soft"] .la-side{border-right:1px solid var(--line)}
[data-style="soft"] .la-logo{border-radius:9px}
[data-style="soft"] .la-ni,[data-style="soft"] .la-col{border-radius:10px}
[data-style="soft"] .la-ni.on{box-shadow:none}
[data-style="soft"] .lk,[data-style="soft"] .lc{border-radius:20px}
[data-style="soft"] .lf-ic,[data-style="soft"] .lt-lg{border-radius:9px}
[data-style="soft"] .lc-lib,[data-style="soft"] .lc-new{border-radius:999px}
[data-style="soft"] .lfu-bar,[data-style="soft"] .lfu-bar i{border-radius:7px}
[data-style="soft"] .lp-i,[data-style="soft"] .lp-i::before{border-radius:9px}
[data-style="soft"] .lc-tip{border-radius:12px}
[data-style="soft"] .ldr{border-radius:20px 0 0 20px}
[data-style="soft"] .lt-v,[data-style="soft"] .lfu-top b,[data-style="soft"] .lso-li b,[data-style="soft"] .lp-p,[data-style="soft"] .lp-i b,[data-style="soft"] .lf-time,[data-style="soft"] .la-c{font-family:var(--sans);font-weight:600}
[data-style="soft"] .lt-h,[data-style="soft"] .ldr-sec{font-family:var(--sans);text-transform:none;font-size:12px;font-weight:600}
[data-style="soft"] .lc-g text{font-family:var(--sans);font-weight:500}
@media (max-width:960px){
  .la{grid-template-columns:1fr}
  .la-side{display:none}
  .lk{grid-template-columns:1fr 1fr}
  .lk-i:nth-child(3){border-left:0}
  .lk-i:nth-child(n+3){border-top:1px solid var(--line)}
  .lg{grid-template-columns:1fr;grid-auto-rows:auto}
  .lc{grid-column:auto!important;grid-row:auto!important;min-height:280px}
  .la-tr .dm-avs,.la-tr .bt-secondary{display:none}
}
/* the assistant: hint on hover, slight tilt in flight */
.lab-hint{position:absolute;right:64px;bottom:16px;padding:6px 10px;border-radius:999px;background:var(--sh-ink);color:var(--sh-on-ink);font-size:12.5px;font-weight:600;white-space:nowrap;opacity:0;transform:translateX(6px);transition:opacity .2s ease,transform .3s cubic-bezier(.16,1,.3,1);pointer-events:none}
.lab-bot:not(.away) .lab-face:hover ~ .lab-hint,.lab-bot:not(.away):hover .lab-hint{opacity:1;transform:none}
.lab-bot .lab-face{order:2}
/* NEW chip next to The Lab */
.new-chip{position:relative;overflow:hidden;margin-left:2px;padding:1px 7px;border-radius:999px;background:#eaf2ff;color:#116ff8;font-size:10.5px;font-weight:700;letter-spacing:.02em;line-height:16px}
.new-chip::after{content:"";position:absolute;inset:0;background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,.85) 50%,transparent 70%);transform:translateX(-120%);animation:newShine 4s ease-in-out infinite 1s}
@keyframes newShine{0%{transform:translateX(-120%)}22%,100%{transform:translateX(120%)}}
html[data-theme="dark"] .new-chip{background:rgba(47,128,255,.18);color:#7fb0ff}
@media (prefers-color-scheme: dark){ html:not([data-theme="light"]) .new-chip{background:rgba(47,128,255,.18);color:#7fb0ff} }
html[data-theme="dark"] .new-chip::after{background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,.25) 50%,transparent 70%)}
@media (prefers-reduced-motion: reduce){ .new-chip::after{animation:none} }
.lso-c{pointer-events:none}
/* header logo a touch smaller so it sits level with the menu */
body.ui .top .brand{transform:scale(.88);transform-origin:left center}
.la-ni .la-nl,.la-col .la-nl{flex:1;text-align:left}
.la-ni span:first-of-type{flex:none}
.la.slim .la-ni span,.la.slim .la-col span{opacity:1;pointer-events:auto}
.la.slim .la-nl,.la.slim .la-c{opacity:0!important;pointer-events:none}
/* the drawer sits on the screen, wherever the dashboard is scrolled */
.ldr-bg{position:fixed;inset:0;z-index:30}
.ldr{position:fixed;top:68px;right:24px;bottom:20px;height:auto;border:1px solid var(--line);box-shadow:0 24px 64px -24px rgba(17,19,24,.35);transform:translateX(calc(100% + 40px))}
[data-style="soft"] .ldr{border-radius:22px}
.dm-chip span:first-of-type{flex:none}
.dm-chip > span:not(.ms):not(.dm-soon){flex:1;text-align:left}
@media (max-width:960px){ .lk-sp{display:none} .lk-v{font-size:21px} .la-top{flex-wrap:wrap} .la-body{padding:14px} .lc-b .dm-pipe{overflow-x:auto} }
/* new: kanban, funnel, top pages, ticket list */
.kb{width:100%;max-width:980px;padding:0;overflow:hidden}
.kb-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px 10px}
.kb-t{margin-top:2px;font-size:16px;font-weight:600;color:var(--text)}
.kb-hr{display:flex;align-items:center;gap:10px}
.kb-avs{display:flex}
.kb-avs .dz-av{margin-left:-6px;box-shadow:0 0 0 2px var(--panel)}
.kb-avs .dz-av:first-child{margin-left:0}
.kb-filters{display:flex;flex-wrap:wrap;gap:6px;padding:0 16px 12px}
.kb-chip{height:28px;padding:0 11px;border:1px solid var(--line);background:var(--panel);font-size:12.5px;font-weight:500;color:var(--text-dim);transition:background-color .2s,color .2s,border-color .2s}
.kb-chip:hover{color:var(--text);border-color:var(--icon-line)}
.kb-chip.on{background:var(--text);border-color:var(--text);color:var(--panel)}
.kb-cols{display:grid;grid-template-columns:repeat(4,minmax(180px,1fr));gap:10px;padding:0 16px 16px;overflow-x:auto}
.kb-col{display:flex;flex-direction:column;gap:8px;min-height:220px;padding:10px;background:var(--bg);border:1px solid transparent;transition:background-color .2s,border-color .2s}
.kb-col.over{border-color:var(--accent);background:var(--accent-bg)}
.kb-ch{display:flex;align-items:center;gap:8px;padding:2px 2px 4px;font-size:13px;font-weight:600;color:var(--text)}
.kb-ch i{width:8px;height:8px;flex:none;background:var(--c)}
.kb-n{margin-left:auto;padding:0 7px;border:1px solid var(--line);background:var(--panel);font-family:var(--mono);font-size:11px;font-weight:700;color:var(--text-dim)}
.kb-list{display:flex;flex-direction:column;gap:8px;flex:1}
.kb-card{display:flex;flex-direction:column;gap:10px;padding:12px;background:var(--panel);border:1px solid var(--line);cursor:grab;transition:border-color .2s,box-shadow .2s,opacity .2s}
.kb-card:hover{border-color:var(--icon-line);box-shadow:0 8px 20px -14px rgba(17,19,24,.35)}
.kb-card.drag{opacity:.35}
.kb-card.hide{display:none}
.kb-tags{display:flex;flex-wrap:wrap;gap:4px}
.kb-tag{display:inline-flex;align-items:center;gap:5px;padding:2px 7px;font-family:var(--mono);font-size:10.5px;font-weight:700;text-transform:uppercase;color:color-mix(in srgb,var(--tone) 78%,var(--text));background:color-mix(in srgb,var(--tone) 12%,var(--panel))}
.kb-tag.design{--tone:#7c5cff}.kb-tag.dev{--tone:#116ff8}.kb-tag.copy{--tone:#d98a00}.kb-tag.qa{--tone:#e5484d}.kb-tag.web{--tone:#159a63}.kb-tag.marketing{--tone:#0ea5a4}
.kb-ct{font-size:13.5px;font-weight:600;line-height:1.35;color:var(--text)}
.kb-done .kb-ct{color:var(--text-dim);text-decoration:line-through;text-decoration-color:var(--muted)}
.kb-prog{display:flex;align-items:center;gap:8px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted)}
.kb-prog b{flex:1;height:4px;background:var(--line);position:relative;overflow:hidden}
.kb-prog b i{position:absolute;inset:0 auto 0 0;width:var(--p);background:var(--accent-hi)}
.kb-meta{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted)}
.kb-due{white-space:nowrap;display:inline-flex;align-items:center;gap:4px;padding:1px 6px;border:1px solid var(--line);font-size:11.5px;font-weight:600;color:var(--text-dim)}
.kb-due.late{border-color:color-mix(in srgb,#e5484d 40%,transparent);color:#e5484d;background:color-mix(in srgb,#e5484d 8%,transparent)}
.kb-due .ms{font-size:13px}
.kb-meta .kb-cm{display:inline-flex;align-items:center;gap:3px}
.kb-meta .kb-cm .ms{font-size:13px}
.kb-who{display:flex;margin-left:auto}
.kb-who .dz-av,.kb-who .dz-av img{width:22px;height:22px}
.kb-who .dz-av{margin-left:-5px;box-shadow:0 0 0 2px var(--panel)}
.kb-who .dz-av:first-child{margin-left:0}
.kb-pri{width:8px;height:8px;border-radius:50%;background:#e5484d;box-shadow:0 0 0 3px color-mix(in srgb,#e5484d 18%,transparent)}
.kb-new{padding:10px;border:1px dashed var(--icon-line);font-size:12.5px;font-weight:500;color:var(--muted);text-align:left;transition:color .2s,border-color .2s}
.kb-new:hover{color:var(--text);border-color:var(--text-dim)}
[data-style="soft"] .kb{border-radius:22px}
[data-style="soft"] .kb-chip{border-radius:999px}
[data-style="soft"] .kb-chip.on{background:var(--ink);border-color:var(--ink);color:#fff}
[data-style="soft"] .kb-col{border-radius:16px}
[data-style="soft"] .kb-ch i{border-radius:50%}
[data-style="soft"] .kb-n{border-radius:999px;font-family:var(--sans);font-weight:600}
[data-style="soft"] .kb-card{border-radius:14px}
[data-style="soft"] .kb-tag{border-radius:999px;font-family:var(--sans);text-transform:none;font-size:11.5px;font-weight:600}
[data-style="soft"] .kb-prog{font-family:var(--sans);font-weight:600}
[data-style="soft"] .kb-prog b,[data-style="soft"] .kb-prog b i{border-radius:999px}
[data-style="soft"] .kb-due{border-radius:999px}
[data-style="soft"] .kb-new{border-radius:12px}
.kb-ct-w{display:flex;align-items:flex-start;gap:6px}
.kb-ct-w .kb-ct{flex:1;min-width:0;cursor:text;outline:0}
.kb-ct.editing{padding:2px 4px;margin:-2px -4px;background:var(--bg);box-shadow:inset 0 0 0 1px var(--icon-line)}
.kb-ed{display:grid;place-items:center;width:22px;height:22px;flex:none;color:var(--muted);opacity:0;transition:opacity .2s,color .2s}
.kb-card:hover .kb-ed{opacity:1}
.kb-ed:hover{color:var(--text)}
[data-style="soft"] .kb-ct.editing{border-radius:6px}
[data-style="soft"] .kb-ed{border-radius:6px}
.fn{width:100%;max-width:760px}
.fn .ch-head{align-items:flex-start}
.fn .ch-big{display:flex;align-items:baseline;gap:8px;margin-top:4px;font-size:26px;font-weight:600;letter-spacing:-.02em;color:var(--text)}
.fn .ch-sub{font-size:12.5px;font-weight:500;color:var(--muted);letter-spacing:0}
.fn-plot{position:relative;height:190px;overflow:hidden}
.fn-plot svg{display:block;width:100%;height:100%;overflow:visible}
.fn-sep{stroke:var(--line);stroke-width:1}
.fn-prev{fill:var(--accent-hi);opacity:.16}
.fn-cur{fill:url(#fn-grad)}
.fn-col{fill:transparent;cursor:default;transition:fill .2s}
.fn-col:hover{fill:color-mix(in srgb,var(--text) 4%,transparent)}
.fn-labs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-top:14px;border-bottom:1px solid var(--line)}
.fn-lab{display:flex;flex-direction:column;align-items:flex-start;gap:3px;min-width:0;padding:0 10px 10px}
.fn-lab + .fn-lab{border-left:1px solid var(--line)}
.fn-lab .mono-xs,.fn-lab b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.fn-lab .mono-xs{font-size:11px}
.fn-lab b{font-size:18px;font-weight:600;color:var(--text);letter-spacing:-.01em}
.fn-pc{align-self:flex-start;margin-top:2px;padding:1px 6px;font-family:var(--mono);font-size:10.5px;font-weight:700;color:var(--accent);background:var(--accent-bg)}
.fn-leg{display:flex;gap:16px;margin-top:10px;font-size:12px;color:var(--text-dim)}
.fn-leg span{display:inline-flex;align-items:center;gap:6px}
.fn-leg i{width:10px;height:10px}
.fn-leg i.cur{background:var(--accent-hi)}
.fn-leg i.prev{background:color-mix(in srgb,var(--accent-hi) 22%,var(--panel))}
[data-style="soft"] .fn-pc{border-radius:999px;font-family:var(--sans);font-weight:600}
[data-style="soft"] .fn-leg i{border-radius:3px}
.tpg{width:100%;max-width:520px;padding:0;overflow:hidden}
.tpg-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px 12px}
.tpg-t{margin-top:2px;font-size:16px;font-weight:600;color:var(--text)}
.tpg-list{display:flex;flex-direction:column;padding:0 8px 8px}
.tpg-r{position:relative;display:grid;grid-template-columns:22px 28px minmax(0,1fr) 64px 56px 52px;align-items:center;gap:10px;height:46px;padding:0 8px;cursor:default}
.tpg-r::before{content:"";position:absolute;inset:4px 0;width:var(--w,0%);background:var(--accent-bg);transition:width .7s cubic-bezier(.16,1,.3,1)}
.tpg-r:hover::after{content:"";position:absolute;inset:4px 0;border:1px solid var(--line);pointer-events:none}
.tpg-r > *{position:relative}
.tpg-rk{font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted)}
.tpg-ic{display:grid;place-items:center;width:28px;height:28px;background:var(--panel);border:1px solid var(--line);color:var(--text-dim)}
.tpg-ic .ms{font-size:15px}
