.lb-tag{position:absolute;z-index:6;top:-12px;left:12px;display:flex;align-items:center;gap:2px;padding:2px;border-radius:999px;background:var(--sh-ink);color:var(--sh-on-ink);opacity:0;transform:translateY(4px);transition:opacity .2s ease,transform .25s cubic-bezier(.16,1,.3,1);pointer-events:none}
