/* ========== Soft, simplifying pass ========== */
/* colour tags and chips keep their colour, without outlines */
:root[data-style="soft"]:is([data-theme],:not([data-theme])){--pb-line:transparent;--pl-line:transparent;--pm-line:transparent;--pp-line:transparent;--pr-line:transparent;--py-line:transparent;--pk-line:transparent;--pt-line:transparent}
:root[data-style="soft"][data-theme="dark"]{--pb-bg:rgba(90,150,255,.24);--pl-bg:rgba(155,125,255,.24);--pm-bg:rgba(70,205,150,.2);--pp-bg:rgba(255,155,80,.22);--pr-bg:rgba(255,105,130,.22);--py-bg:rgba(240,200,60,.2);--pk-bg:rgba(255,100,175,.2);--pt-bg:rgba(60,200,210,.2)}
@media (prefers-color-scheme: dark){ :root[data-style="soft"]:not([data-theme="light"]){--pb-bg:rgba(90,150,255,.24);--pl-bg:rgba(155,125,255,.24);--pm-bg:rgba(70,205,150,.2);--pp-bg:rgba(255,155,80,.22);--pr-bg:rgba(255,105,130,.22);--py-bg:rgba(240,200,60,.2);--pk-bg:rgba(255,100,175,.2);--pt-bg:rgba(60,200,210,.2)} }
