[data-style="soft"] :is(.cap,.kb-due,.kb-n,.ci-s,.retry,.dz-r,.cv-cur):not(.on):not(.run):not(.late){background-color:var(--chip)}
[data-style="soft"] .kb-chip:not(.on){border-color:transparent!important;background:var(--chip)}
[data-style="soft"] .mention{border:0;border-radius:6px;padding:0 5px;display:inline;line-height:inherit;height:auto}
/* status pill keeps its outline in every state */
:root[data-style="soft"] .sp{--pb-line:color-mix(in srgb,var(--accent) 26%,#fff);--pl-line:#ddd2ff;--pm-line:#bfead6;--pp-line:#ffd8b8;--pr-line:#ffcfd8;--py-line:#f4e3a0}
:root[data-style="soft"][data-theme="dark"] .sp{--pb-line:color-mix(in srgb,var(--accent) 34%,transparent);--pl-line:rgba(155,125,255,.32);--pm-line:rgba(70,205,150,.3);--pp-line:rgba(255,155,80,.32);--pr-line:rgba(255,105,130,.32);--py-line:rgba(240,200,60,.3)}
@media (prefers-color-scheme: dark){ :root[data-style="soft"]:not([data-theme="light"]) .sp{--pb-line:color-mix(in srgb,var(--accent) 34%,transparent);--pl-line:rgba(155,125,255,.32);--pm-line:rgba(70,205,150,.3);--pp-line:rgba(255,155,80,.32);--pr-line:rgba(255,105,130,.32);--py-line:rgba(240,200,60,.3)} }
/* thinner outlines everywhere: 0.5px */
[data-style="soft"] .stage *:not(.reason,.explain,.bt-spin,.agd-c,.ci-q,.pg-rd,[class*="spin"],.sp,.sp *,.ld2-pill,.ld2-pill *){border-width:.5px}
