function initInTabs(wrap, onChange){
  const ul = wrap.querySelector('.ul');
  const place = anim => { const sel = wrap.querySelector('[aria-selected="true"]'); if (!sel) return; ul.style.transition = anim ? '' : 'none'; ul.style.width = sel.offsetWidth + 'px'; ul.style.transform = `translateX(${sel.offsetLeft}px)`; };
  wrap.addEventListener('click', e => {
    const b = e.target.closest('.in-tab'); if (!b || b.getAttribute('aria-selected') === 'true') return;
    $$('.in-tab', wrap).forEach(t => t.setAttribute('aria-selected', t === b ? 'true' : 'false'));
    place(true); Sound.play('tab'); onChange(b.dataset.v);
  });
  place(false);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => place(false));
  addEventListener('resize', () => place(false));
}
function whenSeen(el, fn, th=.35){
  // outside designme.dev the component's card wrapper may not exist, so watch the page instead
  if (!el) el = document.querySelector('.stage-inner') || document.body;
  if (!('IntersectionObserver' in window)) return fn();
  const o = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting){ o.disconnect(); fn(); } }), {threshold:th});
  o.observe(el);
}
// glide a highlight block to an item inside a positioned list
function glide(hl, item, list){
  if (!item){ hl.style.opacity = '0'; return; }
  const r = item.getBoundingClientRect(), p = list.getBoundingClientRect();
  hl.style.height = r.height + 'px'; hl.style.transform = `translateY(${r.top - p.top}px)`; hl.style.opacity = '1';
}
function wordsHTML(text){ return text.split(' ').map(w => `<span class="w">${w}</span>`).join(' '); }
function revealWords(root, step=45, each){
  const ws = $$('.w', root); const ts = [];
  ws.forEach((w, i) => ts.push(setTimeout(() => { w.classList.add('in'); if (each) each(i); }, reduce ? 0 : i * step)));
  return { done: reduce ? 0 : ws.length * step, cancel: () => ts.forEach(clearTimeout) };
}

