const rng = seed => () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
const smooth = pts => { let d = `M${pts[0][0]},${pts[0][1]}`; for (let i = 1; i < pts.length; i++){ const [x0, y0] = pts[i-1], [x1, y1] = pts[i], cx = (x0 + x1) / 2; d += ` C${cx},${y0} ${cx},${y1} ${x1},${y1}`; } return d; };
function countTo(el, to, opts = {}){
  const from = +(el.dataset.v || 0), dur = reduce ? 1 : (opts.dur || 800), t0 = performance.now(), dec = opts.dec || 0, suf = opts.suf || '';
  el.dataset.v = to;
  const step = now => { const t = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - t, 3), v = from + (to - from) * e; el.textContent = (dec ? v.toFixed(dec) : Math.round(v).toLocaleString('en-US')) + suf; if (t < 1) requestAnimationFrame(step); };
  requestAnimationFrame(step);
}
const dayKey = d => d.getFullYear() + '-' + d.getMonth() + '-' + d.getDate();
